        }
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count > 0 {
            score += 3.0 * progress;
        }
        // Medium leftover with next item fitting inside is a strong chain start.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= 25 && new_left < 35 && next_item_size <= new_left {
