            score -= 1.5;
        }
        // Near-exact next-item closure is ideal, stronger late.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 1 && progress > 0.5 {
            score -= 1.5;
        }
        if post_residual > 12 && post_residual < 25 && next_item_size > post_residual {
            score += 1.0;
        }
        // Tighten: residual hosting next item twice is valuable when bins are scarce.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count <= 2 {
            score -= 1.0;
        }
        // Small residual that next item cannot use: mild penalty to prefer other bins.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 20 {
            score += (next_item_size - post_residual) as f64 * 0.06;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 8.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(3);

    // 2-step lookahead: strongly reward if the next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 14.0 * (1.0 - slack / (bin_capacity as f64));
        if slack == 0.0 {
            score -= 20.0; // perfect 2-step chain
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize wasted space relative to next item size.
        score += 3.0 * (next_item_size as f64 / (bin_capacity as f64));
    }

    // Relative-to-mean coupling: prefer bins whose residual is below average (tighter bins).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin only when no open bin offers a decent fit (post_residual small elsewhere)
        // and current item is large relative to capacity.
        let item_frac = item_size as f64 / bin_capacity as f64;
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score = 55.0 + 30.0 * item_frac - 12.0 * pressure;
        if next_item_size > 0 && (bin_capacity as u64 - item_size as u64) >= next_item_size as u64 {
            score -= 15.0; // new bin can also chain the next item
        }
        if fitting_bins_count <= 1 {
            score -= 10.0; // few alternatives -> new bin acceptable
        }
    }

    // Slight stream-progression modulation: later in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

