pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (1..=100) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable gap -> heavy penalty
    }
    // Residuals that can only fit very small items are semi-dead.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small post_residual) non-linearly.
    score -= 45.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize leaving medium gaps slightly less if gap is large
        score += 8.0;
    }

    // Compare against mean residual: bins with residual far from item fit are less attractive.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.3;

    // New-bin candidate: penalize opening a new bin unless current bins are crowded,
    // but keep it competitive when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64) * 0.4;
        if post_residual > 0 && post_residual < 10 {
            score += 30.0; // new bin would immediately create dead space risk
        }
        if fitting_bins_count == 1 {
            score += 90.0; // never open new bin when it's the only fitting open bin
        }
    }

    score
}

