        if next_item_size == post_residual {
            score -= 800.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            score -= 150.0 + 0.5 * next_item_size as f64; // next item can follow
        } else {
            // next item won't fit here; penalize small unusable leftovers
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 120.0 - 10.0 * waste; // tiny dead space is bad
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large or fits are scarce
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 250.0
            - 0.8 * item_size as f64
            - 20.0 * (fitting_bins_count as f64)
            - 100.0 * progress;
        if item_size >= 50 {
            score -= 80.0; // large items are fine in a fresh bin
