    // Prefer bins tighter than the mean residual (denser bins first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for very loose fits (large leftover relative to item)
    if post_residual > 0 && post_residual < item_size {
        score += 0.2 * post_residual as f64;
    }

    score
}

