        if post_residual >= 5 && post_residual <= 9 && next_item_size > 0 {
            score -= 0.8 + 0.6 * progress;
        }
        // G75: near-tight fits with multiple candidates — reward exact closeness.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 3 && fitting_bins_count >= 2 {
            score += 1.5 + 1.0 * progress;
        }
        // G75: post-residual in the mean band with a fit — slight reward.
        if next_item_size > 0 && post_residual > 0 && ((post_residual as f64) - mean_residual).abs() <= 2.0 && post_residual >= next_item_size {
            score -= 0.5 + 0.5 * progress;
        }
    }

    // G115: combined dead-space ratio with lookahead anticipation, applied
    // globally — penalize stranded space relative to capacity, scaled by
    // candidate scarcity; reward near-closed bins and empty-bin closure.
    let dead_space = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64
    } else {
        0.0
    };
    if dead_space > 0.0 {
        let dr = dead_space / bin_capacity.max(1) as f64;
        score += dr * 30.0;
        if dr < 0.03 {
            score -= 3.0;
        }
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += dead_space * (0.05 + 0.25 * scarcity);
        if post_residual == 0 && fitting_bins_count > 1 {
            score -= 2.0;
        }
    }
    // G115: reward bins whose post-residual chains the next item plus a
    // fillable sliver within half the mean residual (lookahead compaction).
    if next_item_size > 0 && post_residual >= next_item_size {
        let tail = post_residual - next_item_size;
        if tail > 0 && (tail as f64) <= mean_residual * 0.5 {
            score -= 0.8 + 0.8 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiny residuals are pure waste
    if post_residual > 0 && post_residual < 10 {
        score += 55.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 25 {
        score += (25 - post_residual) as f64 * 1.2;
    }

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 55.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward residuals that are multiples of 10 (likely to host future items)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead: next item chaining
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 22.0 - slack * 0.4;
            if next_item_size == post_residual {
                score -= 12.0;
            }
            let after = post_residual - next_item_size;
            if after % 10 == 0 {
                score -= 3.0;
            }
            if after > 0 && after < 10 {
                score += 3.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
            if next_item_size > bin_capacity / 2 {
                score += 6.0;
            }
        }
    }

    // Fill ratio: strongly reward tight fills of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 12.0;
    } else if fill_ratio > 0.75 {
        score -= 5.0;
    }

    // Drift from mean residual: mild penalty for deviating
    let drift = (post_residual as f64 - mean_residual).abs();
    score += drift * 0.05;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 1.5;

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - item_size as f64 * 0.5;
        // A fresh bin is attractive for large items when few alternatives exist
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 6.0;
        } else if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 2 {
            score -= 2.0;
        } else {
            score += 16.0;
        }
        // Late in the stream, mildly favor closing out with fresh bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 6.0;
    }

    score
}

