            }
        }
        if progress > 0.85 && post_residual > 0
            && (post_residual as f64) / (bin_capacity.max(1) as f64) <= 0.05 {
            score -= 2.0;
        }
        // GEN165: lookahead chain anticipation in existing bins — a residual
        // that can host the next item twice with a plausible small tail is a
        // near-perfect chain; reward scaled by scarcity of fitting bins.
        if next_item_size > 0 && post_residual >= next_item_size * 2 {
            let tail = post_residual - next_item_size * 2;
            if tail <= 6 && (tail as f64) <= mean_residual * 0.8 {
                let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
                score -= 1.0 + 1.0 * progress + 1.5 * scarcity;
