        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let dead_frac = (next_item_size - post_residual) as f64 / bin_capacity.max(1) as f64;
            let tightness = 1.0 - (mean_residual / bin_capacity.max(1) as f64).min(1.0);
            score += dead_frac * 12.0 * tightness;
        }
    }

    score
}

