            score += penalty * (0.5 + 0.5 * (1.0 - usable_ratio));
            let pressure = (mean_residual / bin_capacity.max(1) as f64).min(1.0);
            if pressure > 0.35 && fitting_bins_count >= 1 {
                score += (pressure - 0.35) * 10.0;
            }
        }
        if next_item_size > 0 && new_left >= next_item_size * 2 && new_left <= bin_capacity / 2 {
            score -= 1.5 + 1.0 * progress;
        }
        if progress > 0.85 && fitting_bins_count >= 1 && new_left > bin_capacity / 3 {
            score += 2.0 + 2.0 * (progress - 0.85) * 10.0;
        }
        if next_item_size > 0 && new_left >= next_item_size {
            let chain_gap = new_left - next_item_size;
            if (chain_gap as f64) <= mean_residual * 0.5 {
                score -= 1.0 + 0.5 * progress;
            }
        }
        // G95: new-bin tail reuse tiers.
        if next_item_size > 0 && new_left >= next_item_size {
            let tail = new_left - next_item_size;
            let tail_reuse = ((tail as f64) / mean_residual.max(1.0)).min(2.0);
            if tail_reuse >= 1.0 {
                score -= 0.6 + 0.6 * progress * tail_reuse * 0.5;
            } else if tail == 0 {
                score -= 2.0 + 1.5 * progress;
            } else {
                score += (next_item_size / 4 - tail.min(next_item_size / 4)) as f64 * 0.15;
            }
        }
        if new_left >= 5 && new_left <= 9 && fitting_bins_count >= 1 {
            score -= 1.0 + 0.8 * progress;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && (new_left as f64) <= mean_residual {
            score -= 1.2 + 0.9 * progress;
        }
        if fitting_bins_count >= 2 && (mean_residual as u32) <= item_size + 3 && item_size >= 10 {
            score += 1.0 + 1.0 * progress;
        }
        // G95 mutation: dead-space-aware new-bin decision.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let fresh_is_reusable = new_left >= next_item_size
                || (new_left % 10 == 0 && new_left >= 20 && new_left >= next_item_size / 2);
            let best_existing_strands = post_residual < next_item_size
                && (next_item_size - post_residual) <= 3;
            if fresh_is_reusable && best_existing_strands {
                score -= 2.0 + 2.0 * progress;
            }
            if new_left < 8 && new_left % 2 == 1 && new_left != next_item_size {
                score += 1.5;
            }
            if new_left >= next_item_size * 2 && next_item_size <= bin_capacity / 4 && open_bins_count <= 5 {
                score -= 1.2 + 1.2 * progress;
            }
            if (mean_residual as u32) >= next_item_size + 5 && new_left >= next_item_size && new_left > mean_residual as u32 * 2 {
                score += 1.0 + 0.8 * progress;
            }
            // GEN 164 mutation A: fresh bin whose leftover can host the next
            // item twice with a small round tail beats an existing bin that
            // would strand the next item entirely.
            if new_left >= next_item_size * 2 && (new_left - next_item_size * 2) <= 5
                && post_residual < next_item_size && fitting_bins_count >= 1 {
                score -= 1.2 + 1.2 * progress;
            }
            // GEN 164 mutation B: anti-dead-space — a fresh bin leaving a
            // residual too small for any typical item is heavily penalized.
            if new_left > 0 && new_left < 5 && new_left != next_item_size {
                score += 2.0 + 1.5 * progress;
            }
        }
        // GEN 164 mutation C: late-stream exact-fit closing — prefer existing
        // bins that fill to >= 95% near the end of the stream.
        if progress > 0.9 && fitting_bins_count >= 2
            && post_residual >= next_item_size && (post_residual - next_item_size) <= 6 {
            score -= 1.5 + 1.0 * (progress - 0.9) * 10.0;
        }
    } else {
        if fitting_bins_count > 3 && post_residual > 30 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 3.0;
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 1.5;
        }
        let band = (post_residual as f64 - mean_residual).abs();
        if band < 5.0 && post_residual >= next_item_size.max(1) {
            score -= 1.0;
        }
        if post_residual < next_item_size && post_residual < mean_residual as u32 {
            score += 2.0;
        }
        let fits_small = post_residual / 10;
        score -= fits_small as f64 * 3.0;
        if post_residual >= 10 && post_residual <= 20 && next_item_size > post_residual {
            score += 13.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 && post_residual > 20 {
            score -= 1.5;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < next_item_size / 2 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size >= next_item_size {
            score -= 1.0;
        }
        if post_residual > 12 && post_residual < 25 && next_item_size > post_residual {
            score += 1.0;
        }
        if post_residual >= 18 && post_residual <= 22 && next_item_size > post_residual {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= 10 && post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual as f64 > mean_residual * 0.8 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let twice_left = post_residual - next_item_size;
            if twice_left >= next_item_size.max(8) {
                score -= 1.0;
            }
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 10 && after <= 20 {
                score -= 1.0;
            }
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count >= 1 {
            score -= 1.0 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 1 && progress > 0.5 {
            score -= 1.5;
        }
        if post_residual > 0 && (post_residual as f64) < 0.05 * bin_capacity as f64 {
            score -= 2.0 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 20 {
            score += 1.5;
        }
        if next_item_size > 0 && post_residual >= 15 && post_residual <= 35 && post_residual % 5 == 0 && post_residual >= next_item_size {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual < next_item_size * 3 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 && progress > 0.6 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual > bin_capacity / 2 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && (post_residual - next_item_size) % 10 == 0 {
            score -= 1.0 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fitting_bins_count <= 3 {
            score -= 1.0 + 0.5 / (1.0 + fitting_bins_count as f64);
        }
        if next_item_size > 0 && post_residual >= 15 && post_residual < 20 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.04;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count <= 2 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual % 5 == 0 && fitting_bins_count <= 2 {
            score -= 0.5 + 0.5 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let stranded_gap = (next_item_size - post_residual) as f64;
            let near_close = item_size as f64 >= bin_residual as f64 * 0.85;
            if !near_close {
                score += stranded_gap * (0.10 + 0.15 * progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let dev2 = (post_residual as f64 - mean_residual).abs() / (mean_residual.max(1.0));
            score += dev2 * 1.5;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && post_residual >= next_item_size * 2 && post_residual < next_item_size * 3 && mean_residual > post_residual as f64 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 5 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= 10 && post_residual < 20 && post_residual < next_item_size {
            score += 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            if (post_residual as f64) < mean_residual * 0.5 {
                score += (next_item_size - post_residual) as f64 * 0.06;
            } else {
                score -= 0.4;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail == 0 {
                score -= 1.0 + 1.0 * progress;
            } else if tail <= next_item_size / 4 {
                score -= 0.8 + 0.8 * progress;
            } else if (tail as f64) > mean_residual * 1.2 {
                score += 0.5 + 0.5 * progress;
            }
        }
        if progress > 0.8 && post_residual == 0 {
            score -= 2.0 + 2.0 * (progress - 0.8) * 10.0;
        }
        if post_residual >= 5 && post_residual <= 9 && next_item_size > 0 {
            score -= 0.8 + 0.6 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 3 && fitting_bins_count >= 2 {
            score += 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && ((post_residual as f64) - mean_residual).abs() <= 2.0 && post_residual >= next_item_size {
            score -= 0.5 + 0.5 * progress;
        }
        // G95: dead-space ratio guard.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let waste_frac = (next_item_size - post_residual) as f64 / bin_capacity.max(1) as f64;
            if waste_frac > 0.08 {
                score += (waste_frac - 0.08) * 30.0;
            }
        }
        // GEN 164 mutation D: late-stream closing — existing bins that fill
        // to >= 95% near the end get a bonus, avoiding fresh-bin waste.
        if progress > 0.85 && post_residual > 0
            && (post_residual as f64) / (bin_capacity.max(1) as f64) <= 0.05 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny post_residual gaps are unusable dead space.
    if post_residual > 0 {
        let min_useful = 10u32; // smallest possible item size
        if post_residual < min_useful {
            score += 500.0; // absolute dead space: never leave a gap < min item
        } else if post_residual <= 20 {
            score += 40.0; // near-dead: only fit by very small items
        } else if post_residual <= 35 {
            score += 12.0; // awkward gap
        } else {
            // Larger leftovers are fine; mildly reward roomier leftovers.
            score -= 5.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin.
        score -= 200.0;
    }

    // Reward filling bins tightly: bigger fill fraction is better.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Open-bin pressure: when many bins are open, prefer consolidation into existing bins
    // over opening new ones (penalize the new-bin candidate).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).powf(1.3) * (1.0 + progress);
    score += 0.35 * pressure;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 120.0; // next item closes this bin perfectly
            } else if slack <= 15 {
                score -= 25.0; // next item leaves only a small gap
            } else {
                score -= 8.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 20.0; // leftover can't host next item: mild penalty
        }
    }

    // Prefer bins below mean residual (denser bins) slightly, to keep packing tight.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 60.0 * deadness * deadness;
