        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count >= 1 {
            score -= 1.0 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 1 && progress > 0.5 {
            score -= 1.5;
        }
        if post_residual > 0 && (post_residual as f64) < 0.05 * bin_capacity as f64 {
            score -= 2.0 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 20 {
            score += 1.5;
        }
        if next_item_size > 0 && post_residual >= 15 && post_residual <= 35 && post_residual % 5 == 0 && post_residual >= next_item_size {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual < next_item_size * 3 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 && progress > 0.6 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual > bin_capacity / 2 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && (post_residual - next_item_size) % 10 == 0 {
            score -= 1.0 + 1.0 * progress;
