pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 55.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward residuals that are multiples of 10 (likely reusable by common item sizes).
    if post_residual % 10 == 0 {
        score -= 10.0;
    }

    // Fine-grained residual fitting: reward reusable residual bands.
    let fits_small = post_residual / 10;
    score -= fits_small as f64 * 3.0;

    // Tight fill ratio reward.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 12.0;
    } else if fill_ratio > 0.75 {
        score -= 5.0;
    }
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * 2.0;

    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Lookahead: reward if next item fits; extra reward for exact fit.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 12.0;
            if next_item_size == post_residual {
                score -= 10.0;
            }
            let after = post_residual - next_item_size;
            if after > 0 && after < 10 {
                score += 3.0; // avoid leaving tiny sliver after next placement
            }
            if after >= next_item_size * 2 {
                score -= 2.0 + 2.0 * progress; // room for two more: strong lookahead
            }
            if after == 0 {
                score -= 4.0; // perfect two-item completion
            }
            if after % 10 == 0 && after > 0 {
                score -= 3.0; // clean residual after lookahead placement
            }
            if after > 0 && after < next_item_size {
                score += 1.5;
            }
            if post_residual >= mean_residual as u32 {
                score -= 1.5;
            }
        } else {
            score += 8.0;
            // If next item is large and won't fit here anyway, soften penalty.
            if next_item_size > bin_capacity / 2 {
                score -= 4.0;
            }
            // Dead-space ratio vs next item: penalize proportionally, with scarcity.
            let gap = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score += gap * (0.15 + 0.45 * scarcity);
            // Dead-space ratio penalty scaled to capacity.
            let dead_ratio = gap / bin_capacity as f64;
            score += dead_ratio * 42.0;
            if dead_ratio < 0.04 {
                score -= 4.0;
            }
            // Nearly full bin despite next item not fitting: still valuable.
            if post_residual + item_size >= bin_capacity * 9 / 10 {
                score -= 1.5;
            }
            // Stranded residual: small gap unusable by next item.
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += stranded * 18.0;
            if post_residual == 0 && fitting_bins_count > 1 {
                score -= 3.0; // perfectly closed bin, strong reward
            }
            if fitting_bins_count >= 2 {
                score += 2.0;
            }
        }
    }

    // Mean residual alignment.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    // Near-exact gap rewards.
    let exact_gap = bin_residual.saturating_sub(item_size);
    if exact_gap <= 2 {
        score -= 5.0;
    } else if exact_gap <= 5 {
        score -= 2.0;
    } else if exact_gap <= 9 {
        score -= 1.0;
    }

    // Perfect completion of this bin with current item.
    if item_size == bin_residual {
        score -= 4.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 4.0;
        } else if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 2 {
            score -= 1.0;
        } else {
            let new_left = bin_capacity.saturating_sub(item_size);
            if new_left % 10 == 0 && new_left >= 20 {
                score -= 4.0; // clean new-bin residual
            }
            if next_item_size > 0 && new_left == next_item_size {
                score -= 5.0; // set up exact next fit
            }
            if next_item_size > 0 && new_left >= next_item_size {
                let leftover = new_left - next_item_size;
                if leftover > 0 && leftover < 8 {
                    score -= 2.0;
                }
                if new_left >= next_item_size * 2 {
                    score -= 2.5;
                }
                if leftover > 0 && leftover < 10 && leftover % 10 != 0 {
                    score += 1.0; // awkward leftover after lookahead
                }
            }
            let sloppy = next_item_size > bin_capacity / 2 && new_left > bin_capacity / 3;
            if sloppy && item_size >= 40 {
                score -= 2.0;
            } else {
                score += 25.0 - pressure * 4.0;
            }
            // Small clean new-bin residual is nearly perfect.
            if new_left <= 3 {
                score -= 6.0;
            }
            // Late-stream: avoid opening extra bins when many fit elsewhere.
            if progress > 0.8 && item_size < bin_capacity / 2 {
                score += 6.0 * (progress - 0.8) * 10.0;
            }
            // Mid-stream: mild preference for existing bins.
            if progress > 0.6 && progress <= 0.8 {
                score += 2.0 * (progress - 0.6) * 10.0;
            }
            // Many fitting bins with slack: avoid opening a new one.
            if fitting_bins_count >= 3 && item_size <= bin_capacity / 3 {
                score += 3.0;
            }
            // Next item large and won't fit a small item's new residual anyway.
            if next_item_size >= bin_capacity * 2 / 5 && item_size <= bin_capacity / 3 {
                score += 4.0;
            }
            // Mean-residual slack in open bins: prefer them for small items.
            if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
                score += 2.5;
            }
            if fitting_bins_count > 0 && mean_residual > (new_left as f64) * 1.2 && item_size <= bin_capacity / 4 {
                score += 5.0;
            }
            // New-bin residual too small for next item: bad setup.
            if next_item_size > 0 && new_left < next_item_size && new_left < 15 {
                score += 3.0;
            }
            // Band 25-34 residual usable by next item: avoid opening.
            if new_left >= 25 && new_left < 35 && next_item_size > 0 && next_item_size <= new_left {
                score += 3.0;
            }
            if new_left >= 11 && new_left <= 19 && next_item_size > new_left {
                score += 2.0;
            }
        }
    } else {
        // Existing-bin refinements.
        if fitting_bins_count > 3 && post_residual > 30 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 3.0;
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 1.5;
        }
        let band = (post_residual as f64 - mean_residual).abs();
        if band < 5.0 && next_item_size > 0 && post_residual >= next_item_size.max(1) {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual < next_item_size && post_residual < mean_residual as u32 {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: quadratic in normalized post residual, modulated by progress
    let mut score = x * (1.0 - x) * 4.0; // peaks at half-full waste, low near 0 or full
    score = 1.0 - score; // low score when post residual near 0 (tight fit) or 0 (perfect)

    // Smooth polynomial coupling with progress: early stream prefers flexibility,
    // late stream prefers tight packing
    let coupling = (1.0 - progress) * x * x + progress * (1.0 - x) * (1.0 - x);
    score += 0.8 * coupling;

    // Non-linear interaction of post residual with mean residual
    let mr = mean_residual / cap;
    score += 0.3 * (x - mr) * (x - mr);

    // Last-chance bonus (smooth sigmoid-like weight)
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 2.0 * last_chance * (1.0 - x * x);

    // Lookahead: reward if next item fits the post residual (smooth margin term)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_next = (pr - ns).max(0.0) / cap;
        score -= 0.5 * fit_next * (1.0 - fit_next);
        let miss = ((ns - pr).max(0.0) / cap).min(1.0);
        score += 0.4 * miss * miss;
    }

    // Mild penalty for proliferating bins relative to progress
    score += 0.05 * open_bins_count as f64 / (total_items.max(1) as f64);

    // New-bin candidate: neutral-ish baseline with slight progress-dependent pull
    if bin_residual == bin_capacity {
        score = 1.2 - 0.5 * progress + 0.3 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: minimize wasted space nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 40.0;

    // Penalize dead space quadratically (small post-residuals are most valuable).
    let pr = post_residual as f64;
    score += (pr / bin_capacity as f64).powi(3) * 60.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly placement, but only if leftover isn't too tight.
            score -= 12.0;
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score += 6.0; // near-perfect chain completion
            }
        } else {
            // Post-residual becomes dead space for the next item.
            score += 8.0;
        }
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual.max(0.0);
        // Open a new bin if mean residual is too small to be useful, or many bins already open.
        if avg_waste < item_size as f64 * 1.2 || open_bins_count > 12 {
            score -= 30.0;
        } else {
            score += 25.0 + avg_waste * 0.1;
        }
    } else {
        // Mild preference for filling already-open bins as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
        // Slight penalty when many bins are open to encourage consolidation.
        score += open_bins_count as f64 * 0.3;
    }

    // Prefer bins whose residual is above average (keeps flexible bins for later).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step fit: post_residual exactly matches next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual relative to next item size: penalize waste larger than next item
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff > 0.0 {
            // dead space beyond what the next item can consume
            score += diff * 0.4;
        } else {
            // next item still fits here afterwards: mild reward
            score += diff * 0.15;
        }
    }

    // Compare post_residual against mean residual: avoid creating outlier dead space
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - pr) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable slivers (< 10, min item size)
    if post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        // new bin is bad if any open bin could fit (fragmentation low means residuals tight)
        score = 70.0 + fragmentation * 30.0 - (open_bins_count as f64) * 0.5;
        if fitting_bins_count <= 1 {
            // nothing else fits: opening a new bin is fine
            score -= 60.0;
        }
    }

    // Tight-fill reward: item fills most of the bin
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

