pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near multiples of common item sizes
    // are more likely to be filled by future items.
    let pr = post_residual as u32;
    let mut harmony: f64 = 0.0;
    for &m in &[10u32, 20, 25, 50] {
        let r = (pr % m) as f64;
        let closeness = (m as f64 / 2.0 - r).abs() / (m as f64 / 2.0); // 0 = exact half, 1 = at multiple
        harmony += closeness;
    }
    harmony /= 4.0;

    // Reward bins whose post_residual sits in a "harmonic" class (low score).
    score -= 12.0 * harmony;

    // Exact-fill class: post_residual exactly divisible by common sizes -> very attractive.
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 4.0; }
    } else {
        // Perfect fill is the best outcome.
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (-slack / 20.0).exp();
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers less mildly
            score += 0.02 * (pr as f64);
        }
    }

    // Dead-space penalty: leftover too small for the smallest conceivable item.
    if pr > 0 && pr < 5 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it if all open bins would leave big dead space.
    if bin_residual == bin_capacity {
        let best_possible_waste = if item_size <= bin_capacity { 0.0 } else { cap };
        let avg_waste_if_open = mean_residual - item_size as f64;
        score = cap * 0.55 + 0.3 * avg_waste_if_open.max(0.0) - best_possible_waste;
        if fitting_bins_count == 0 {
            score -= cap; // must open a bin
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 6.0; // new bin can host the next item cleanly
        }
    }

    // Mild normalization toward fraction of capacity wasted.
    score += 0.1 * (post_residual as f64 / cap) * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residual gaps that are too small
    // to be useful for future items (typical small items are <= 30).
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 1.5;
    }
    // Perfect or near-perfect fits are highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item won't fit here; mild penalty
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // (the new-bin candidate has bin_residual == bin_capacity, gets penalized).
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 2.0;
    } else {
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Progress: early in the stream, be slightly more willing to pack tightly
    // into existing bins; later, avoid fragmentation more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.3 * progress;

    // Prefer bins whose residual is close to the item (tight fit signal).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact/tight fits
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (unusable gap)
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * (10.0 - pr) * 2.0;
        }
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= n {
            // next item fits here afterwards: reward closeness of match
            score -= 60.0 - 0.5 * (pr - n);
            if (pr - n).abs() < 5.0 {
                score -= 40.0; // near-perfect 2-step chain
            }
        } else if pr > 0.0 && pr < n {
            // post residual too small for next item: penalize proportionally
            score += (n - pr) * 1.5;
        }
    } else {
        // last item: just minimize leftover
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins already below-average residual
    // (compact bins get compacted further), penalize draining large-residual bins.
    let mr = mean_residual;
    let pr = post_residual as f64;
    if pr < mr {
        score -= (mr - pr).min(50.0) * 0.8;
    } else {
        score += (pr - mr).min(50.0) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only open a new bin when item is large relative
    // to residuals of open bins (i.e., poor fit everywhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base penalty so open bins are preferred unless fit is bad
        score += 120.0;
        // large items open bins more readily; small items should fill gaps
        let large = (item_size as f64) > 60.0;
        if large {
            score -= 90.0;
        }
        // early stream: opening bins is cheaper
        score -= (1.0 - progress) * 30.0;
        // if next item is huge, reserving a fresh bin is fine
        if next_item_size >= 70 {
            score -= 25.0;
        }
        // if many open bins with high mean residual, opening new bin is wasteful
        if mean_residual > 40.0 && open_bins_count > 2 {
            score += 60.0;
        }
    }

    // Mild tie-break: prefer bins with more residual consumed overall
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post-residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: heavily penalize opening a new bin unless
    // nothing fits well (large post_residual waste vs. best fit).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 60.0 + 0.5 * open_bins_count as f64;
        // Early in the stream, opening fresh bins is cheaper (future packing freedom).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 70.0 * (1.0 - progress) * (1.0 - progress);
        // If current item is large, a fresh bin is more attractive.
        score -= 0.3 * item_size as f64;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 35.0;
        } else if diff > 0 && (diff as u32) < 10 {
            score -= 15.0;
        } else if diff < 0 && (diff as u32) >= 10 {
            // Next item would not fit here anyway; mild bonus for keeping space useful.
            score += 5.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidation
    // into bins below the mean residual (i.e., tighter bins).
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
    }

    // Late in the stream, minimize waste aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: favor small post-residual, with non-linear sharpening over time.
    let norm_pr = pr / cap;
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr);

    // Smooth polynomial coupling: penalize mid-range residuals more as stream advances.
    let quad = norm_pr * (1.0 - norm_pr); // peaks at half-full residual
    score += 8.0 * progress * quad;

    // Dead-space penalty: residual too small for the smallest plausible item.
    if pr > 0 && pr < next_item_size.max(10) {
        score += 6.0 * (1.0 - pr / next_item_size.max(10) as f64);
    }

    // Lookahead: reward bins that leave room for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_quality = 1.0 - ((pr - nx) / cap);
            score -= 3.0 * fit_quality * (1.0 - progress);
        } else {
            score += 2.0 * progress;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Late stream: prefer filling existing bins over opening new ones.
    score += 0.4 * (open_bins_count as f64) * progress;

    // Mild preference toward bins near the mean residual (balance).
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: smooth escalating penalty so it's chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual w.r.t. capacity quarters: dead space classes
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..4 integer class
    // Reward tight fits (class 0 = post_residual < 25): strong subtraction
    match class {
        0 => score -= 40.0,
        1 => score -= 10.0,
        2 => score += 5.0,
        3 => score += 15.0,
        _ => {}
    }

    // Exact fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling with next item: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // partial fit: penalize leftover after next item being tiny (wasted)
            let next_left = post_residual - next_item_size;
            let nl_class = next_left / quarter;
            if nl_class == 0 {
                score -= 20.0;
            } else {
                score += 10.0 * nl_class as f64;
            }
        } else {
            // next item won't fit here: penalize proportionally to wasted residual
            score += 0.3 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer reusing,
    // unless residual here is very large (poor fit) — then empty bin becomes attractive.
    if bin_residual == bin_capacity {
        score += 15.0;
        // if mean residual across open bins is large, opening new bin is fine
        score -= 0.2 * mean_residual;
    }

    // Progress: later in the stream, be more conservative with dead space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 % 10.0);

    // Discourage many open bins with small residuals (fragmentation)
    if open_bins_count > 4 && post_residual < quarter {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into more bins.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * 2.0;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual alignment: prefer bins near the mean residual (balanced use).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    // New-bin candidate: only attractive when no open bin fits well or many bins already open.
    if bin_residual == bin_capacity {
        score += 25.0 - pressure * 4.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-perfect matches (next item fits with little waste).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot follow in this bin: penalize proportionally to how far off.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.3 * gap;
    }

    // Penalize tiny unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: prefer bins whose post-residual deviates
    // favorably (smaller) from the mean; penalize creating outliers above mean.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.5 * (pr - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - pr);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (full residual is a fresh slate; base score = capacity is high, so it
    // naturally loses unless bonuses above make open bins unattractive).
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Early in stream, slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
