pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    // Early: prefer tight fills (penalize large residuals quadratically).
    // Late: residual becomes less costly; linear term dominates.
    let mut score = pr
        + norm_pr * norm_pr * (1.0 - progress) * 30.0
        - norm_pr * progress * 12.0;

    // Smooth dead-space term: residuals that are too small to ever be useful
    // (below typical minimum item size) are heavily penalized, smoothly.
    let min_item = 1.0f64;
    let dead = ((min_item - pr).max(0.0) / cap).powi(2) * 100.0;
    score += dead;

    // Coupling with lookahead: if next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= (1.0 - gap / cap).max(0.0).powi(3) * 15.0;
        // If next item cannot fit post-residual, mildly penalize tight fits.
        score += (nxt - pr).max(0.0) / cap * 8.0 * progress;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty proportional to bin scarcity relative to mean residual.
    let scarcity = (open_bins_count as f64).ln().max(1.0);
    score += (mean_residual - pr).abs() / cap * 4.0 / scarcity;

    // Slight reward for high fill ratio, smoothly scaled by progress.
    score -= (1.0 - norm_pr) * (1.0 + progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "useful" residue classes (multiples of 10, small leftovers) are favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual is a multiple of 10 -> highly reusable.
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    // Class B: post_residual in [1..9] -> nearly perfect fit, tiny dead space.
    if post_residual < 10 {
        score -= 25.0;
    }
    // Class C: dead-space penalty for unusable mid-range leftovers (11..19),
    // which few items (10..80) can still use.
    if post_residual >= 11 && post_residual <= 19 {
        score += 15.0;
    }

    // Integer-division threshold on post_residual: how many "typical" items fit.
    let fits_small = post_residual / 10;
    score -= fits_small as f64 * 3.0;

    // Lookahead coupling: reward if next_item_size fits into post_residual
    // (chain packing), penalize if next item would exactly fill it (waste of chain).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // Harmonic: exact harmonic match next == post_residual is ideal
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else {
            score += 5.0;
        }
        // Next item is large: prefer bins leaving big residuals for it.
        if next_item_size > bin_capacity / 2 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when the fit here is poor (large post_residual) or many bins are open.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = cap * 0.55;
        // If the current stream is early, opening bins is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // If many open bins already, discourage opening another.
        score += open_bins_count as f64 * 1.5;
        // If mean residual is large, we should reuse instead of opening.
        score += mean_residual * 0.3;
        // If this is the only fitting option, opening a new bin is acceptable.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Tight-fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    }

    // Mild preference for bins below mean residual (balancing residuals).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Reward tight fits in the usable range.
        score -= 0.3 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;
    }

    // Dead space is only "wasted" if no future item can use it.
    if post_residual > 0 && (next_item_size as u32 > post_residual || next_item_size == 0) {
        score += 15.0;
    } else if post_residual > 0 && next_item_size as u32 <= post_residual {
        // Gap usable by the lookahead item: reward.
        score -= 10.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize relative to mean residual of open bins,
    // unless open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * mean_residual;
        // If nothing fits well, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Slight late-stream tightening: keep bins closed as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
