    }

    // Penalize bins far below mean residual (fragmentation avoidance)
    score += 0.15 * ((bin_residual as f64 - mean_residual) * (bin_residual as f64 - mean_residual)).sqrt();

    // Discourage opening new bins when a decent fit exists among open bins
    if bin_residual == bin_capacity {
        score += 12.0 + 0.2 * open_bins_count as f64;
    }

    // Late in the stream: consolidate, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: fill bins snugly (small post_residual preferred).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize dead space that is too small to ever fit the smallest item (size 1..10 range unknown; use 10 as safe floor).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // existing fits are poor (large post_residual) or bins are scarce.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin grows with stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 20.0 * progress;
        // If many bins are open with slack, discourage opening yet another.
        score += 2.0 * open_bins_count as f64;
        // But if no open bin fits well, allow opening (score naturally competes).
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Global residual pressure: if mean residual is low, conserve space in open bins.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.05 * mean_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: polynomial in normalized post_residual times stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let poly = prn * prn * (1.0 - prn) + 0.5 * prn * (1.0 - prn) * (1.0 - prn);
    score += poly * cap * (0.5 + 2.0 * progress);

    // Favor tight fits: reward small post_residual non-linearly
    score -= (1.0 - prn) * (1.0 - prn) * (1.0 - prn) * 20.0;

    // Last-chance bin: strong penalty for opening new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // New-bin candidate: penalize mildly unless post_residual would be huge waste elsewhere
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
        // look ahead: opening new bin is good if next item fits perfectly in fresh bin
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            score -= 0.3 * nxt;
        }
    } else {
        // lookahead synergy: reward if next item fits into resulting post_residual
        if next_item_size > 0 && next_item_size as f64 <= pr {
            score -= 10.0 * (pr - next_item_size as f64) / cap;
        }
    }

    // Penalize bins with residual far from mean residual (non-linear dispersion term)
    let dev = pr - mean_residual;
    score += 0.1 * dev * dev / cap;

    // Mild reward for consolidating into fewer bins when many are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - prn);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity/4 quarters
    let quarter = bin_capacity / 4; // 25
    let residue = post_residual % quarter;
    // Reward post-residuals that land on "nice" harmonic grid points (0, quarter multiples)
    let align = residue as f64 / quarter as f64; // 0..1
    score -= 6.0 * (1.0 - align); // aligned post-residuals are more reusable

    // Integer-division threshold classes on post_residual
    let class = post_residual / quarter; // 0..4
    match class {
        0 => score -= 4.0,  // very tight fill, great
        1 => score += 1.0,  // small leftover
        2 => score += 3.0,  // medium leftover
        3 => score += 5.0,  // large leftover, wasteful
        _ => score += 0.0,  // untouched bin
    }

    // Dead-space penalty: post_residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Next-item coupling: reward if next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - slack / bin_capacity as f64);
            // Harmonic bonus: next item leaves a quarter-aligned residual
            let nres = post_residual - next_item_size;
            if nres % quarter == 0 {
                score -= 3.0;
            }
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Penalize spreading when many bins are open and mean residual is high
    if open_bins_count > 2 {
        let tightness = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * tightness;
    }

    // New-bin candidate logic: empty bin gets a baseline score
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only late in stream or when fit elsewhere is bad
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 20.0 * progress;
        // But if the item is large relative to capacity, new bin is attractive
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // pair next item in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits via post_residual, with non-linear dead-space penalty
    let pr = post_residual as f64;
    score += pr;

    // Strict dead-space avoidance: residuals that are too small to ever host
    // a meaningful future item (typical min item size ~1..10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 25 {
        // mid-range gap: mildly risky
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.5; // reward chaining, more if next fits snugly
    }
    // If next item is large and this bin cannot host it after placement, slight penalty
    if next_item_size > post_residual && next_item_size > 50 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 2.0;

    // New-bin candidate: opening a new bin should lose unless the current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: nearly full cost of capacity
        score = bin_capacity as f64 - item_size as f64 * 0.5;
        // If existing options are terrible (item leaves unusable gap in every bin,
        // or this is a last-chance situation we want to avoid wasting), allow opening.
        if post_residual < 10 || (fitting_bins_count == 1 && bin_residual < bin_capacity) {
            // fitting_bins_count==1 impossible here (new bin), but keep guard simple
        }
        // If the item is large relative to capacity, a fresh bin is attractive
        if item_size >= 60 {
            score -= 15.0;
        }
        // Late in stream, prefer closing out with new bins rather than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-match: next item fits into the post residual comfortably.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward proportional to how snugly the next item fits (small slack left after both).
        let slack_after_next = post_residual as f64 - next_item_size as f64;
        score -= 12.0 * (1.0 - slack_after_next / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item cannot follow into this bin: penalize proportionally to the gap.
        if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / 100.0).min(1.0);
        }
    }

    // Compare post residual against mean residual across open bins:
    // leaving post_residual far below mean wastes capacity relative to the fleet.
    let mean = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    let diff = post_residual as f64 - mean;
    if diff > 0.0 {
        // Post residual larger than mean -> this bin retains more usable space: mild reward.
        score -= 3.0 * (diff / bin_capacity as f64);
    } else {
        // Post residual below mean -> creates dead space relative to others: penalize.
        score += 5.0 * (-diff / bin_capacity as f64);
    }

    // Tight fit bonus: item nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 8.0 * (fill_ratio - 0.9);
    } else if fill_ratio < 0.4 {
        // Spreading a small item into a large residual wastes the bin.
        score += 4.0 * (0.4 - fill_ratio);
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a good 2-step fit, or the fleet is very fragmented.
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0 && fitting_bins_count > 0;
        let fragmentation = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        if good_fit_exists && fragmentation < 0.5 {
            score += 25.0; // discourage opening a new bin when fits exist
        } else {
            score -= 5.0; // allow fresh bin when stream is fragmented or no fits
        }
        // A fresh bin always has maximal residual; counteract the base residual advantage
        // unless the item is huge and leaves a clean structured space.
        if item_size <= bin_capacity / 2 {
            score += 6.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
