}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling with stream progress: late in the stream,
    // tightness matters more; early on, be more tolerant of slack.
    let progress_coupling = (1.0 + 2.0 * progress + 3.0 * progress * progress) * norm_pr * norm_pr * norm_pr;
    score += 60.0 * progress_coupling;

    // Penalize dead space relative to mean residual of open bins (smooth quadratic).
    let slack_gap = pr - mean_residual;
    score += 0.15 * slack_gap * slack_gap;

    // Reward last-chance bins (fitting_bins_count == 1) smoothly.
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 25.0 * last_chance * (1.0 + progress);

    // Lookahead: penalize if post_residual can't fit next item, reward if it can.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 12.0 + 8.0 * (nxt - pr) / cap;
        } else {
            score -= 6.0 * (1.0 - (pr - nxt) / cap).max(0.0);
        }
    }

    // New-bin candidate: mild penalty so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: dead-space classes mod 10
    let cls = post_residual % 10;
    // Small post-residuals are valuable leftovers; large ones are dead space
    match cls {
        0 => score -= 8.0,          // leftover usable by many item sizes
        1 => score -= 6.0,
        2 => score -= 5.0,
        3 => score -= 3.0,
        4 => score -= 1.0,
        5 => score += 2.0,          // awkward half-class
        6 => score += 3.0,
        7 => score += 5.0,
        8 => score += 7.0,
        _ => score += 9.0,          // 9 mod 10 hard to fill
    }

    // Integer-division thresholds on post_residual
    let half = bin_capacity / 2;
    if post_residual > half {
        // leaves more than half a bin empty -> strong penalty unless bin was nearly empty
        score += (post_residual - half) as f64 * 0.6;
    } else if post_residual <= bin_capacity / 10 {
        // tiny leftover: nearly perfect packing
        score -= 15.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // great: chain placement possible, reward proportional to lookahead use
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else if next_item_size == post_residual {
            score -= 40.0; // exact chain fit
        } else {
            // next item won't fit here; penalize more if leftover is dead space
            score += (next_item_size - post_residual).min(30) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins overall (residual close to item size means tight fit)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Slight preference to keep few open bins when mean residual is high
    score += mean_residual * 0.05;

    // New-bin candidate: only attractive when item is large and no tight fit exists
    if bin_residual == bin_capacity {
        if item_size >= bin_capacity * 3 / 4 {
            score -= 5.0; // big item: fresh bin fine
        } else {
            score += 25.0; // small item: prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual is a multiple of 10 -> highly reusable.
