    if post_residual < 10 {
        score -= 25.0;
    }
    // Class C: dead-space penalty for unusable mid-range leftovers.
    if post_residual >= 11 && post_residual <= 19 {
        score += 15.0;
    }

    // How many "typical" small items still fit.
    let fits_small = post_residual / 10;
    score -= fits_small as f64 * 3.0;

