            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: gate opening on stream position, crowding,
    // and how wasteful the best existing fit would be.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, scaled by how much space would be wasted
        // by placing the item in an existing bin instead.
        score = cap * 0.55;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Late in the stream, prefer reusing existing bins harder.
        score -= progress * 18.0;
        // Crowding penalty grows superlinearly with open bins.
        score += open_bins_count as f64 * open_bins_count.max(1) as f64 * 0.12;
        // Large mean residual => plenty of slack available elsewhere.
        score += mean_residual * 0.35;
        // If this is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if fitting_bins_count == 1 {
            // Exactly one alternative: only open if that fit would be terrible.
            score += 12.0;
        }
        // Big item in a fresh bin wastes less relatively; ease the cost.
        let item_ratio = item_size as f64 / cap;
        if item_ratio > 0.6 {
            score -= (item_ratio - 0.6) * 40.0;
        }
    }

    // Tight-fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
