    } else if fill_ratio > 0.75 {
        score -= 4.0;
    }

    // Mild preference for bins below mean residual (balancing residuals).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Exact-fill bonus: item perfectly consumes the bin residual.
    if item_size == bin_residual {
        score -= 15.0;
    }

    score
}

