    if fill_ratio > 0.9 {
        score -= 12.0;
    } else if fill_ratio > 0.75 {
        score -= 5.0;
    }
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * 2.0;

    // Lookahead: reward if next item fits; extra reward for exact fit.
