                score -= 4.0;
            }
            // Stranded small residual.
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += stranded * 18.0;
            if post_residual == 0 && fitting_bins_count > 1 {
                score -= 3.0;
            }
