            }
            if post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
                score += 5.0;
            }
        }
    }

    // Mean residual alignment.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    // Near-exact gap rewards.
    let exact_gap = bin_residual.saturating_sub(item_size);
    if exact_gap <= 2 {
        score -= 5.0;
    } else if exact_gap <= 5 {
        score -= 2.0;
    } else if exact_gap <= 9 {
        score -= 1.0;
    }

    // Perfect completion of this bin with current item.
    if item_size == bin_residual {
        score -= 4.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 4.0;
        } else if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 2 {
            score -= 1.0;
        } else {
            let new_left = bin_capacity.saturating_sub(item_size);
            if new_left % 10 == 0 && new_left >= 20 {
                score -= 4.0;
            }
            if next_item_size > 0 && new_left == next_item_size {
                score -= 5.0;
            }
            if next_item_size > 0 && new_left >= next_item_size {
                let leftover = new_left - next_item_size;
                if leftover > 0 && leftover < 8 {
                    score -= 2.0;
                }
                if new_left >= next_item_size * 2 {
                    score -= 2.5;
                }
                if leftover > 0 && leftover < 10 && leftover % 10 != 0 {
                    score += 1.0;
                }
            }
            let sloppy = next_item_size > bin_capacity / 2 && new_left > bin_capacity / 3;
            if sloppy && item_size >= 40 {
                score -= 2.0;
            } else {
                score += 20.0 - pressure * 4.0;
            }
            if new_left <= 3 {
                score -= 6.0;
            }
            // Late-stream: avoid opening extra bins when many fit elsewhere.
            if progress > 0.8 && item_size < bin_capacity / 2 {
                score += 6.0 * (progress - 0.8) * 10.0;
            }
            // Mid-stream: mild preference for existing bins.
            if progress > 0.6 && progress <= 0.8 {
                score += 2.0 * (progress - 0.6) * 10.0;
            }
            if fitting_bins_count >= 3 && item_size <= bin_capacity / 3 {
                score += 3.0;
            }
            if next_item_size >= bin_capacity * 2 / 5 && item_size <= bin_capacity / 3 {
                score += 4.0;
            }
            if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
                score += 2.5;
            }
            if fitting_bins_count > 0 && mean_residual > (new_left as f64) * 1.2 && item_size <= bin_capacity / 4 {
                score += 5.0;
            }
            if next_item_size > 0 && new_left < next_item_size && new_left < 15 {
                score += 3.0;
            }
            if next_item_size > 0 && new_left < 10 && next_item_size > new_left {
                score += 4.0;
            }
            if new_left >= 25 && new_left < 35 && next_item_size > 0 && next_item_size <= new_left {
                score += 3.0;
            }
            if new_left >= 11 && new_left <= 19 && next_item_size > new_left {
                score += 2.0;
            }
            // NEW: strong pressure to keep existing bins when slack matches item.
            if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
                score += 3.5 + 1.5 * progress;
            }
            // NEW: discourage new bins whose residual won't hold next item mid-stream.
            if next_item_size > 0 && new_left < next_item_size && progress > 0.5 {
                score += 2.0;
            }
        }
    } else {
        // Existing-bin refinements.
        if fitting_bins_count > 3 && post_residual > 30 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual == 0 {
            score -= 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 3.0;
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 1.5;
        }
        let band = (post_residual as f64 - mean_residual).abs();
        if band < 5.0 && next_item_size > 0 && post_residual >= next_item_size.max(1) {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual < next_item_size && post_residual < mean_residual as u32 {
            score += 2.0;
        }
        // NEW: near-complete bin with next-item-compatible leftover is valuable.
        if next_item_size > 0 && post_residual > 0 && post_residual + item_size >= bin_capacity * 95 / 100 {
            score -= 2.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, waste matters more (quadratic ramp)
    let urgency = progress * progress;
    score *= 1.0 + 0.5 * urgency * norm_pr;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 20.0 * urgency * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize bins far below mean residual (wasteful use of roomy bin)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - urgency);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * urgency;
    } else {
        // mild penalty when many bins compete (encourage consolidation)
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: penalize if post_residual cannot fit next item (dead space risk)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 8.0 * urgency * (ni - pr) / cap;
        } else {
            score -= 4.0 * (1.0 - urgency) * (ni / cap);
        }
    }

    // New-bin candidate: make it slightly unattractive unless it's a large item
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap;
        score += 6.0 - 12.0 * big * big;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual is a
    // "clean" fraction of capacity are more reusable. Classify post_residual
    // into residue classes modulo small integers.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class reward: post_residual divisible by common item granules
    // (5, 10, 20, 25, 50) means future items can tile the leftover exactly.
    if post_residual > 0 {
        if post_residual % 50 == 0 { score -= 60.0; }
        else if post_residual % 25 == 0 { score -= 45.0; }
        else if post_residual % 10 == 0 { score -= 30.0; }
        else if post_residual % 5 == 0 { score -= 15.0; }
        else { score += 10.0; } // awkward leftover
    }

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or nearly: strong reward
            if next_item_size == post_residual {
                score -= 120.0;
            } else {
                score -= 25.0 + 0.5 * (next_item_size as f64);
                // harmonic bonus if pair (post_residual - next) is clean
                let tail = post_residual - next_item_size;
                if tail % 10 == 0 { score -= 15.0; }
            }
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += 8.0 + 0.15 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
        if post_residual == 0 { score -= 50.0; }
    }

    // New-bin candidate handling: an empty bin is attractive early or when
    // the item is huge (poor fit anywhere), unattractive when many open bins
    // exist and the item is small.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let huge_item = (item_size as f64) > 0.6 * cap;
        if huge_item {
            score -= 70.0; // big items deserve fresh space
        } else {
            score += 35.0 + 20.0 * (open_bins_count as f64).ln().max(0.0) + 25.0 * progress;
        }
        // if next item is also huge, opening now keeps flexibility
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * cap {
            score -= 30.0;
        }
    }

    // Prefer filling bins that are already relatively full (small residual
    // relative to mean): tightens packing and keeps slack concentrated.
    if bin_residual != bin_capacity {
        let tightness = 1.0 - (bin_residual as f64) / cap;
        score -= 12.0 * tightness;
        // penalize bins far above mean residual (wasteful use of loose bins)
        if (bin_residual as f64) > mean_residual + 30.0 {
            score += 10.0;
        }
    }

    // Mild preference for fewer open bins late in the stream.
    score += 0.05 * (open_bins_count as f64) * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    // A post_residual that cannot fit even the smallest plausible item is dead space.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    } else if post_residual <= 35 {
        score += 8.0;
    }

    // Reward tight fits (post_residual small relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing bins
    // over opening new ones.
    if bin_residual < bin_capacity {
        score -= 2.0 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize slightly unless current bin would leave bad gap.
        score += 5.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; mild penalty proportional to wasted potential.
        score += 6.0;
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier gaps first
    // keeps larger residuals available).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Stream progression: late in stream, be more aggressive at filling bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
