pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual exactly matches next item — strong reward.
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= 30.0 - 0.6 * gap;
        } else {
            // Post-residual too small for next item: penalize potential dead space,
            // worse when the leftover is tiny (unusable).
            let dead = post_residual as f64;
            let waste_ratio = dead / bin_capacity as f64;
            score += 8.0 * (1.0 - waste_ratio);
        }
    }

    // Tight fit reward relative to current residual.
    let fit_tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fit_tightness;

    // Compare post_residual against mean residual: prefer bins driven below the mean
    // (concentrating usage), penalize bins that stay far above average.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new empty bin mildly, unless stream is early and
    // open bins are crowded (mean residual low means bins are nearly full).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (mean_residual / bin_capacity as f64) < 0.25;
        if crowded && progress > 0.2 {
            score -= 12.0; // opening a fresh bin is fine when existing bins are nearly full
        } else {
            score += 20.0; // discourage opening new bins when open bins have room
        }
    }

    // Small bonus for leaving round, reusable residuals (multiples of 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: bonus scaled by how small the post residual is.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness;

    // Exact or near-exact fills are gold.
    if post_residual == 0 { score -= 40.0; }
    else if post_residual <= 5 { score -= 20.0; }

    // Penalize dead space: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 { score += 15.0; }

    // Lookahead: if next item can pair perfectly into the post residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual { score -= 35.0; }
        else if next_item_size < post_residual {
            let leftover = post - nx;
            score -= 8.0 * (1.0 - leftover / cap);
        } else {
            // next item won't fit here: slight penalty for leaving a mid-size gap
            score += 3.0 * (nx - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 25.0; }

    // New-bin candidate handling: opening a bin is only attractive when open bins
    // are crowded or fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 30.0 + crowding * 2.0 - progress * 10.0;
        // If item is large, a fresh bin is more attractive (avoids fragmentation).
        score -= (item_size as f64 / cap) * 15.0;
    } else {
        // Favor bins whose residual deviates below the mean (consolidate small gaps).
        if (bin_residual as f64) < mean_residual { score -= 4.0; }
    }

    // Mild preference for reusing fuller bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - (bin_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, penalize residual more strongly
    score += 25.0 * progress * norm_pr * norm_pr * (1.0 - norm_pr);

    // Dead-space penalty: residuals too small for typical future items are worthless
    let dead = (norm_pr - (next_item_size as f64 / cap)).max(0.0);
    score += 15.0 * dead * dead * (1.0 + progress);

    // Lookahead synergy: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let match_term = 1.0 - (pr - next_item_size as f64).abs() / cap;
        score -= 12.0 * match_term.max(0.0) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening bins
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Mild penalty for scattering across many open bins when residual is above mean
    let dev = (mean_residual - pr) / cap;
    score += 5.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: make empty bin attractive only for large items / late stream
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress) - 8.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: partition capacity into 4 bands.
    let item_class = (item_size * 4 / bin_capacity) as f64;
    let next_class = (next_item_size * 4 / bin_capacity) as f64;

    // Reward tight fits: small post_residual is good (already base score).
    // Penalize dead space that no harmonic class can reuse:
    // post_residual < 10 (smallest item) is pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Reward placements that leave room for the NEXT item's harmonic class.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_class * 3.0;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize more if this bin was a good host.
        score += 4.0;
    }

    // Integer-division threshold: bins whose residual falls in a "harmonic"
    // band matching common item sizes (multiples of 10) are valuable.
    let band = post_residual / 10;
    let band_bonus = match band {
        0 => -25.0,
        1 => -18.0,
        2 => -10.0,
        3 => 0.0,
        4 => 6.0,
        _ => 10.0,
    };
    score += band_bonus;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // unless current bin would leave large unusable residue.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + progress * 10.0 - mean_residual * 0.05;
        if post_residual >= 50 {
            score -= 20.0; // fresh bin fine for big items early
        }
    }

    // Coupling with mean residual: prefer bins below mean residual
    // (denser bins) to consolidate fill.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Modulo coupling: residual divisible by item class boundaries is reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Penalize spreading across many open bins slightly.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold a
    // typical future item are worthless — heavily penalize them.
    let r = post_residual as f64;
    let dead_zone = 35.0; // typical small-item scale threshold
    if r > 0.0 && r < dead_zone {
        // The smaller the leftover, the worse: quadratic dead-space penalty.
        let deadness = (dead_zone - r) / dead_zone;
        score += 60.0 * deadness * deadness;
    }

    // Perfect fit is ideal: reward exact fills.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating a gap the known next item cannot use: extra penalty.
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing ones; when few are open, new bins are less costly.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 3.0 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Prefer bins with residuals close to the mean (balanced packing),
    // penalize outliers that create fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for tighter bins (best-fit flavor).
    score += 0.1 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that end with zero residual.
    if post_residual == 0 {
