    }

    // Aggressive 2-step lookahead: reward if next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves slack: mild reward proportional to tightness.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 50.0 * tightness;
        } else {
            // Next item cannot use this residual: penalize creating dead space
            // that is too small for the next item but non-zero.
            let waste = post_residual as f64;
            score += 0.5 * waste;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual close to the mean
    // (keeps residual distribution balanced), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Late in the stream, be more conservative: penalize leaving large residuals.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 0.2 * post_residual as f64;

    // Penalize new-bin opening unless nothing fits well.
    if bin_residual == bin_capacity {
        // New bin: base score = full capacity residual; only win if it yields
        // a better lookahead than existing bins (handled by score comparison).
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score *= 1.0 - 0.35 * fit_ratio;

    // Penalize leaving dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else {
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let time = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 - 30.0 * pressure - 5.0 * time;
        // discourage new bin when mean residual across open bins is large
        score += 0.4 * mean_residual;
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Mild preference to spread load when many bins are open with high mean residual
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Dead-space avoidance: residuals too small for a typical future item are worthless.
    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 60.0 * deadness * deadness;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: reward leaving room for the next item; penalize unusable gaps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            let after = post_residual - next_item_size;
            // Bonus for leaving a reusable, well-shaped remainder.
            if after % 10 == 0 && after >= 20 {
                score -= 3.0;
            }
            if after == 0 {
                score -= 6.0;
            }
            if after > 0 && after < 6 {
                score += 3.0;
            }
            if after >= next_item_size * 2 {
                score -= 2.0 + 2.0 * progress;
            }
        } else if post_residual > 0 {
            // Gap the known next item cannot use: scaled penalty.
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 + gap * 0.35;
            if post_residual < 20 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count == 0 {
        score -= 10.0;
    }

    // Open-bin pressure: consolidate when many bins are open.
    score += 3.0 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Prefer residuals near the mean (anti-fragmentation), plus tight-bin flavor.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;
    score += 0.1 * (bin_residual as f64);

    // Fill-ratio flavor (borrowed from best): near-full placements are excellent.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.75 {
        score -= 4.0;
    }

    // Exact-gap micro-rewards.
    let exact_gap = bin_residual.saturating_sub(item_size);
    if exact_gap <= 2 {
        score -= 5.0;
    } else if exact_gap <= 5 {
        score -= 2.0;
    } else if exact_gap <= 9 {
        score -= 1.0;
    }

    // NEW-BIN CANDIDATE LOGIC: decide when opening a fresh bin beats a poor fit.
    if bin_residual == bin_capacity {
        let new_left = bin_capacity.saturating_sub(item_size);
        let big_item = item_size > bin_capacity / 2;
        let scarce = fitting_bins_count <= 1;

        // Large items with no good home: opening a new bin is cheap.
        if big_item && scarce {
            score -= 6.0;
        } else if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 2 {
            score -= 2.0;
        } else if item_size >= 40 && (fitting_bins_count == 0 || (item_size > bin_capacity / 3 && next_item_size > bin_capacity / 2)) {
            score -= 2.0;
        } else {
            // Otherwise a fresh bin is expensive when open bins exist.
            score += 14.0;
        }

        // Reward a fresh bin whose remainder exactly matches the next item.
        if next_item_size > 0 && new_left == next_item_size && fitting_bins_count >= 1 {
            score -= 5.0;
        }
        // Penalize fresh-bin remainders that strand the next item in a narrow gap.
        if next_item_size > 0 && new_left < next_item_size && new_left < 15 && fitting_bins_count >= 1 {
            score += 3.0;
        }
        // Fresh bin leaving a clean multiple-of-10 remainder is attractive.
        if new_left % 10 == 0 && new_left >= 20 && fitting_bins_count >= 1 {
            score -= 4.0;
        }
        // Late-stream pressure: stop opening new bins near the end.
        if progress > 0.8 && fitting_bins_count > 0 && item_size < bin_capacity / 2 {
            score += 6.0 * (progress - 0.8) * 10.0;
        }
        if progress > 0.6 && fitting_bins_count >= 1 {
            score += 2.0 * (progress - 0.6) * 10.0;
        }
    } else {
        // Existing-bin refinements.
        if fitting_bins_count > 3 && post_residual > 30 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 3.0;
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 1.5;
        }
