pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: residual buckets by capacity fractions (eighths)
    let eighth = bin_capacity / 8; // 12
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;   // 50

    // Perfect-fit classes: reward residuals that are "harmonic" divisors of capacity
    let harmonic = post_residual == 0
        || post_residual == eighth
        || post_residual == quarter
        || post_residual == half
        || post_residual == 3 * quarter
        || post_residual == bin_capacity / 5
        || post_residual == bin_capacity / 10;
    if harmonic {
        score -= 18.0;
    }

    // Dead space penalty: residuals too small for any plausible item (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < quarter && post_residual > 0 {
        score += 8.0;
    }

    // Modulo-10 classes: residuals divisible by 10 pair well with integer item sizes
    if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain fit: strong reward, scaled by how snugly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't chain here: mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / bin_capacity as f64);
        }
    }

    // Last-chance bin: avoid opening a new bin if fit is decent
    if fitting_bins_count == 1 && post_residual < half {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 30.0;
        } else {
            // neutral baseline; penalize slightly so only truly bad fits open new bins
            score += mean_residual * 0.15;
            if post_residual == bin_capacity {
                score += 5.0; // fresh bin stays fresh only if unavoidable
            }
        }
    }

    // Early stream: be greedy with tight fits; late stream: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual divergence: prefer bins close to the mean (balance preservation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

