        if next_item_size > 0 && new_left >= next_item_size && new_left - next_item_size <= 1 && fitting_bins_count >= 1 {
            score -= 2.0;
        }
        if new_left < 10 && fitting_bins_count >= 1 && next_item_size > new_left {
            score += 4.0;
        }
        // Late-stream pressure: stop opening new bins near the end.
        if progress > 0.8 && fitting_bins_count > 0 && item_size < bin_capacity / 2 {
            score += 6.0 * (progress - 0.8) * 10.0;
        }
        if progress > 0.6 && fitting_bins_count >= 1 {
            score += 2.0 * (progress - 0.6) * 10.0;
        }
    } else {
        // Existing-bin refinements.
        if fitting_bins_count > 3 && post_residual > 30 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 3.0;
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 1.5;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && post_residual + item_size >= bin_capacity * 9 / 10 {
            score -= 1.5;
        }
        let band = (post_residual as f64 - mean_residual).abs();
        if band < 5.0 && post_residual >= next_item_size.max(1) {
            score -= 1.0;
        }
        // NEW: leave a residual that is itself reusable for the next item's remainder.
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 && post_residual > 20 {
            score -= 1.5;
        }
        // NEW: penalize residuals slightly below mean — likely stranded dead space.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual as f64 > mean_residual * 0.8 {
            score += 1.0;
        }
        // NEW: reward tight post-residual just above the next item (double-fit chains).
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score -= 2.0;
        }
    }

    score
