            if after % 10 == 0 && after >= 20 {
                score -= 3.0;
            }
            if after == 0 {
                score -= 6.0;
            }
            if after > 0 && after < 6 {
                score += 3.0;
            }
            if after >= next_item_size * 2 {
                score -= 2.0 + 2.0 * progress;
            }
            if after < 3 {
                score -= 2.0;
            }
            if after >= next_item_size && (after - next_item_size) * 2 >= next_item_size {
                score -= 1.5;
            }
            // refine: tight double-host lookahead — residual that hosts next item twice exactly
            if after == next_item_size {
                score -= 2.0;
            }
            // refine: after-next residual just under a second copy strands space
            if after >= next_item_size && after < next_item_size * 2 && after - next_item_size < next_item_size / 2 {
                score -= 1.0;
            }
            // refine: multiple-of-10 after-residual that still hosts another copy
            if after % 10 == 0 && after >= 10 && after < next_item_size {
                score -= 1.0;
            }
