        // NEW: residual exactly divisible into two next-item slots.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 2.0;
        }
        // NEW: residual just above next item (within 3) is a tight, valuable fit.
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score -= 2.0;
        }
        // NEW: clean 10-multiple residual that still hosts next item.
        if next_item_size > 0 && post_residual >= 10 && post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        // NEW: residual in the awkward 18..22 band unusable by next item.
        if post_residual >= 18 && post_residual <= 22 && next_item_size > post_residual {
            score += 2.0;
        }
    }

    score
