        if next_item_size > 0 && new_left >= next_item_size && fitting_bins_count >= 1 {
            let leftover = new_left - next_item_size;
            if leftover > 0 && leftover < 8 {
                score -= 2.0;
            }
            if leftover >= 10 && leftover % 10 == 0 {
                score -= 2.5;
            }
        }
        // Fresh bin leaving a residual band the next item cannot use.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left < next_item_size {
            score += (next_item_size - new_left) as f64 * 0.12;
        }
        // Small item into a fresh roomy bin is wasteful when open bins exist.
        if fitting_bins_count >= 1 && new_left >= 30 && item_size <= 10 {
            score += 2.0;
        }
        if fitting_bins_count == 0 && open_bins_count > 0 && mean_residual >= item_size as f64 {
