pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Dead-space avoidance: residuals too small for a typical future item are worthless.
    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 60.0 * deadness * deadness;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Borrowed from best: 10-band reuse signals.
    let fits_small = post_residual / 10;
    score -= fits_small as f64 * 2.0;
    if post_residual >= 10 && post_residual <= 20 && next_item_size > post_residual {
        score += 6.0;
    }

    // Lookahead: reward leaving room for the next item; penalize unusable gaps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            if next_item_size == post_residual {
                score -= 11.0;
            }
            let after = post_residual - next_item_size;
            if after % 10 == 0 && after >= 20 {
                score -= 4.0;
            }
            if after == 0 {
                score -= 6.0;
            }
            if after > 0 && after < 6 {
                score += 3.0;
            }
            if after >= next_item_size * 2 {
                score -= 2.0 + 2.0 * progress;
            }
            if after < 3 {
                score -= 2.0;
            }
            // Borrowed: after-next residual can host a second copy.
            if after >= next_item_size && after < next_item_size * 3 {
                score -= 1.5;
            }
        } else if post_residual > 0 {
            // Gap the known next item cannot use: scaled penalty with scarcity weighting.
            let gap = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score += 15.0 + gap * (0.35 + 0.25 * scarcity);
            // Dead-ratio penalty scaled by capacity.
            let dead_ratio = gap / bin_capacity as f64;
            score += dead_ratio * 46.0;
            if dead_ratio < 0.04 {
                score -= 4.5;
            }
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += stranded * 18.0;
            if post_residual < 20 {
                score += 5.0;
            }
            if fitting_bins_count <= 1 {
                score += 1.5;
            } else {
                score += 2.0;
            }
            // Borrowed: near-capacity fills even with a stranded gap are still good.
            if post_residual + item_size >= bin_capacity * 9 / 10 {
                score -= 3.0;
            }
        } else {
            // post_residual == 0 with a known next item: filling a bin completely is fine.
            if fitting_bins_count > 1 {
                score -= 3.0;
            } else {
                score -= 4.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count == 0 {
        score -= 10.0;
    }

    // Open-bin pressure: consolidate when many bins are open.
    score += 3.0 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Prefer residuals near the mean (anti-fragmentation), plus tight-bin flavor.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;
    score += 0.1 * (bin_residual as f64);

    // Fill-ratio flavor: near-full placements are excellent.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.75 {
        score -= 4.0;
    }

    // Exact-gap micro-rewards.
    let exact_gap = bin_residual.saturating_sub(item_size);
    if exact_gap <= 2 {
        score -= 5.0;
    } else if exact_gap <= 5 {
        score -= 2.0;
    } else if exact_gap <= 9 {
        score -= 1.0;
    }

    // NEW-BIN CANDIDATE LOGIC: decide when opening a fresh bin beats a poor fit.
    if bin_residual == bin_capacity {
        let new_left = bin_capacity.saturating_sub(item_size);
        let big_item = item_size > bin_capacity / 2;
        let scarce = fitting_bins_count <= 1;

        if big_item && scarce {
            score -= 6.0;
        } else if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 2 {
            score -= 2.0;
        } else if item_size >= 40 && (fitting_bins_count == 0 || (item_size > bin_capacity / 3 && next_item_size > bin_capacity / 2)) {
            score -= 2.0;
        } else {
            score += 14.0;
        }

        // Fresh bin leaving a remainder that exactly matches the next item.
        if next_item_size > 0 && new_left == next_item_size && fitting_bins_count >= 1 {
            score -= 5.0;
        }
        if next_item_size > 0 && new_left < next_item_size && new_left < 15 && fitting_bins_count >= 1 {
            score += 3.0;
        }
        // Clean multiple-of-10 remainder is attractive.
        if new_left % 10 == 0 && new_left >= 20 && fitting_bins_count >= 1 {
            score -= 4.0;
        }
        // Nearly-exact new-left match to next item.
        if next_item_size > 0 && new_left >= next_item_size && new_left - next_item_size <= 3 && fitting_bins_count >= 1 {
            score -= 2.5;
        }
        // Tiny new-left remainder strands space when open bins exist.
        if new_left <= 3 && fitting_bins_count >= 1 {
            score -= 6.0;
        }
        if new_left < 10 && fitting_bins_count >= 1 && next_item_size > new_left {
            score += 4.0;
        }
        // Roomy fresh bin that can host the next item twice is attractive.
        if next_item_size > 0 && new_left >= next_item_size * 2 && fitting_bins_count >= 1 && new_left < bin_capacity / 2 {
            score -= 3.5;
