    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Mean residual coupling: bins far below mean residual are already fragmented.
    if (bin_residual as f64) < mean_residual - 15.0 {
        score += 10.0;
    } else if (bin_residual as f64) > mean_residual + 15.0 {
        score -= 6.0;
    }

    score
}

