        if post == nxt {
            score -= 40.0;
        }
        // Near-match reward decaying with distance.
        let diff = (post - nxt).abs();
        score -= 20.0 * (-diff / 10.0).exp();

        // Penalize leaving post_residual that cannot host the next item but is
        // too large to be "dead" — awkward leftovers.
        if post < nxt && post > 0.0 {
            score += 8.0 * (1.0 - post / nxt);
        }

        // If next item is bigger than any residual we could leave, prefer
        // minimizing post_residual even harder (make room elsewhere).
        if nxt > post {
            score -= 5.0;
        }
    } else {
        // Last item: simply close out bins as tightly as possible.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tight";
    // filling them further is good if fit is tight, bad if it creates waste.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 6.0 * (1.0 - post_f / (mean_residual + 1.0));
    } else {
        score += 4.0 * ((post_f - mean_residual) / (bin_capacity as f64));
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating large unusable gaps relative to minimum item size (1).
    // Dead space = post_residual that is small but nonzero is worst.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a good (tight) fit — i.e., when best possible post_residual elsewhere is large.
    if bin_residual == bin_capacity {
        // Opening new bin leaves residual = capacity - item_size.
        // Penalize unless existing bins would leave much worse leftovers.
        score += 15.0;
