    let mut score = post_residual as f64;

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residue classes modulo 10.
    // Small residues (<=5) are "almost full" bins -> good, reward more.
    let class = post_residual % 10;
    if class <= 5 {
        score -= (5 - class) as f64 * 2.0;
    } else {
        score += (class - 5) as f64 * 1.5;
    }

