            score -= (10.0 - fill.min(10.0)) * 3.0;
        } else if next_item_size <= bin_residual && post_residual > 0 {
            // next item can't use this bin's leftover; mild penalty
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is penalized unless
    // the item is large relative to capacity and current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 60.0 * progress;
        if item_size >= 50 {
            score -= 30.0;
        }
        if open_bins_count > 0 && mean_residual < item_size as f64 * 0.5 {
            score -= 70.0; // bins are fragmented; fresh bin is good
