    }

    // Prefer filling bins that deviate below the mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.5;

    // Mild reward for consolidating into many-open-bin regimes.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

