pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect lookahead: next item would leave a tiny residual after
    // being placed into post_residual (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_residual = post_residual - next_item_size;
        if chain_residual <= 10 {
            score -= 25.0 - chain_residual as f64;
        } else if chain_residual <= 25 {
            score -= 10.0;
        }
    }
    // Penalize dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size as f64 - post_residual as f64;
        if gap <= 15.0 {
            score += gap * 0.8; // near-miss: mildly bad
        } else {
            score += gap * 0.25; // large unusable gap
        }
    }

    // Tight fits are good: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Compare against mean residual across open bins: bins with residual
    // far below mean are scarcer, prefer filling them.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when post_residual would be very usable (large space)
    // and no good fit exists elsewhere. Neutralize its raw score baseline.
    if bin_residual == bin_capacity {
        // An empty new bin leaves post_residual = capacity; that large raw
        // value already hurts it. Add a mild penalty so real tight fits win.
        score += 8.0;
        // But if nothing fits well (item leaves big dead space everywhere),
        // opening fresh can win via lookahead: reward when item is large.
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Stream progression: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            0.5
        } else {
            2.5
        };
        score += dead * (post_residual as f64).sqrt();
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / (bin_capacity as f64));
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty proportional to waste.
        score += 0.15 * post_residual as f64;
    }

    // New-bin candidate logic: an empty bin is attractive only if current open bins are crowded
    // or this bin would leave large unusable residue.
    if bin_residual == bin_capacity {
        let avg_crowding = mean_residual / (bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base handicap so new bins are not opened frivolously.
        score += 18.0;
        // But if open bins have little room on average, opening a new bin is fine.
        score -= 20.0 * (1.0 - avg_crowding);
        // Slightly more willing to open bins early in the stream (long horizon to amortize).
        score -= 6.0 * (1.0 - progress);
        // If many bins are already open, discourage spreading further.
        score += 0.4 * open_bins_count as f64;
        // If the new bin would fit the next item tightly too, encourage it.
        if next_item_size > 0 && (bin_capacity - next_item_size) <= 20 {
            score -= 8.0;
        }
    }

    // Mild bonus for bins whose residual is far below the mean (they are "specialized").
    let res_diff = (bin_residual as f64) - mean_residual;
    if res_diff < 0.0 {
        score -= 0.05 * (-res_diff);
    } else {
        score += 0.05 * res_diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: residual after placement (tighter fit => lower score)
    let mut score = r;

    // Non-linear polynomial coupling of residual with stream progress:
    // early on, small residuals are mildly penalized (keep bins flexible);
    // late in the stream, tight fits are strongly rewarded.
    let tightness = 1.0 - (r / cap).powf(2.0); // 0 = empty-ish, 1 = perfectly tight
    score -= tightness * (1.0 + 60.0 * progress * progress);

    // Smooth penalty for awkward mid-range dead space (residual too small
    // for typical future items but not zero): cubic bump centered mid-capacity.
    let x = r / cap;
    let dead = x * (1.0 - x) * (x - 0.5) * (x - 0.5);
    score += 40.0 * dead * (1.0 - progress);

    // Last-chance bonus: only one bin fits => strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits in post-residual, penalize otherwise.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= r {
            score -= 8.0 * (1.0 - (nx / cap).powf(1.5));
        } else {
            score += 6.0 * ((nx - r) / cap);
        }
    }

    // Mild preference to fill bins with large residuals when many bins open.
    score -= (bin_residual as f64 - mean_residual) / cap * 5.0 * progress;

    // New-bin candidate: make empty bins slightly unattractive unless
    // nothing fits well (post_residual small relative to capacity elsewhere
    // will dominate); scale with open bins count to limit bin proliferation.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Dead-space avoidance: residuals too small for typical future items are wasted.
    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 60.0 * deadness * deadness;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: reward leaving room for the next item; penalize unusable gaps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if next_item_size == post_residual {
                score -= 11.0;
            }
            let after = post_residual - next_item_size;
            if after % 10 == 0 && after >= 20 {
                score -= 3.0;
            }
            if after == 0 {
                score -= 6.0;
            }
            if after > 0 && after < next_item_size {
                score += 1.5;
            }
            if after < 10 {
                score += 2.0;
            }
            if after >= next_item_size * 2 {
                score -= 2.0 + 2.0 * progress;
            }
            if after < 3 {
                score -= 2.0;
            }
        } else if post_residual > 0 {
            // Gap the known next item cannot use: scaled penalty with scarcity weighting.
            let gap = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score += 15.0 + gap * (0.15 + 0.45 * scarcity);
            let dead_ratio = gap / bin_capacity as f64;
            score += dead_ratio * 46.0;
            if dead_ratio < 0.04 {
                score -= 4.5;
            }
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += stranded * 18.0;
            if post_residual < 20 {
                score += 5.0;
            }
            if fitting_bins_count >= 2 {
                score += 2.0;
            }
            if fitting_bins_count <= 1 {
                score += 1.5;
            }
        } else {
            if fitting_bins_count > 1 {
                score -= 3.0;
            }
        }
        if next_item_size > bin_capacity / 2 && post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
        if post_residual >= next_item_size && post_residual >= mean_residual as u32 {
            score -= 1.5;
        }
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count == 0 {
        score -= 10.0;
    }

    // Open-bin pressure: consolidate when many bins are open.
    score += 3.0 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Prefer residuals near the mean (anti-fragmentation), plus tight-bin flavor.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;
    score += 0.1 * (bin_residual as f64);

    // Fill-ratio flavor: near-full placements are excellent.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.75 {
        score -= 4.0;
    }

