    let exact_gap = bin_residual.saturating_sub(item_size);
    if exact_gap <= 2 {
        score -= 5.0;
    } else if exact_gap <= 5 {
        score -= 2.0;
    } else if exact_gap <= 9 {
        score -= 1.0;
