        }
        // Mean open residual already covers this item size: reuse.
        if fitting_bins_count > 0 && open_bins_count > 0 && mean_residual >= item_size as f64 * 1.2 && item_size <= bin_capacity / 4 {
            score += 5.0;
        }
        // Late-stream pressure: stop opening new bins near the end.
        if progress > 0.8 && fitting_bins_count > 0 && item_size < bin_capacity / 2 {
            score += 6.0 * (progress - 0.8) * 10.0;
        }
        if progress > 0.6 && fitting_bins_count >= 1 {
            score += 2.0 * (progress - 0.6) * 10.0;
        }
        if next_item_size >= bin_capacity * 2 / 5 && fitting_bins_count > 0 && item_size <= bin_capacity / 3 {
            score += 4.0;
        }
        if fitting_bins_count == 0 && open_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 6.0;
        }
        if next_item_size > 0 && new_left >= next_item_size {
            let leftover = new_left - next_item_size;
            if leftover > 0 && leftover < 8 {
                score -= 2.0;
            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && new_left < next_item_size {
            score += (next_item_size - new_left) as f64 * 0.12;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left > next_item_size && (new_left - next_item_size) % 10 == 0 && new_left - next_item_size >= 10 {
