pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common item sizes) are preferred.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Perfect fit -> huge reward.
    if pr == 0 {
        score -= 1000.0;
    }

    // Harmonic class check: is post_residual divisible into small usable chunks?
    // Classes: divisible by 10, 20, 25, 50 are "harmonic" leftovers.
    let harmonic = (pr % 10 == 0) as f64 * 6.0
                 + (pr % 20 == 0) as f64 * 4.0
                 + (pr % 25 == 0) as f64 * 3.0
                 + (pr % 50 == 0) as f64 * 2.0;
    score -= harmonic;

    // Dead-space penalty: small, non-harmonic residuals are wasted space.
    if pr > 0 && pr < 10 {
        score += 25.0 * (1.0 - pr as f64 / 10.0);
    }

    // Fraction-of-capacity thresholds via integer division on post_residual.
    let quarter = pr / 25; // 0..4 class
    match quarter {
        0 => score += 8.0,          // tiny leftover: nearly full, good
        1 => score -= 2.0,          // 25-49 leftover
        2 => score -= 4.0,          // 50-74 leftover
        _ => {}                     // large leftover: neutral
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            let nxt_pr = pr - next_item_size;
            // reward chained harmonic leftovers
            if nxt_pr % 10 == 0 { score -= 10.0; }
            score -= 5.0 * (1.0 - (nxt_pr as f64 / cap).abs());
        } else {
            // next item cannot follow here: mild penalty scaled by gap
            score += 3.0 + (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent
    // open bins exist, unless current bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 * mean_residual / cap;
        // new bin is attractive only if mean residual across open bins is small
        score += 15.0 + open_pressure * 2.0 - progress * 5.0;
        // but if item is large, new bin is fine
        if item_size as f64 > 0.7 * cap {
            score -= 20.0;
        }
    }

    // Tightness reward: how well item fills the bin (fraction-based).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 12.0;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Mild exploration term via step harmonic class.
    let step_class = (step_index % 7) as f64;
    score += step_class * 0.01;

    score
}

