        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual as f64 > mean_residual * 0.8 {
            score += 1.0;
        }
        // refine: existing bins whose residual after placement leaves a second-hostable residual get an extra nudge
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size >= next_item_size {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space: essentially unusable
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits proportionally (fraction of bin consumed by this item).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // making new bins less attractive.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty plus pressure from open bin count.
        score += 35.0 + 3.0 * open_bins_count as f64;
        // If the next item is small, a fresh large residual is attractive.
        if next_item_size > 0 && (next_item_size as f64) < mean_residual {
            score -= 10.0;
        }
        // Late in the stream, opening new bins is cheaper (less future to serve).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    } else {
        // Existing bin: slight preference for bins with low residual already
        // (keep big residuals for big future items).
        let gap = (mean_residual - bin_residual as f64).max(0.0);
        score += 0.15 * gap;
        // If next item could exactly use the post residual, reward this placement.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual as u32 && post_residual > 0 {
            // post residual too small for next item: mild penalty
            score += 5.0;
        }
    }

    score
}

