    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit in the leftover: penalize proportionally to wasted potential
    else if next_item_size > 0 && next_item_size > post_residual {
        let waste = (post_residual as f64) / (next_item_size as f64);
        score += 20.0 * waste;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual
    let cap = bin_capacity as f64;
    let rel = (post_residual as f64 - mean_residual) / cap;
    score += 15.0 * rel;

    // Penalize tiny unusable dead space more than moderately large space
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins -> discourage spreading; few open bins -> allow new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are crowded or few
        let crowded = mean_residual / cap;
        score -= 10.0 * (1.0 - crowded) * (1.0 - progress);
        score += 20.0 * crowded;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

