pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight fit reward: strongly favor bins where the item nearly fills residual.
    let tightness = 1.0 - pr / cap; // 0..1, higher = tighter
    score -= 18.0 * tightness * tightness;

    // Perfect-fit style bonus for very small dead space.
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let reuse_ratio = next_item_size as f64 / pr.max(1.0);
        score -= 8.0 + 6.0 * reuse_ratio;
    } else if next_item_size > 0 {
        // Penalize creating dead space the next item cannot use.
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity). It should only
    // win when no open bin offers a decent fit. Its natural base score is high
    // (pr = cap - item), but we calibrate: penalize opening new bins when several
    // bins already fit, and reward it when the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        // Baseline deterrent proportional to how many bins already fit.
        score += 30.0 + 6.0 * fitting_bins_count as f64;
        // If item is large, a fresh bin is attractive (large items pair well with
        // small leftovers elsewhere, but a new bin keeps flexibility).
        score -= (item_size as f64 / 10.0) * 2.0;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Global state coupling: prefer bins whose residual is close to the mean
    // residual (keeps bin states balanced, preserves many medium gaps).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for bins with larger residual when item is small
    // (don't waste a nearly-empty bin on a tiny item).
    if item_size < 25 && bin_residual > 70 {
        score += 8.0;
    }

    // Mild open-bin count pressure: many open bins -> prefer consolidating.
    score += 0.5 * open_bins_count as f64 * (pr / cap);

    score
}

