    let mut score = pr as f64 + 40.0 * norm_pr * norm_pr;

    // Smooth coupling of post_residual with stream progress:
    // early on, tolerate loose fits; late, penalize them more strongly.
    let progress_coupling = norm_pr * (1.0 - norm_pr) * (0.5 - progress);
    score += 60.0 * progress_coupling;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item can fit into the post residual (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt) / cap;
        if fit_gap >= 0.0 {
            score -= 12.0 * fit_gap * (1.0 - fit_gap);
        } else {
            score += 8.0 * (-fit_gap);
        }
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Mean residual deviation: penalize bins that deviate from the fleet average
