    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Items are 1..=100, so a post_residual below ~10 is likely dead space.
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        let severity = (dead_threshold - pr) / dead_threshold; // 0..1, worse as gap shrinks
        score += 60.0 * severity;
    }

    // Post residual exactly equal to a plausible next-item size is great: reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If next item can't fit in the post residual, this bin becomes dead-ish: mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize new-bin usage); with few open bins, opening new bins is cheap.
    let pressure = (open_bins_count as f64).ln() / 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins accumulate.
        score += 20.0 + 30.0 * pressure;
    } else {
        // Reward using existing bins, scaled by pressure.
        score -= 5.0 + 10.0 * pressure;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Tight fits (low waste ratio) get a proportional reward.
    let waste_ratio = pr / bin_capacity as f64;
    score -= 15.0 * (1.0 - waste_ratio);

    // Early in the stream, be more willing to fill bins loosely (future items unknown);
    // later, tighten up.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * waste_ratio;

    // Prefer bins whose residual is below the mean (consolidate fuller bins first).
    score += 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    score
}

