pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        // exact match bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // avoid leaving residual just below next item (dead space for next step)
        if next_item_size > post_residual {
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 25.0 * (1.0 - gap / 10.0);
            }
        }
    } else {
        // last item: prefer tightest fit
        score -= 20.0;
    }

    // Penalize residual that is too small to ever be useful (below min item size 1..100 unknown, use small threshold)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: this is the only fitting bin; strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or residuals are large
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize new bins generally, more early on
        score += 90.0 + 50.0 * (1.0 - progress);
        // but if mean residual is large and item is big, new bin may be reasonable
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // must open new bin
        }
    }

    // mild preference for bins below mean residual (consolidate fragmented space)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

