    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else {
            score -= 6.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here after placement: penalize wasted residual.
        score += 0.08 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.3 * crowding;

    // New-bin candidate: make it unattractive unless it's early or residual is huge.
    if bin_residual == bin_capacity {
        let base = 30.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
        // Early stream: opening bins is cheap; late stream: expensive.
        score += base;
