        if next_item_size > 0 && new_left == next_item_size && fitting_bins_count >= 1 && progress > 0.4 {
            score -= 2.0;
        }
        // Fresh bin leftover of 1-3 units is a near-perfect fill — reward closing tightly.
        if new_left >= 1 && new_left <= 3 && fitting_bins_count >= 1 {
            score -= 3.0;
        }
        // When mean residual already fits the next item, opening a fresh bin is wasteful.
        if next_item_size > 0 && fitting_bins_count > 1 && mean_residual >= next_item_size as f64 {
            score += 1.5;
        }
        // gen44: fresh bin whose leftover is a round reusable band (10/15/20/25/30) and can host next twice — deepen.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 2 && new_left % 5 == 0 {
            score -= 1.0;
        }
        // gen44: fresh bin leftover just under next item with a big gap is a poor prospect — scale harder late.
        if next_item_size > 0 && new_left < next_item_size && new_left >= 4 && (next_item_size - new_left) > 6 {
            score += (next_item_size - new_left) as f64 * 0.05 * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
