    }

    // Penalize residuals that are far from mean residual (fragmentation).
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are poor.
    if bin_residual == bin_capacity {
        let mut penalty = 30.0;
        // If no open bin leaves room for the next item, opening a new bin is more attractive.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
