        // Early in the stream, allow more bins (spread items for future flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty -= 8.0 * (1.0 - progress);
        // Many open bins with slack: discourage opening yet another.
        penalty += 1.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
