            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && new_left < next_item_size {
            score += (next_item_size - new_left) as f64 * 0.12;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left > next_item_size && (new_left - next_item_size) % 10 == 0 && new_left - next_item_size >= 10 {
            score -= 2.5;
        }
        if next_item_size > 0 && new_left >= next_item_size && new_left < next_item_size * 3 && fitting_bins_count >= 1 {
            score -= 1.0;
        }
        if item_size >= bin_capacity * 2 / 5 && item_size <= bin_capacity / 2 && fitting_bins_count == 0 && open_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 && new_left >= 25 && new_left < 35 && fitting_bins_count > 0 && next_item_size <= new_left {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= 11 && new_left <= 19 && new_left < next_item_size {
            score += 2.0;
        }
        if fitting_bins_count > 2 && open_bins_count > 0 && mean_residual > new_left as f64 * 1.5 {
            score += 2.5;
        }
        if item_size <= 10 && fitting_bins_count >= 1 && new_left >= 30 {
            score += 2.0;
        }
        // gen37: fresh bin that can host next item and then leave a splittable half-chunk is valuable.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size {
            let chain = new_left - next_item_size;
            if chain >= next_item_size / 2 && chain <= next_item_size {
                score -= 2.0;
            }
        }
        // gen37: stranded fresh-bin leftover just under next item — scale penalty with chunk size.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left < next_item_size && new_left >= 15 {
            score += (next_item_size - new_left) as f64 * 0.18;
        }
        // gen37: late-stream consolidation — avoid opening new bins when few items remain.
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count > 0 {
            score += 3.0 * progress;
        }
        // gen38: fresh bin that can host next item twice is very valuable when open bins are scarce.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 2 && open_bins_count <= 3 {
            score -= 1.5;
        }
        // gen38: penalize fresh bins whose stranded leftover is a large fraction of capacity without next-item info.
        if next_item_size == 0 && new_left > bin_capacity * 3 / 5 && open_bins_count > 2 {
            score += 2.0;
        }
        // gen38: discourage opening new bins for small items when open bins have plenty of room.
        if fitting_bins_count >= 1 && item_size <= bin_capacity / 5 && mean_residual >= item_size as f64 * 2.0 {
            score += 3.0;
        }
        // gen39: fresh bin whose leftover after next item is a reusable round size (10/20/30) is attractive.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left > next_item_size {
            let chain_left = new_left - next_item_size;
            if chain_left == 10 || chain_left == 20 || chain_left == 30 {
                score -= 2.0;
            }
        }
        // gen39: opening a new bin for a tiny item when open bins have generous mean residual is wasteful — stronger penalty.
        if fitting_bins_count >= 1 && item_size <= 8 && mean_residual >= 40.0 {
            score += 4.0;
        }
        // gen41: fresh bin whose leftover after next item is just under another next-item-sized chunk — proportional strand penalty.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left > next_item_size {
            let chain_left = new_left - next_item_size;
            if chain_left > 0 && chain_left < next_item_size {
                score += (next_item_size - chain_left) as f64 * 0.10;
            }
        }
        // gen41: fresh bin that exactly closes after hosting next item late in stream is excellent.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left == next_item_size && progress > 0.5 {
            score -= 1.5;
        }
        // gen41: when many bins are open and mean residual comfortably fits the item, resist opening fresh bins.
        if fitting_bins_count >= 1 && open_bins_count > 3 && mean_residual >= (item_size + 10) as f64 {
            score += 2.5;
        }
        // gen44: fresh bin that can host next item then leave exactly 10/20 (reusable round chunk) — deeper reward.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left > next_item_size {
            let chain_left = new_left - next_item_size;
            if chain_left == 10 || chain_left == 20 {
                score -= 1.5;
            }
        }
        // gen44: fresh-bin leftover just under next item in the 20-30 band strands a big chunk — penalize harder.
        if next_item_size > 0 && new_left >= 20 && new_left < next_item_size && (next_item_size - new_left) <= 6 {
            score += 1.5;
        }
    } else {
        // Existing-bin refinements.
        if fitting_bins_count > 3 && post_residual > 30 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 3.0;
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 1.5;
        }
        let band = (post_residual as f64 - mean_residual).abs();
        if band < 5.0 && post_residual >= next_item_size.max(1) {
            score -= 1.0;
        }
        if post_residual < next_item_size && post_residual < mean_residual as u32 {
            score += 2.0;
        }
        // 10-band reuse bonus.
        let fits_small = post_residual / 10;
        score -= fits_small as f64 * 3.0;
        if post_residual >= 10 && post_residual <= 20 && next_item_size > post_residual {
            score += 13.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 && post_residual > 20 {
            score -= 1.5;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < next_item_size / 2 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size >= next_item_size {
            score -= 1.0;
        }
        if post_residual > 12 && post_residual < 25 && next_item_size > post_residual {
            score += 1.0;
        }
        if post_residual >= 18 && post_residual <= 22 && next_item_size > post_residual {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= 10 && post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual as f64 > mean_residual * 0.8 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let twice_left = post_residual - next_item_size;
            if twice_left >= next_item_size.max(8) {
                score -= 1.0;
            }
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 10 && after <= 20 {
                score -= 1.0;
            }
        }
        // gen37: existing bin that exactly hosts next item afterwards is ideal.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 2.0;
        }
        // gen37: near-full existing bins — extra reward scaled by stream progress.
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count >= 1 {
            score -= 1.0 + 1.5 * progress;
        }
        // gen38: existing bins that close fully after hosting next item late in stream.
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 1 && progress > 0.5 {
            score -= 1.5;
        }
        // gen38: two-step lookahead — residual that after next item still fits a similar item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let twice_left = post_residual - next_item_size;
            if twice_left >= next_item_size && twice_left < next_item_size * 2 && fitting_bins_count >= 1 {
                score -= 1.0;
            }
        }
        // gen39: existing bin whose post-residual is a reusable round size (10/20/30) is a good landing spot.
        if post_residual == 10 || post_residual == 20 || post_residual == 30 {
            score -= 1.5;
        }
        // gen39: when open bins are plentiful, reward placements that leave small (nearly closed) residuals.
        if open_bins_count > 4 && post_residual > 0 && post_residual <= 8 {
            score -= 2.0 * (open_bins_count.min(10) as f64 - 4.0) * 0.25;
        }
        // gen41: existing bin that after next item leaves a strand just below next-item size — proportional penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after > 0 && after < next_item_size && after >= 10 {
                score += (next_item_size - after) as f64 * 0.06;
            }
        }
        // gen41: existing bin that closes exactly after hosting the next item late in stream.
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.5 {
            score -= 1.0;
        }
        // gen44: combine fine-grained residual fitting with lookahead — existing bin whose after-next leftover
        // lands exactly on a small reusable size (5/10/15/20) is a strong landing spot.
        if next_item_size > 0 && post_residual > next_item_size {
            let after = post_residual - next_item_size;
            if after == 5 || after == 10 || after == 15 || after == 20 {
                score -= 1.5;
            }
        }
        // gen44: existing bin leaving a strand just under the next item wastes proportionally —
        // strengthen the fine-grained penalty when open bins are plentiful (dead-space control).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && open_bins_count > 3 {
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: waste classes by integer division.
    // Residuals in [1, 12] are near-dead space -> heavy penalty unless exactly 0.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 6 {
        score += 45.0; // nearly unusable dead space
    } else if post_residual <= 12 {
        score += 22.0;
    }

    // Modulo arithmetic on post_residual: leftover divisible by common small
    // item sizes (5, 10, 20, 25) is reusable -> reward.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 14.0;
    } else if post_residual > 0 && post_residual % 5 == 0 {
        score -= 7.0;
    }

    // Lookahead coupling: reward when next item fits the post-residual,
    // penalize when it nearly fits (would force a new bin anyway).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.25;
        } else if next_item_size > post_residual && next_item_size - post_residual <= 8 {
            score += 10.0; // teases but fails: bad trap
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless it creates tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual <= 6 && post_residual > 0 {
            score += 25.0; // but not if it wastes almost everything
        }
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // current bin would leave a bad class of residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_here = post_residual as f64;
        score = waste_here + 55.0 * (1.0 - progress) - 20.0 * progress;
        if fitting_bins_count == 1 && post_residual <= 12 {
            score += 40.0; // keep the last-chance bin alive instead
        }
    }

    // Mild pressure to consolidate: prefer fuller bins among equals.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "dead" if it cannot fit even the smallest plausible item (<= 1),
    // and heavily discouraged if it can only fit tiny items.
    let dead_threshold = 1.0;
    let small_gap_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 50.0; // perfect fill, great
    } else if (post_residual as f64) < small_gap_threshold {
        score += (small_gap_threshold - post_residual as f64) * 4.0; // discourage tiny gaps
    }

    // Reward tight fits (low post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * tightness * 20.0;

    // Open-bin pressure: penalize opening new bins when many bins are open,
    // but allow new bins when open bins are crowded.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bin pressure.
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 10.0 + 30.0 * pressure;

        // If this bin is the last chance before opening a new bin, strongly prefer using it.
        if fitting_bins_count == 1 && open_bins_count > 0 {
            score -= 100.0;
        }
    } else if fitting_bins_count == 1 {
        // Last fitting open bin: strongly favor using it to avoid a new bin.
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 4.0; // next item won't fit here; slight penalty
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // using it reduces fragmentation of the bin set.
    let residual_diff = mean_residual - (bin_residual as f64);
    if residual_diff > 0.0 {
        score -= residual_diff * 0.5;
    }

    // Stream progression: early on, be more willing to open bins (explore);
    // later, consolidate to avoid bin sprawl.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 15.0; // later in stream, new bins are more costly
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Dead-space avoidance: residuals too small for typical future items are wasted.
    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 65.0 * deadness * deadness;
    }

    // Perfect fill reward (progress-scaled).
    if post_residual == 0 {
        score -= 80.0 + 2.0 * progress;
    }

    // Lookahead: reward leaving room for the next item; penalize unusable gaps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if next_item_size == post_residual {
                score -= 13.0;
            }
            let after = post_residual - next_item_size;
            if after % 10 == 0 && after >= 20 {
                score -= 3.0;
            }
            if after == 0 {
                score -= 6.0;
            }
            if after > 0 && after < next_item_size {
                score += 1.5;
            }
            if after < 10 {
                score += 2.0;
            }
            if after >= next_item_size * 2 {
                score -= 2.0 + 2.0 * progress;
            } else if after < 4 {
                score += 2.0;
            }
            if after < 3 {
                score -= 2.0;
            }
            if after >= next_item_size.max(8) {
                score -= 1.0;
            }
            if after >= next_item_size * 3 {
                score -= 1.0;
            }
            // Chain: after next item, still can host half of next size again.
            if after >= next_item_size / 2 && after <= next_item_size {
                score -= 1.0;
            }
            // gen41: two-step chain — after hosting next, still host next again.
            if after >= next_item_size * 2 && open_bins_count <= 4 {
                score -= 1.0;
            }
            // gen45: three-step chain — residual hosting next three times is superb consolidation.
            if after >= next_item_size * 3 && open_bins_count >= 4 {
                score -= 1.5;
            }
            // gen45: reusable multiple of 5 in the 15-35 band after hosting next.
            if after >= 15 && after <= 35 && after % 5 == 0 {
                score -= 1.0;
            }
        } else if post_residual > 0 {
            // Gap the known next item cannot use.
            let gap = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score += 15.0 + gap * (0.15 + 0.45 * scarcity);
            let dead_ratio = gap / bin_capacity as f64;
            score += dead_ratio * 46.0;
            if dead_ratio < 0.04 {
                score -= 4.5;
            }
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += stranded * 18.0;
            if post_residual < 20 {
                score += 5.0;
            }
            if fitting_bins_count >= 2 {
                score += 2.0;
            }
            if fitting_bins_count <= 1 {
                score += 1.5;
            }
            score += gap * 0.08;
            if post_residual + item_size >= bin_capacity * 9 / 10 {
                score -= 1.5;
            }
            if post_residual <= 4 {
                score -= 2.5;
            }
            // Stranded chunk scaled with size when just under next item.
            if post_residual >= 15 {
                score += gap * 0.10;
            }
            // gen41: near-miss gap of 1-2 units is nearly a perfect fill — soften penalty.
            if gap <= 2.0 && post_residual >= 10 {
                score -= 3.0;
            }
            // gen45: dead-space guard — residual just below next item in the 10-20 band wastes a usable chunk.
            if post_residual >= 10 && post_residual < 20 {
                score += 2.0;
            }
        } else {
            if fitting_bins_count > 1 {
                score -= 3.0;
            }
        }
        if next_item_size > bin_capacity / 2 && post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
        if post_residual >= next_item_size && post_residual >= mean_residual as u32 {
            score -= 1.5;
        }
        if post_residual > 0 && post_residual < next_item_size && post_residual > next_item_size.saturating_sub(4) {
            score += 2.0;
        }
        // Exact-next fit on existing bins is ideal.
        if post_residual == next_item_size {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count == 0 {
        score -= 10.0;
    }

    // Open-bin pressure: consolidate when many bins are open.
    score += 3.0 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Prefer residuals near the mean (anti-fragmentation), plus tight-bin flavor.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;
    score += 0.1 * (bin_residual as f64);

    // Fill-ratio flavor: near-full placements are excellent.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.75 {
        score -= 4.0;
    }

    // Exact-gap micro-rewards.
    let exact_gap = bin_residual.saturating_sub(item_size);
    if exact_gap <= 2 {
        score -= 5.0;
    } else if exact_gap <= 5 {
        score -= 2.0;
    } else if exact_gap <= 9 {
        score -= 1.0;
