        }
        // gen41: fresh bin leftover of 1-3 units is a near-perfect fill — reward closing tightly.
        if new_left >= 1 && new_left <= 3 && fitting_bins_count >= 1 {
            score -= 3.0;
        }
        // gen41: when mean residual already fits the next item, opening a fresh bin is wasteful.
        if next_item_size > 0 && fitting_bins_count > 1 && mean_residual >= next_item_size as f64 {
            score += 1.5;
        }
        // gen45: dead-space minimization — stranded leftover in the 10-15 band under next item.
        if next_item_size > 0 && new_left < next_item_size && new_left >= 10 && new_left < 15 {
            score += (next_item_size - new_left) as f64 * 0.10;
