        // gen45: fresh bin leaving residual that is a reusable multiple of 5 in the 30-50 band stays reusable.
        if new_left >= 30 && new_left <= 50 && new_left % 5 == 0 {
            score -= 1.0;
        }
        // gen45: late-stream — only open fresh bins when no open bin can host both this and the next item.
        if progress > 0.75 && fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step match: post_residual equals next item size -> perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits exactly after current placement (pairing bonus).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_pair = post_residual - next_item_size;
        // Reward tight two-item packing: slack after both items is small.
        score -= 25.0 * (1.0 - slack_after_pair as f64 / bin_capacity as f64);
        // Extra bonus if the pair leaves a tiny unusable residue.
        if slack_after_pair < 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow in this bin: penalize proportionally to wasted potential.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.35 * waste;
        // Harsher if the leftover is a dead zone (too small for typical items).
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    let resid_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (resid_f - mean_residual);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0
            || (next_item_size > 0 && next_item_size > post_residual && post_residual < 20);
        if poor_fits {
            score -= 18.0;
        } else {
            score += 25.0;
        }
    }

    // Late in the stream: consolidate harder, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (resid_f / bin_capacity as f64);

    // Penalize opening new bins when many bins are already open but usable.
    if open_bins_count > 3 && bin_residual == bin_capacity {
        score += 5.0 * (open_bins_count as f64).ln();
    }

    score
}

