        // gen46: reward fresh bins whose leftover matches next item plus a small reusable band (5..9).
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && new_left - next_item_size >= 5 && new_left - next_item_size <= 9 {
