        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count <= 2 {
            score -= 1.0;
        }
        // dead-space guard for large stranded residuals — post_residual just below next item but > 20 wastes a big chunk.
        if next_item_size > 0 && post_residual >= 20 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.06;
        }
        // reusable 5-multiple band late in stream — these residuals are easiest to fill.
        if post_residual >= 15 && post_residual <= 35 && post_residual % 5 == 0 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 1.0;
        }
        // gen52: exact two-step chain — post_residual == 2*next with few fitting bins.
        if next_item_size > 0 && post_residual == next_item_size * 2 && fitting_bins_count <= 3 {
            score -= 1.0 + 0.5 / (1.0 + fitting_bins_count as f64);
        }
        // gen52: hosting next twice with a clean 10-multiple tail is a perfect handoff, progress-weighted.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && (post_residual - next_item_size) % 10 == 0 {
            score -= 1.0 + 0.5 * progress;
        }
        // gen52: mid-band stranded residual guard (15..20 just below next).
        if next_item_size > 0 && post_residual >= 15 && post_residual < 20 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.04;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, quadratically (dead space is increasingly bad)
    let mut score = post * post / cap;

    // Smooth interaction: leftover space matters more late in the stream
    score += post * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item size)
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * (item_size as f64);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Penalize opening a new bin when good fits exist, more so early on
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress);
        // If next item fits nicely in the residual this bin would leave, soften penalty
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0;
        }
        // Late stream with many open bins: prefer consolidation into open bins
        if progress > 0.7 && open_bins_count > 2 {
            score += 15.0 * progress;
        }
    }

    // Mild penalty if this bin's residual deviates far from the mean residual
    // (encourages balanced residual profiles)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Lookahead: if the next item exactly fills the post residual, reward heavily
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }

    score
}

