        if next_item_size > 0 && post_residual >= 15 && post_residual <= 35 && post_residual % 5 == 0 && post_residual >= next_item_size {
            score -= 1.0;
        }
        // post_residual hosting next item twice (2x..3x) is a strong consolidation signal.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual < next_item_size * 3 {
            score -= 1.0;
        }
        // near-exact chain — post_residual exceeds next item by exactly 1..=3 with progress: deepen reward.
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 && progress > 0.6 {
            score -= 1.0;
        }
        // large post_residual (> half capacity) that cannot host next item is heavy dead space; penalize more.
        if next_item_size > 0 && post_residual > bin_capacity / 2 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
        // gen52: existing-bin exact double handoff — post_residual == 2*next with few fitting bins is a perfect chain.
        if next_item_size > 0 && post_residual == next_item_size * 2 && fitting_bins_count <= 3 {
            score -= 1.5;
        }
        // gen52: post_residual hosting next with a 10-multiple tail >= 10 leaves a reusable slot; reward with progress.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size >= 10 && (post_residual - next_item_size) % 10 == 0 && progress > 0.5 {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small" residue classes (<= 10) are nearly perfect fits.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 60.0; // near-perfect, dead space negligible
    } else if post_residual <= 25 {
        score -= 15.0; // still usable for small items
    }

    // Integer-division classes: residue mod 10 buckets. Leftovers that are
    // multiples of 10 align with common item sizes (10..80 grid).
    let r10 = post_residual % 10;
    if r10 == 0 {
        score -= 8.0;
    } else {
        score += r10 as f64 * 0.5; // ragged residue is less reusable
    }

    // Lookahead coupling: if next item fits the post_residual exactly,
    // strongly reward this bin (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // fraction of next item absorbed by the leftover
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * frac;
            // next item leaves another tiny residue -> chain continues
            let post2 = post_residual - next_item_size;
            if post2 <= 10 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this leftover: penalize large leftovers
            score += 0.3 * (post_residual as f64 - bin_capacity as f64 / 2.0).abs();
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when existing bins are underutilized,
    // but allow it late in the stream to consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate score: base cost + pressure from open bins
        score = bin_capacity as f64 - 20.0 * progress;
        if open_bins_count > 8 {
            score += 30.0; // too many open bins: prefer reusing
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0; // big next item: a fresh bin may serve it better
        }
    }

    // Mean-residual coupling: prefer bins close to the mean residual
    // (keeps the bin set homogeneous, easier future packing).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Mild tightness reward: fuller bins first.
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

