}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are small relative to the
    // minimum plausible item size (1..100 interface) are "dead" — penalize hard.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 0.0; // exact fit, perfect
    }
    // Dead-space curve: waste grows super-linearly as residual shrinks
    // toward unusability, but large residuals are mild.
    let r = post_residual as f64;
    let dead_threshold = (bin_capacity as f64) * 0.30;
    if r < dead_threshold {
        let severity = (dead_threshold - r) / dead_threshold; // 0..1
        score += severity * severity * 40.0;
    }

    // Reward residuals that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Tight-but-fitting residual is ideal: chain packing.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Lookahead won't fit here: penalize proportionally to closeness
            // (near-miss residual is the worst kind of dead space).
            let miss = (next_item_size - post_residual) as f64;
            score += 6.0 + 14.0 * (1.0 - miss / bin_capacity as f64);
        }
    }

    // Exact-fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bins pressure: discourage spreading across many bins when a
    // tight fit exists; mild linear term plus mild quadratic coupling.
    let pressure = open_bins_count as f64;
    score += 0.35 * pressure + 0.02 * pressure * pressure;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a "junk drawer" — using it up is good (subtract).
    let diff = mean_residual - r;
    if diff > 0.0 {
        score -= 0.5 * diff;
    } else {
        score += 0.25 * (-diff);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless dead space is egregious).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        // But if the placement would strand a large dead gap, soften the bonus.
        if r < dead_threshold * 0.5 {
            score += 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; give it a
    // neutral-ish baseline so it only wins when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.5 * pressure;
    }

    // Slight late-stream conservatism: as the stream progresses, prefer
    // filling existing bins tighter (dead space matters less at the end).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - r / bin_capacity as f64);

    score
}

