        if post_residual > 0 && post_residual < next_item_size {
            score += 40.0;
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 50.0;
    }

    // Penalize small unusable residuals that block future items (but not 0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive if no good fit exists elsewhere;
    // penalize mildly so open bins with decent fits win, but keep it viable
    // when post_residual of existing bins would be tiny/dead.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin perfectly fits the next item too.
            if bin_capacity - next_item_size == item_size {
                score -= 150.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Prefer bins with residuals far from mean (consolidate waste).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.5 * dev;

    // Late in the stream: favor closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

