    // Penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            let best_gap = (bin_residual - item_size) as f64;
            20.0 * (1.0 - best_gap / bin_capacity as f64)
        };
        score += 40.0 + pressure + 2.0 * open_bins_count as f64;
        // Early in the stream, allow more bins (exploration).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (less-filled bins absorb big items well),
    // but avoid spreading too thin when many bins are open.
    score += 0.15 * (mean_residual - bin_residual as f64);
    score += 0.05 * open_bins_count as f64;

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space avoidance: residuals too small for typical future items are wasted.
    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 60.0 * deadness * deadness;
    }

    // Perfect fill reward (scaled with progress).
    if post_residual == 0 {
        score -= 80.0 + 2.0 * progress;
    }

    // Lookahead: reward leaving room for the next item; penalize unusable gaps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if next_item_size == post_residual {
                score -= 11.0;
            }
            let after = post_residual - next_item_size;
            if after % 10 == 0 && after >= 20 {
                score -= 3.0;
            }
            if after == 0 {
                score -= 6.0;
            }
            if after > 0 && after < next_item_size {
                score += 1.5;
            }
            if after < 10 {
                score += 2.0;
            }
            if after >= next_item_size * 2 {
                score -= 2.0 + 2.0 * progress;
            } else if after < 4 {
                score += 2.0;
            }
            if after < 3 {
                score -= 2.0;
            }
            if after >= next_item_size.max(8) {
                score -= 1.0;
            }
            if after >= next_item_size * 3 {
                score -= 1.0;
            }
            if after >= 10 && after <= 20 {
                score -= 1.5;
            }
            if after >= next_item_size && after < next_item_size * 2 && fitting_bins_count >= 1 {
                score -= 1.0;
            }
            // small tail (<=5) after hosting next item is near-perfect; tighten with progress.
            if after > 0 && after <= 5 {
                score -= 1.0 + 1.0 * progress;
            }
            // large margin (>2x) with few fitting bins is a strong consolidation signal.
            if after >= next_item_size * 2 && fitting_bins_count <= 2 {
                score -= 1.0;
            }
            // residual able to host next item twice with a multiple-of-5 tail is ideal handoff.
            if after >= next_item_size && after % 5 == 0 && fitting_bins_count >= 1 {
                score -= 1.0;
            }
            // chain depth — post_residual hosting next 2x exactly leaves a perfect second slot.
            if after == next_item_size {
                score -= 1.5 + 1.0 * progress;
            }
            // post_residual hosting next twice with small (<=4) tail is a perfect double handoff.
            if after >= next_item_size && after - next_item_size <= 4 && after >= next_item_size {
                score -= 1.0;
            }
            // gen54: deep chain — post_residual hosting next 3x exactly is a triple handoff.
            if after == next_item_size * 2 {
                score -= 1.0 + 1.0 * progress;
            }
            // gen54: multiple-of-10 tails that remain reusable slots, deepened late.
            if after >= 10 && after % 10 == 0 && progress > 0.5 {
                score -= 1.0;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score += 15.0 + gap * (0.15 + 0.45 * scarcity);
            let dead_ratio = gap / bin_capacity as f64;
            score += dead_ratio * 46.0;
            if dead_ratio < 0.04 {
                score -= 4.5;
            }
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += stranded * 18.0;
            if post_residual < 20 {
                score += 5.0;
            }
            if fitting_bins_count >= 2 {
                score += 2.0;
            }
            if fitting_bins_count <= 1 {
                score += 1.5;
            }
            score += gap * 0.08;
            if post_residual + item_size >= bin_capacity * 9 / 10 {
                score -= 1.5;
            }
            if post_residual <= 4 {
                score -= 2.5;
            }
            if post_residual % 2 == 1 && post_residual > 5 {
                score += 1.5;
            }
            // large stranded residual just below next item wastes a big chunk.
            if post_residual >= 20 {
                score += (next_item_size - post_residual) as f64 * 0.06;
            }
            // near-miss residuals (within 2 of next item) are recoverable with tiny items; soften penalty.
            if gap <= 2.0 && post_residual >= 15 {
                score -= 3.0;
            }
            // near-miss band widened — gap <= 4 with substantial residual is partially recoverable.
            if gap > 2.0 && gap <= 4.0 && post_residual >= 20 {
                score -= 1.5;
            }
            // gen54: mid-band stranded residual (15..20) just below next — milder slope guard.
            if post_residual >= 15 && post_residual < 20 {
                score += (next_item_size - post_residual) as f64 * 0.04;
            }
        } else {
            if fitting_bins_count > 1 {
                score -= 3.0;
            }
        }
        if next_item_size > bin_capacity / 2 && post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
        if post_residual >= next_item_size && post_residual >= mean_residual as u32 {
