        }
        if item_size >= bin_capacity * 2 / 5 && item_size <= bin_capacity / 2 && fitting_bins_count == 0 && open_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 && new_left >= 25 && new_left < 35 && fitting_bins_count > 0 && next_item_size <= new_left {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= 11 && new_left <= 19 && new_left < next_item_size {
            score += 2.0;
        }
        if fitting_bins_count > 2 && open_bins_count > 0 && mean_residual > new_left as f64 * 1.5 {
            score += 2.5;
        }
        if item_size <= 10 && fitting_bins_count >= 1 && new_left >= 30 {
            score += 2.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size {
            let chain = new_left - next_item_size;
            if chain >= next_item_size / 2 && chain <= next_item_size {
                score -= 2.0;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left < next_item_size && new_left >= 15 {
            score += (next_item_size - new_left) as f64 * 0.18;
        }
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count > 0 {
            score += 3.0 * progress;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 2 && open_bins_count <= 3 {
            score -= 1.5;
        }
        if next_item_size == 0 && new_left > bin_capacity * 3 / 5 && open_bins_count > 2 {
            score += 2.0;
        }
        if fitting_bins_count >= 1 && item_size <= bin_capacity / 5 && mean_residual >= item_size as f64 * 2.0 {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && (new_left - next_item_size) <= 1 {
            score -= 2.0;
        }
        // fresh bins able to host item + next + next again with a multiple-of-5 leftover are near-perfect.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 3 && new_left % 5 == 0 {
            score -= 1.5;
        }
        // huge stranded fresh-bin leftover (>40% of capacity) just missing next item — scale with progress.
        if next_item_size > 0 && new_left < next_item_size && new_left > bin_capacity * 2 / 5 {
            score += (next_item_size - new_left) as f64 * (0.05 + 0.10 * progress);
        }
        // reward fresh bins whose leftover matches next item plus a small reusable (5..=9) band.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && new_left - next_item_size >= 5 && new_left - next_item_size <= 9 {
            score -= 1.0;
        }
        // late-stream — if an open bin's post_residual already fits next item closely, opening fresh strands capacity.
        if progress > 0.7 && fitting_bins_count >= 1 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score += 2.0;
        }
        // new-bin strictness — with several fitting open bins and a mid-size item, opening fresh is wasteful.
        if fitting_bins_count >= 2 && item_size <= bin_capacity / 4 && progress > 0.4 {
            score += 2.0 + 2.0 * progress;
        }
        // fresh bin whose leftover exactly equals a multiple of 10 and >= 20 leaves a reusable slot.
        if new_left >= 20 && new_left % 10 == 0 && fitting_bins_count >= 1 && next_item_size > 0 && next_item_size <= new_left {
            score -= 1.0;
        }
        // fresh-bin strictness tightened — with >=3 fitting open bins, opening fresh is strongly wasteful.
        if fitting_bins_count >= 3 && item_size <= bin_capacity / 2 {
            score += 2.0 + 2.0 * progress;
        }
        // fresh bins whose leftover hosts next exactly twice (tail == next) are perfect chains.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left == next_item_size * 2 {
            score -= 2.0;
        }
        // fresh-bin leftover that cannot host next but leaves a reusable 10-multiple band is acceptable.
        if next_item_size > 0 && new_left < next_item_size && new_left >= 10 && new_left % 10 == 0 {
            score -= 1.0;
        }
        // gen54: fresh bins whose leftover hosts next twice AND leaves an exact 10-multiple tail are ideal handoffs.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 3 && new_left % 10 == 0 {
            score -= 1.0 + 1.0 * progress;
        }
        // gen54: exact-tail perfection — fresh bin leaving leftover == 3*next exactly is a perfect chain, scarcity-weighted.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left == next_item_size * 3 {
            score -= 1.0 + 0.5 * (1.0 / (1.0 + fitting_bins_count as f64));
        }
        // gen54: mid-band dead-space guard — fresh-bin leftover just missing next in 25..40% capacity also strands usable space.
        if next_item_size > 0 && new_left < next_item_size && new_left > bin_capacity / 4 && new_left <= bin_capacity * 2 / 5 {
            score += (next_item_size - new_left) as f64 * (0.03 + 0.06 * progress);
        }
        // gen54: late-stream fresh bins must remain strictly justified — widen the near-chain detection band.
        if progress > 0.7 && fitting_bins_count >= 1 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score += 1.0 + progress;
        }
