        if next_item_size > 0 && post_residual >= 15 && post_residual <= 35 && post_residual % 5 == 0 && post_residual >= next_item_size {
            score -= 1.0;
        }
        // post_residual hosting next item twice (2x..3x) is a strong consolidation signal.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual < next_item_size * 3 {
            score -= 1.0;
        }
        // near-exact chain — post_residual exceeds next item by exactly 1..=3 with progress: deepen reward.
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 && progress > 0.6 {
            score -= 1.0;
        }
        // large post_residual (> half capacity) that cannot host next item is heavy dead space; penalize more.
        if next_item_size > 0 && post_residual > bin_capacity / 2 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
        // existing-bin exact double handoff — post_residual == 2*next with few fitting bins is a perfect chain.
        if next_item_size > 0 && post_residual == next_item_size * 2 && fitting_bins_count <= 3 {
            score -= 1.5;
        }
        // post_residual hosting next with a 10-multiple tail >= 10 leaves a reusable slot; reward with progress.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size >= 10 && (post_residual - next_item_size) % 10 == 0 && progress > 0.5 {
            score -= 1.0;
        }
        // gen54: mid-band dead-space guard for existing bins — post_residual just below next but 15..20 strands usable space.
        if next_item_size > 0 && post_residual >= 15 && post_residual < 20 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.04;
        }
        // gen54: chain deepening — existing bins whose post_residual hosts next twice and leaves a 10-multiple tail are perfect handoffs.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && (post_residual - next_item_size) % 10 == 0 {
            score -= 1.0 + 1.0 * progress;
        }
        // gen54: strong consolidation signal for post_residual >= 2x next with few fitting bins.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count <= 2 {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * (norm_pr * norm_pr));

    // Reward tight fits: penalize (subtract) when post_residual is small.
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap) * (1.0 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Penalize bins deviating from mean residual (encourage balance), smoothed.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for spreading across many bins early.
    score += 0.3 * open_bins_count as f64 * progress;

    // New-bin candidate: neutral base with slight progress-dependent preference.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress);
    }

    score
}

