pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into 10-wide bands.
    let post_class = (post_residual / 10) as f64;
    score += post_class * 2.0;

    // Perfect fit bonus: residual exactly 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead-space penalty for awkward mid-range residuals (harmonic "bad classes").
    // Residuals in (10, 30) are too small for most items (min size 1..100 unknown,
    // but empirically small items are rare) -> penalize.
    if post_residual > 10 && post_residual < 30 {
        score += 15.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic pairing: reward if next_item_size + post_residual forms a tight pair.
        let pair_waste = post_residual - next_item_size;
        if pair_waste == 0 {
            score -= 45.0;
        } else if pair_waste <= 10 {
            score -= 20.0;
        } else {
            score -= (pair_waste as f64) * 0.3;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's remainder: penalize proportionally
        // to how much dead space this creates relative to capacity.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly prefer using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a good fit. Make empty-bin score neutral-high unless
    // current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progress and open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 3.0 + progress * 10.0;
        // If next item is small, a fresh bin wastes its harmonics; slight penalty.
        if next_item_size > 0 && next_item_size <= 20 {
            score += 10.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "tight" bin — prefer consuming tight bins first.
    let residual_diff = mean_residual - bin_residual as f64;
    score += residual_diff * 0.4;

    // Prefer bins whose residual is an exact harmonic multiple of the item size.
    if item_size > 0 && bin_residual % item_size == 0 && bin_residual > item_size {
        score -= 8.0;
    }

    // Integer-division threshold on post_residual vs half capacity.
    if post_residual > bin_capacity / 2 {
        score -= 5.0; // leaving > half space is fine, keep bin flexible
    } else if post_residual < bin_capacity / 4 {
        score += 3.0; // leaving < quarter space creates near-dead bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even the smallest plausible item (<= 10)
    // or if it falls in the awkward 1..20 band that few items fill.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    } else if pr < 10 {
        // Dead space: unusable gap -> big penalty.
        score += 45.0;
    } else if pr < 20 {
        // Awkward gap: only tiny items can use it.
        score += 18.0;
    } else if pr < 35 {
        score += 6.0;
    }

    // Tight fit bonus: the closer the fill, the better (relative to capacity).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize alternatives implicitly by rewarding this).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0;
        // Extra reward for near-perfect lookahead fit.
        if pr - next_item_size < 10 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: discourage proliferation of open bins.
    // Applied to every candidate including the new-bin candidate so that
    // opening a new bin is only chosen when the fit is genuinely bad.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: it has pr = capacity - item; add a fixed opening cost
    // so it only wins when existing bins would create dead space.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Late in the stream, opening new bins is cheaper than carrying dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Slight preference for bins whose residual deviates from the mean
    // (consolidating space into fewer, fuller bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
