}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 8.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(3);

    // 2-step lookahead: strongly reward if the next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 14.0 * (1.0 - slack / (bin_capacity as f64));
        if slack == 0.0 {
            score -= 20.0; // perfect 2-step chain
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize wasted space relative to next item size.
        score += 3.0 * (next_item_size as f64 / (bin_capacity as f64));
    }

    // Relative-to-mean coupling: prefer bins whose residual is below average (tighter bins).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin only when no open bin offers a decent fit (post_residual small elsewhere)
        // and current item is large relative to capacity.
        let item_frac = item_size as f64 / bin_capacity as f64;
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score = 55.0 + 30.0 * item_frac - 12.0 * pressure;
        if next_item_size > 0 && (bin_capacity as u64 - item_size as u64) >= next_item_size as u64 {
            score -= 15.0; // new bin can also chain the next item
        }
        if fitting_bins_count <= 1 {
            score -= 10.0; // few alternatives -> new bin acceptable
        }
    }

    // Slight stream-progression modulation: later in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // Penalize bins whose residual is only slightly larger than the item
    // (awkward near-misses) but reward exact / near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item can fit into the post residual, reward it;
    // if the next item is small and post residual is large, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        }
        // If next item exactly fills post residual, big reward.
        if next_item_size == post_residual {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // existing fits are terrible (large post residual).
    if bin_residual == bin_capacity {
        score += 35.0 + 0.5 * open_bins_count as f64;
        // Early in the stream, opening bins is cheap (need parallelism).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Global state coupling: if mean residual is high, prefer bins with
    // residual below mean (consolidate the small leftovers).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Prefer fuller bins (smaller residual) mildly beyond post residual.
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    // Dead-space penalty: post residuals that are tiny but nonzero are
    // nearly useless; make them slightly less attractive than exact fills
    // but keep them better than medium waste.
    if post_residual > 0 && post_residual < item_size / 2 {
        score -= 8.0;
    }

    score
}

