pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Smooth non-linear coupling: quadratic dead-space penalty grows with stream progress
    let norm_pr = pr / cap;
    let dead_space = norm_pr * norm_pr * (1.0 + progress * 3.0);

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tight_fit_reward = -((1.0 - norm_pr) * (1.0 - norm_pr)) * (2.0 + progress * 4.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    let last_chance = if fitting_bins_count <= 1 { -8.0 * (1.0 + progress) } else { 0.0 };

    // Lookahead coupling: if next item fits into post_residual, reward this placement
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -3.0 * (1.0 - (next_item_size as f64 / cap))
    } else if next_item_size > 0 {
        1.5 * progress
    } else {
        0.0
    };

    // Mild preference for consolidating into fuller bins relative to mean residual
    let mean_pull = -(mean_residual - pr) * 0.05;

    // New-bin candidate: penalize opening a new bin mildly, more early in stream
    let new_bin_penalty = if bin_residual == bin_capacity {
        4.0 + 6.0 * (1.0 - progress) + open_bins_count as f64 * 0.1
    } else {
        0.0
    };

    base + dead_space + tight_fit_reward + last_chance + lookahead + mean_pull + new_bin_penalty
}

