                score -= 1.0 + 1.0 * progress;
            }
            // large margin (>2x) with few fitting bins is a strong consolidation signal.
            if after >= next_item_size * 2 && fitting_bins_count <= 2 {
                score -= 1.0;
            }
            // residual able to host next item twice with a multiple-of-5 tail is ideal handoff.
            if after >= next_item_size && after % 5 == 0 && fitting_bins_count >= 1 {
                score -= 1.0;
            }
            // gen52: chain-deepening — post_residual hosts next twice AND leaves a 10-multiple tail.
            if after >= next_item_size * 2 && after % 10 == 0 {
                score -= 1.0 + 1.0 * progress;
            }
            // gen52: two-step chain exactness — after == next_item_size is a perfect recursive handoff.
            if after == next_item_size && fitting_bins_count <= 3 {
                score -= 1.0 + 0.5 / (1.0 + fitting_bins_count as f64);
            }
            // gen56: tail in [5..=9] after hosting next is a reusable micro-slot; reward mildly.
            if after >= 5 && after <= 9 && fitting_bins_count <= 4 {
                score -= 0.5 + 0.5 * progress;
            }
            // gen56: tail exactly a multiple of next_item_size (2x, 3x, 4x) — deep chain possible.
            if next_item_size > 0 && after > 0 && after % next_item_size == 0 && after >= next_item_size * 2 {
                score -= 0.5 + 0.5 * progress;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score += 15.0 + gap * (0.15 + 0.45 * scarcity);
            let dead_ratio = gap / bin_capacity as f64;
            score += dead_ratio * 46.0;
            if dead_ratio < 0.04 {
                score -= 4.5;
            }
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += stranded * 18.0;
            if post_residual < 20 {
                score += 5.0;
            }
            if fitting_bins_count >= 2 {
                score += 2.0;
            }
            if fitting_bins_count <= 1 {
                score += 1.5;
            }
            score += gap * 0.08;
            if post_residual + item_size >= bin_capacity * 9 / 10 {
                score -= 1.5;
            }
            if post_residual <= 4 {
                score -= 2.5;
            }
            if post_residual % 2 == 1 && post_residual > 5 {
                score += 1.5;
            }
            // large stranded residual just below next item wastes a big chunk.
            if post_residual >= 20 {
                score += (next_item_size - post_residual) as f64 * 0.06;
            }
            // near-miss residuals (within 2 of next item) are recoverable with tiny items; soften penalty.
            if gap <= 2.0 && post_residual >= 15 {
                score -= 3.0;
            }
            // gen52: mid-band stranded residual (15..=19) also wastes usable space; mild slope.
            if post_residual >= 15 && post_residual < 20 {
                score += (next_item_size - post_residual) as f64 * 0.04;
            }
            // gen56: near-miss within 3 of next with high progress — a tiny item may follow; soften more.
            if gap <= 3.0 && progress > 0.6 {
                score -= 1.5 * progress;
            }
        } else {
            if fitting_bins_count > 1 {
                score -= 3.0;
            }
        }
        if next_item_size > bin_capacity / 2 && post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
        if post_residual >= next_item_size && post_residual >= mean_residual as u32 {
            score -= 1.5;
        }
        if post_residual > 0 && post_residual < next_item_size && post_residual > next_item_size.saturating_sub(4) {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count == 0 {
        score -= 10.0;
    }

    // Open-bin pressure: consolidate when many bins are open.
    score += 3.0 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Prefer residuals near the mean (anti-fragmentation), plus tight-bin flavor.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;
    score += 0.1 * (bin_residual as f64);

    // Fill-ratio flavor: near-full placements are excellent.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.75 {
        score -= 4.0;
    }

    // Exact-gap micro-rewards.
    let exact_gap = bin_residual.saturating_sub(item_size);
    if exact_gap <= 2 {
        score -= 5.0;
    } else if exact_gap <= 5 {
        score -= 2.0;
    } else if exact_gap <= 9 {
        score -= 1.0;
    }

    // NEW-BIN CANDIDATE LOGIC.
    if bin_residual == bin_capacity {
        let new_left = bin_capacity.saturating_sub(item_size);
        let big_item = item_size > bin_capacity / 2;
        let scarce = fitting_bins_count <= 1;

        if big_item && scarce {
            score -= 4.0;
        } else if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 2 {
            score -= 1.0;
        } else if item_size >= 40 && (fitting_bins_count == 0 || (item_size > bin_capacity / 3 && next_item_size > bin_capacity / 2)) {
            score -= 2.0;
        } else {
            score += 14.0;
        }

        if next_item_size > 0 && new_left == next_item_size && fitting_bins_count >= 1 {
            score -= 5.0;
        }
        if next_item_size > 0 && new_left < next_item_size && new_left < 15 && fitting_bins_count >= 1 {
            score += 3.0;
        }
        if new_left % 10 == 0 && new_left >= 20 && fitting_bins_count >= 1 {
            score -= 4.0;
        }
        if next_item_size > 0 && new_left >= next_item_size && new_left - next_item_size <= 3 && fitting_bins_count >= 1 {
            score -= 2.5;
        }
        if new_left <= 3 && fitting_bins_count >= 1 {
            score -= 6.0;
        }
        if new_left < 10 && fitting_bins_count >= 1 && next_item_size > new_left {
            score += 4.0;
        }
        if next_item_size > 0 && new_left >= next_item_size * 2 && fitting_bins_count >= 1 {
            score -= 2.5;
            if new_left < bin_capacity / 2 {
                score -= 1.5;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 3 {
            score -= 1.0;
        }
        if next_item_size > 0 && new_left < next_item_size && new_left >= 8 && (next_item_size - new_left) <= 4 {
            score += 4.0;
        }
        if next_item_size > 0 && new_left >= 20 && new_left < next_item_size && (next_item_size - new_left) <= 6 {
            score += 2.5;
        }
        if new_left == 10 || new_left == 15 || new_left == 20 || new_left == 25 || new_left == 30 {
            score -= 1.5;
        }
        if fitting_bins_count >= 3 && item_size <= bin_capacity / 3 {
            score += 3.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 && mean_residual >= item_size as f64 * 1.2 && item_size <= bin_capacity / 4 {
            score += 5.0;
        }
        if progress > 0.8 && fitting_bins_count > 0 && item_size < bin_capacity / 2 {
            score += 6.0 * (progress - 0.8) * 10.0;
        }
        if progress > 0.6 && fitting_bins_count >= 1 {
            score += 2.0 * (progress - 0.6) * 10.0;
        }
        if next_item_size >= bin_capacity * 2 / 5 && fitting_bins_count > 0 && item_size <= bin_capacity / 3 {
            score += 4.0;
        }
        if fitting_bins_count == 0 && open_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 6.0;
        }
        if next_item_size > 0 && new_left >= next_item_size {
            let leftover = new_left - next_item_size;
            if leftover > 0 && leftover < 8 {
                score -= 2.0;
            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && new_left < next_item_size {
            score += (next_item_size - new_left) as f64 * 0.12;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left > next_item_size && (new_left - next_item_size) % 10 == 0 && new_left - next_item_size >= 10 {
            score -= 2.5;
        }
        if next_item_size > 0 && new_left >= next_item_size && new_left < next_item_size * 3 && fitting_bins_count >= 1 {
            score -= 1.0;
        }
        if item_size >= bin_capacity * 2 / 5 && item_size <= bin_capacity / 2 && fitting_bins_count == 0 && open_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 && new_left >= 25 && new_left < 35 && fitting_bins_count > 0 && next_item_size <= new_left {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= 11 && new_left <= 19 && new_left < next_item_size {
            score += 2.0;
        }
        if fitting_bins_count > 2 && open_bins_count > 0 && mean_residual > new_left as f64 * 1.5 {
            score += 2.5;
        }
        if item_size <= 10 && fitting_bins_count >= 1 && new_left >= 30 {
            score += 2.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size {
            let chain = new_left - next_item_size;
            if chain >= next_item_size / 2 && chain <= next_item_size {
                score -= 2.0;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left < next_item_size && new_left >= 15 {
            score += (next_item_size - new_left) as f64 * 0.18;
        }
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count > 0 {
            score += 3.0 * progress;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 2 && open_bins_count <= 3 {
            score -= 1.5;
        }
        if next_item_size == 0 && new_left > bin_capacity * 3 / 5 && open_bins_count > 2 {
            score += 2.0;
        }
        if fitting_bins_count >= 1 && item_size <= bin_capacity / 5 && mean_residual >= item_size as f64 * 2.0 {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && (new_left - next_item_size) <= 1 {
            score -= 2.0;
        }
        // fresh bins able to host item + next + next again with a multiple-of-5 leftover are near-perfect.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 3 && new_left % 5 == 0 {
            score -= 1.5;
        }
        // huge stranded fresh-bin leftover (>40% of capacity) just missing next item — scale with progress.
        if next_item_size > 0 && new_left < next_item_size && new_left > bin_capacity * 2 / 5 {
            score += (next_item_size - new_left) as f64 * (0.05 + 0.10 * progress);
        }
        // gen52: extend dead-space guard to the mid band (25..40% capacity) with a milder slope.
        if next_item_size > 0 && new_left < next_item_size && new_left > bin_capacity / 4 && new_left <= bin_capacity * 2 / 5 {
            score += (next_item_size - new_left) as f64 * (0.03 + 0.06 * progress);
        }
        // reward fresh bins whose leftover matches next item plus a small reusable (5..=9) band.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && new_left - next_item_size >= 5 && new_left - next_item_size <= 9 {
            score -= 1.0;
        }
        // late-stream — if an open bin's post_residual already fits next item closely, opening fresh strands capacity.
        if progress > 0.7 && fitting_bins_count >= 1 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score += 2.0;
        }
        // new-bin strictness — with several fitting open bins and a mid-size item, opening fresh is wasteful.
        if fitting_bins_count >= 2 && item_size <= bin_capacity / 4 && progress > 0.4 {
            score += 2.0 + 2.0 * progress;
        }
        // fresh bin whose leftover exactly equals a multiple of 10 and >= 20 leaves a reusable slot.
        if new_left >= 20 && new_left % 10 == 0 && fitting_bins_count >= 1 && next_item_size > 0 && next_item_size <= new_left {
            score -= 1.0;
        }
        // gen52: fresh-bin chain exactness — leftover == 2*next or 3*next exactly is a perfect chain; scarcity-weighted.
        if next_item_size > 0 && fitting_bins_count >= 1 && (new_left == next_item_size * 2 || new_left == next_item_size * 3) {
            score -= 1.0 + 0.5 / (1.0 + fitting_bins_count as f64);
        }
        // gen52: fresh-bin leftover hosting next thrice with a 10-multiple tail is an ideal handoff; deepen with progress.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 3 && new_left % 10 == 0 {
            score -= 1.0 + 1.0 * progress;
        }
        // gen52: late-stream fresh bins must be strictly justified — widen the near-chain detection to <=5.
        if progress > 0.7 && fitting_bins_count >= 1 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score += 1.0 + progress;
        }
        // gen56: fresh-bin leftover an exact multiple of next_item_size (>=2x) — deep chain; reward with progress.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 2 && new_left % next_item_size == 0 {
            score -= 0.5 + 0.75 * progress;
        }
        // gen56: when many bins are open and mean residual already exceeds the fresh leftover, opening fresh is wasteful.
        if fitting_bins_count >= 2 && open_bins_count > 2 && next_item_size > 0 && mean_residual > new_left as f64 * 1.1 {
            score += 2.0;
        }
    } else {
        // Existing-bin refinements.
        if fitting_bins_count > 3 && post_residual > 30 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 3.0;
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 1.5;
        }
        let band = (post_residual as f64 - mean_residual).abs();
        if band < 5.0 && post_residual >= next_item_size.max(1) {
            score -= 1.0;
        }
        if post_residual < next_item_size && post_residual < mean_residual as u32 {
            score += 2.0;
        }
        let fits_small = post_residual / 10;
        score -= fits_small as f64 * 3.0;
        if post_residual >= 10 && post_residual <= 20 && next_item_size > post_residual {
            score += 13.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 && post_residual > 20 {
            score -= 1.5;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < next_item_size / 2 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size >= next_item_size {
            score -= 1.0;
        }
        if post_residual > 12 && post_residual < 25 && next_item_size > post_residual {
            score += 1.0;
        }
        if post_residual >= 18 && post_residual <= 22 && next_item_size > post_residual {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= 10 && post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual as f64 > mean_residual * 0.8 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let twice_left = post_residual - next_item_size;
            if twice_left >= next_item_size.max(8) {
                score -= 1.0;
            }
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 10 && after <= 20 {
                score -= 1.0;
            }
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count >= 1 {
            score -= 1.0 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 1 && progress > 0.5 {
            score -= 1.5;
        }
        if post_residual > 0 && (post_residual as f64) < 0.05 * bin_capacity as f64 {
            score -= 2.0 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 20 {
            score += 1.5;
        }
        // mid-band reusable residuals (multiple of 5, 15..=35) are valuable handoff slots.
        if next_item_size > 0 && post_residual >= 15 && post_residual <= 35 && post_residual % 5 == 0 && post_residual >= next_item_size {
            score -= 1.0;
        }
        // post_residual hosting next item twice (2x..3x) is a strong consolidation signal.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual < next_item_size * 3 {
            score -= 1.0;
        }
        // near-exact chain — post_residual exceeds next item by exactly 1..=3 with progress: deepen reward.
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 && progress > 0.6 {
            score -= 1.0;
        }
        // large post_residual (> half capacity) that cannot host next item is heavy dead space; penalize more.
        if next_item_size > 0 && post_residual > bin_capacity / 2 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
        // gen52: existing-bin chain deepening — post_residual hosting next twice AND leaving a 10-multiple tail is a perfect handoff.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && (post_residual - next_item_size) % 10 == 0 {
            score -= 1.0 + 1.0 * progress;
        }
        // gen52: near-perfect two-step chain — post_residual hosting next twice exactly (tail == next) when few bins fit.
        if next_item_size > 0 && post_residual == next_item_size * 2 && fitting_bins_count <= 3 {
            score -= 1.0 + 0.5 / (1.0 + fitting_bins_count as f64);
        }
        // gen52: mid-band dead-space guard — post_residual just below next but 15..=19 strands usable space.
        if next_item_size > 0 && post_residual >= 15 && post_residual < 20 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.04;
        }
        // gen52: strong consolidation for post_residual >= 2x next with few fitting bins.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count <= 2 {
            score -= 1.0;
        }
        // gen56: post_residual is an exact multiple of next_item_size (>=2x) — deep chain possible; scarcity-weighted reward.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual % next_item_size == 0 {
            score -= 0.5 + 0.75 * progress;
        }
        // gen56: post_residual in [5..=9] that cannot host next item is a tiny recoverable slot; soften slightly.
        if next_item_size > 0 && post_residual >= 5 && post_residual < 10 && post_residual < next_item_size && gap_small(next_item_size - post_residual) {
            score -= 1.0;
        }
    }

    score
}

fn gap_small(gap: u32) -> bool {
    gap <= 6
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space avoidance: residuals too small for typical future items are wasted.
    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 60.0 * deadness * deadness;
    }

    // Perfect fill reward (scaled with progress).
    if post_residual == 0 {
        score -= 80.0 + 2.0 * progress;
    }

    // Lookahead: reward leaving room for the next item; penalize unusable gaps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if next_item_size == post_residual {
                score -= 11.0;
            }
            let after = post_residual - next_item_size;
            if after % 10 == 0 && after >= 20 {
                score -= 3.0;
            }
            if after == 0 {
                score -= 6.0;
            }
            if after > 0 && after < next_item_size {
                score += 1.5;
            }
            if after < 10 {
                score += 2.0;
            }
            if after >= next_item_size * 2 {
                score -= 2.0 + 2.0 * progress;
            } else if after < 4 {
                score += 2.0;
            }
            if after < 3 {
                score -= 2.0;
            }
            if after >= next_item_size.max(8) {
                score -= 1.0;
            }
            if after >= next_item_size * 3 {
                score -= 1.0;
            }
            if after >= 10 && after <= 20 {
                score -= 1.5;
            }
            if after >= next_item_size && after < next_item_size * 2 && fitting_bins_count >= 1 {
                score -= 1.0;
            }
            // small tail (<=5) after hosting next item is near-perfect; tighten with progress.
            if after > 0 && after <= 5 {
                score -= 1.0 + 1.0 * progress;
            }
            // large margin (>2x) with few fitting bins is a strong consolidation signal.
            if after >= next_item_size * 2 && fitting_bins_count <= 2 {
                score -= 1.0;
            }
            // residual able to host next item twice with a multiple-of-5 tail is ideal handoff.
            if after >= next_item_size && after % 5 == 0 && fitting_bins_count >= 1 {
                score -= 1.0;
            }
            // gen52: chain-deepening — post_residual hosts next twice AND leaves a 10-multiple tail.
            if after >= next_item_size * 2 && after % 10 == 0 {
                score -= 1.0 + 1.0 * progress;
            }
            // gen52: two-step chain exactness — after == next_item_size is a perfect recursive handoff.
            if after == next_item_size && fitting_bins_count <= 3 {
                score -= 1.0 + 0.5 / (1.0 + fitting_bins_count as f64);
            }
            // gen56: two-item lookahead — after hosting next, can it also host the one after?
            // Prefer placements whose tail remains reusable for the following item stream.
            if after >= next_item_size.max(6) {
                score -= 1.0 + 1.5 * progress;
                if after >= next_item_size * 2 + next_item_size / 2 {
                    score -= 1.0;
                }
            }
            // gen56: tails in the 5..=9 band are half-dead; mild penalty slope to prefer 0 or >=10.
            if after >= 5 && after <= 9 {
                score += 0.8;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score += 15.0 + gap * (0.15 + 0.45 * scarcity);
            let dead_ratio = gap / bin_capacity as f64;
            score += dead_ratio * 46.0;
            if dead_ratio < 0.04 {
                score -= 4.5;
            }
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += stranded * 18.0;
            if post_residual < 20 {
                score += 5.0;
            }
            if fitting_bins_count >= 2 {
                score += 2.0;
            }
            if fitting_bins_count <= 1 {
                score += 1.5;
            }
            score += gap * 0.08;
            if post_residual + item_size >= bin_capacity * 9 / 10 {
                score -= 1.5;
            }
            if post_residual <= 4 {
                score -= 2.5;
            }
            if post_residual % 2 == 1 && post_residual > 5 {
                score += 1.5;
            }
            // large stranded residual just below next item wastes a big chunk.
            if post_residual >= 20 {
                score += (next_item_size - post_residual) as f64 * 0.06;
            }
            // near-miss residuals (within 2 of next item) are recoverable with tiny items; soften penalty.
            if gap <= 2.0 && post_residual >= 15 {
                score -= 3.0;
            }
            // gen52: mid-band stranded residual (15..=19) also wastes usable space; mild slope.
            if post_residual >= 15 && post_residual < 20 {
                score += (next_item_size - post_residual) as f64 * 0.04;
            }
            // gen56: near-miss band widened to <=4 — these residuals often host the next-next item.
            if gap <= 4.0 && post_residual >= 12 {
                score -= 2.0;
            }
        } else {
            if fitting_bins_count > 1 {
                score -= 3.0;
            }
        }
        if next_item_size > bin_capacity / 2 && post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
        if post_residual >= next_item_size && post_residual >= mean_residual as u32 {
            score -= 1.5;
        }
        if post_residual > 0 && post_residual < next_item_size && post_residual > next_item_size.saturating_sub(4) {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count == 0 {
        score -= 10.0;
    }

    // Open-bin pressure: consolidate when many bins are open.
    score += 3.0 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Prefer residuals near the mean (anti-fragmentation), plus tight-bin flavor.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;
    score += 0.1 * (bin_residual as f64);

    // Fill-ratio flavor: near-full placements are excellent.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.75 {
        score -= 4.0;
    }

    // Exact-gap micro-rewards.
    let exact_gap = bin_residual.saturating_sub(item_size);
    if exact_gap <= 2 {
        score -= 5.0;
    } else if exact_gap <= 5 {
        score -= 2.0;
    } else if exact_gap <= 9 {
        score -= 1.0;
    }

    // NEW-BIN CANDIDATE LOGIC.
    if bin_residual == bin_capacity {
        let new_left = bin_capacity.saturating_sub(item_size);
        let big_item = item_size > bin_capacity / 2;
        let scarce = fitting_bins_count <= 1;

        if big_item && scarce {
            score -= 4.0;
        } else if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 2 {
            score -= 1.0;
        } else if item_size >= 40 && (fitting_bins_count == 0 || (item_size > bin_capacity / 3 && next_item_size > bin_capacity / 2)) {
            score -= 2.0;
        } else {
            score += 14.0;
        }

        if next_item_size > 0 && new_left == next_item_size && fitting_bins_count >= 1 {
            score -= 5.0;
        }
        if next_item_size > 0 && new_left < next_item_size && new_left < 15 && fitting_bins_count >= 1 {
            score += 3.0;
        }
        if new_left % 10 == 0 && new_left >= 20 && fitting_bins_count >= 1 {
            score -= 4.0;
        }
        if next_item_size > 0 && new_left >= next_item_size && new_left - next_item_size <= 3 && fitting_bins_count >= 1 {
            score -= 2.5;
        }
        if new_left <= 3 && fitting_bins_count >= 1 {
            score -= 6.0;
        }
        if new_left < 10 && fitting_bins_count >= 1 && next_item_size > new_left {
            score += 4.0;
        }
        if next_item_size > 0 && new_left >= next_item_size * 2 && fitting_bins_count >= 1 {
            score -= 2.5;
            if new_left < bin_capacity / 2 {
                score -= 1.5;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 3 {
            score -= 1.0;
        }
        if next_item_size > 0 && new_left < next_item_size && new_left >= 8 && (next_item_size - new_left) <= 4 {
            score += 4.0;
        }
        if next_item_size > 0 && new_left >= 20 && new_left < next_item_size && (next_item_size - new_left) <= 6 {
            score += 2.5;
        }
        if new_left == 10 || new_left == 15 || new_left == 20 || new_left == 25 || new_left == 30 {
            score -= 1.5;
        }
        if fitting_bins_count >= 3 && item_size <= bin_capacity / 3 {
            score += 3.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 && mean_residual >= item_size as f64 * 1.2 && item_size <= bin_capacity / 4 {
            score += 5.0;
        }
        if progress > 0.8 && fitting_bins_count > 0 && item_size < bin_capacity / 2 {
            score += 6.0 * (progress - 0.8) * 10.0;
        }
        if progress > 0.6 && fitting_bins_count >= 1 {
            score += 2.0 * (progress - 0.6) * 10.0;
        }
        if next_item_size >= bin_capacity * 2 / 5 && fitting_bins_count > 0 && item_size <= bin_capacity / 3 {
            score += 4.0;
        }
        if fitting_bins_count == 0 && open_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 6.0;
        }
        if next_item_size > 0 && new_left >= next_item_size {
            let leftover = new_left - next_item_size;
            if leftover > 0 && leftover < 8 {
                score -= 2.0;
            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && new_left < next_item_size {
            score += (next_item_size - new_left) as f64 * 0.12;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left > next_item_size && (new_left - next_item_size) % 10 == 0 && new_left - next_item_size >= 10 {
            score -= 2.5;
        }
        if next_item_size > 0 && new_left >= next_item_size && new_left < next_item_size * 3 && fitting_bins_count >= 1 {
            score -= 1.0;
        }
        if item_size >= bin_capacity * 2 / 5 && item_size <= bin_capacity / 2 && fitting_bins_count == 0 && open_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 && new_left >= 25 && new_left < 35 && fitting_bins_count > 0 && next_item_size <= new_left {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= 11 && new_left <= 19 && new_left < next_item_size {
            score += 2.0;
        }
        if fitting_bins_count > 2 && open_bins_count > 0 && mean_residual > new_left as f64 * 1.5 {
            score += 2.5;
        }
        if item_size <= 10 && fitting_bins_count >= 1 && new_left >= 30 {
            score += 2.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size {
            let chain = new_left - next_item_size;
            if chain >= next_item_size / 2 && chain <= next_item_size {
                score -= 2.0;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left < next_item_size && new_left >= 15 {
            score += (next_item_size - new_left) as f64 * 0.18;
        }
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count > 0 {
            score += 3.0 * progress;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 2 && open_bins_count <= 3 {
            score -= 1.5;
        }
        if next_item_size == 0 && new_left > bin_capacity * 3 / 5 && open_bins_count > 2 {
            score += 2.0;
        }
        if fitting_bins_count >= 1 && item_size <= bin_capacity / 5 && mean_residual >= item_size as f64 * 2.0 {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && (new_left - next_item_size) <= 1 {
            score -= 2.0;
        }
        // fresh bins able to host item + next + next again with a multiple-of-5 leftover are near-perfect.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 3 && new_left % 5 == 0 {
            score -= 1.5;
        }
        // huge stranded fresh-bin leftover (>40% of capacity) just missing next item — scale with progress.
        if next_item_size > 0 && new_left < next_item_size && new_left > bin_capacity * 2 / 5 {
            score += (next_item_size - new_left) as f64 * (0.05 + 0.10 * progress);
        }
        // gen52: extend dead-space guard to the mid band (25..40% capacity) with a milder slope.
        if next_item_size > 0 && new_left < next_item_size && new_left > bin_capacity / 4 && new_left <= bin_capacity * 2 / 5 {
            score += (next_item_size - new_left) as f64 * (0.03 + 0.06 * progress);
        }
        // reward fresh bins whose leftover matches next item plus a small reusable (5..=9) band.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && new_left - next_item_size >= 5 && new_left - next_item_size <= 9 {
            score -= 1.0;
        }
        // late-stream — if an open bin's post_residual already fits next item closely, opening fresh strands capacity.
        if progress > 0.7 && fitting_bins_count >= 1 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score += 2.0;
        }
        // new-bin strictness — with several fitting open bins and a mid-size item, opening fresh is wasteful.
        if fitting_bins_count >= 2 && item_size <= bin_capacity / 4 && progress > 0.4 {
            score += 2.0 + 2.0 * progress;
        }
        // fresh bin whose leftover exactly equals a multiple of 10 and >= 20 leaves a reusable slot.
        if new_left >= 20 && new_left % 10 == 0 && fitting_bins_count >= 1 && next_item_size > 0 && next_item_size <= new_left {
            score -= 1.0;
        }
        // gen52: fresh-bin chain exactness — leftover == 2*next or 3*next exactly is a perfect chain; scarcity-weighted.
        if next_item_size > 0 && fitting_bins_count >= 1 && (new_left == next_item_size * 2 || new_left == next_item_size * 3) {
            score -= 1.0 + 0.5 / (1.0 + fitting_bins_count as f64);
        }
        // gen52: fresh-bin leftover hosting next thrice with a 10-multiple tail is an ideal handoff; deepen with progress.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 3 && new_left % 10 == 0 {
            score -= 1.0 + 1.0 * progress;
        }
        // gen52: late-stream fresh bins must be strictly justified — widen the near-chain detection to <=5.
        if progress > 0.7 && fitting_bins_count >= 1 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score += 1.0 + progress;
        }
        // gen56: fresh-bin justification via mean-residual comparison — if open bins already carry
        // enough average slack for this item, opening a fresh bin strands capacity.
        if fitting_bins_count >= 1 && mean_residual >= item_size as f64 * 1.5 && item_size <= bin_capacity / 3 {
            score += 2.0 + 2.0 * progress;
        }
        // gen56: fresh bins whose leftover is a multiple of 5 within 15..=45 form reusable slots.
        if new_left >= 15 && new_left <= 45 && new_left % 5 == 0 && fitting_bins_count >= 1 {
            score -= 1.0;
        }
    } else {
        // Existing-bin refinements.
        if fitting_bins_count > 3 && post_residual > 30 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 3.0;
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 1.5;
        }
        let band = (post_residual as f64 - mean_residual).abs();
        if band < 5.0 && post_residual >= next_item_size.max(1) {
            score -= 1.0;
        }
        if post_residual < next_item_size && post_residual < mean_residual as u32 {
            score += 2.0;
        }
        let fits_small = post_residual / 10;
        score -= fits_small as f64 * 3.0;
        if post_residual >= 10 && post_residual <= 20 && next_item_size > post_residual {
            score += 13.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 && post_residual > 20 {
            score -= 1.5;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < next_item_size / 2 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size >= next_item_size {
            score -= 1.0;
        }
        if post_residual > 12 && post_residual < 25 && next_item_size > post_residual {
            score += 1.0;
        }
        if post_residual >= 18 && post_residual <= 22 && next_item_size > post_residual {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= 10 && post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual as f64 > mean_residual * 0.8 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let twice_left = post_residual - next_item_size;
            if twice_left >= next_item_size.max(8) {
                score -= 1.0;
            }
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 10 && after <= 20 {
                score -= 1.0;
            }
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count >= 1 {
            score -= 1.0 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 1 && progress > 0.5 {
            score -= 1.5;
        }
        if post_residual > 0 && (post_residual as f64) < 0.05 * bin_capacity as f64 {
            score -= 2.0 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 20 {
            score += 1.5;
        }
        // mid-band reusable residuals (multiple of 5, 15..=35) are valuable handoff slots.
        if next_item_size > 0 && post_residual >= 15 && post_residual <= 35 && post_residual % 5 == 0 && post_residual >= next_item_size {
            score -= 1.0;
        }
        // post_residual hosting next item twice (2x..3x) is a strong consolidation signal.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual < next_item_size * 3 {
            score -= 1.0;
        }
        // near-exact chain — post_residual exceeds next item by exactly 1..=3 with progress: deepen reward.
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 && progress > 0.6 {
            score -= 1.0;
        }
        // large post_residual (> half capacity) that cannot host next item is heavy dead space; penalize more.
        if next_item_size > 0 && post_residual > bin_capacity / 2 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
        // gen52: existing-bin chain deepening — post_residual hosting next twice AND leaving a 10-multiple tail is a perfect handoff.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && (post_residual - next_item_size) % 10 == 0 {
            score -= 1.0 + 1.0 * progress;
        }
        // gen52: near-perfect two-step chain — post_residual hosting next twice exactly (tail == next) when few bins fit.
        if next_item_size > 0 && post_residual == next_item_size * 2 && fitting_bins_count <= 3 {
            score -= 1.0 + 0.5 / (1.0 + fitting_bins_count as f64);
        }
        // gen52: mid-band dead-space guard — post_residual just below next but 15..=19 strands usable space.
        if next_item_size > 0 && post_residual >= 15 && post_residual < 20 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.04;
        }
        // gen52: strong consolidation for post_residual >= 2x next with few fitting bins.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count <= 2 {
            score -= 1.0;
        }
        // gen56: residual within 1..=2 of the next item is a near-perfect handoff — deepen the reward late.
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 2 && progress > 0.4 {
            score -= 1.0 + progress;
        }
        // gen56: post_residual >= 3x next with a 5-multiple tail is an ideal multi-item chain.
        if next_item_size > 0 && post_residual >= next_item_size * 3 && post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space avoidance: residuals too small for typical future items are wasted.
    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 60.0 * deadness * deadness;
    }

    // Perfect fill reward (scaled with progress).
    if post_residual == 0 {
        score -= 80.0 + 2.0 * progress;
    }

    // Lookahead: reward leaving room for the next item; penalize unusable gaps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if next_item_size == post_residual {
                score -= 11.0;
            }
            let after = post_residual - next_item_size;
            if after % 10 == 0 && after >= 20 {
                score -= 3.0;
            }
            if after == 0 {
                score -= 6.0;
            }
            if after > 0 && after < next_item_size {
                score += 1.5;
            }
            if after < 10 {
                score += 2.0;
            }
            if after >= next_item_size * 2 {
                score -= 2.0 + 2.0 * progress;
            } else if after < 4 {
                score += 2.0;
            }
            if after < 3 {
                score -= 2.0;
            }
            if after >= next_item_size.max(8) {
                score -= 1.0;
            }
            if after >= next_item_size * 3 {
                score -= 1.0;
            }
            if after >= 10 && after <= 20 {
                score -= 1.5;
            }
            if after >= next_item_size && after < next_item_size * 2 && fitting_bins_count >= 1 {
                score -= 1.0;
            }
            // small tail (<=5) after hosting next item is near-perfect; tighten with progress.
            if after > 0 && after <= 5 {
                score -= 1.0 + 1.0 * progress;
            }
            // large margin (>2x) with few fitting bins is a strong consolidation signal.
            if after >= next_item_size * 2 && fitting_bins_count <= 2 {
                score -= 1.0;
            }
            // residual able to host next item twice with a multiple-of-5 tail is ideal handoff.
            if after >= next_item_size && after % 5 == 0 && fitting_bins_count >= 1 {
                score -= 1.0;
            }
            // chain-deepening — post_residual hosts next twice AND leaves a 10-multiple tail.
            if after >= next_item_size * 2 && after % 10 == 0 {
                score -= 1.0 + 1.0 * progress;
            }
            // two-step chain exactness — after == next_item_size is a perfect recursive handoff.
            if after == next_item_size && fitting_bins_count <= 3 {
                score -= 1.0 + 0.5 / (1.0 + fitting_bins_count as f64);
            }
            // gen56: three-step chain exactness — post hosts next thrice exactly; scarcity-weighted.
            if after == next_item_size * 2 && fitting_bins_count <= 3 {
                score -= 0.5 + 0.5 / (1.0 + fitting_bins_count as f64);
            }
            // gen56: tail in a reusable 5..=9 band after hosting next is a good micro-slot.
            if after >= 5 && after <= 9 && progress > 0.4 {
                score -= 0.5 + 0.5 * progress;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score += 15.0 + gap * (0.15 + 0.45 * scarcity);
            let dead_ratio = gap / bin_capacity as f64;
            score += dead_ratio * 46.0;
            if dead_ratio < 0.04 {
                score -= 4.5;
            }
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += stranded * 18.0;
            if post_residual < 20 {
                score += 5.0;
            }
            if fitting_bins_count >= 2 {
                score += 2.0;
            }
            if fitting_bins_count <= 1 {
                score += 1.5;
            }
            score += gap * 0.08;
            if post_residual + item_size >= bin_capacity * 9 / 10 {
                score -= 1.5;
            }
            if post_residual <= 4 {
                score -= 2.5;
            }
            if post_residual % 2 == 1 && post_residual > 5 {
                score += 1.5;
            }
            // large stranded residual just below next item wastes a big chunk.
            if post_residual >= 20 {
                score += (next_item_size - post_residual) as f64 * 0.06;
            }
            // near-miss residuals (within 2 of next item) are recoverable with tiny items; soften penalty.
            if gap <= 2.0 && post_residual >= 15 {
                score -= 3.0;
            }
            // mid-band stranded residual (15..=19) also wastes usable space; mild slope.
            if post_residual >= 15 && post_residual < 20 {
                score += (next_item_size - post_residual) as f64 * 0.04;
            }
            // gen56: near-miss within 5 of next with high fill is recoverable; extra softening late.
            if gap <= 5.0 && gap > 2.0 && post_residual + item_size >= bin_capacity * 3 / 4 {
                score -= 1.5 + 1.5 * progress;
            }
        } else {
            if fitting_bins_count > 1 {
                score -= 3.0;
            }
        }
        if next_item_size > bin_capacity / 2 && post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
        if post_residual >= next_item_size && post_residual >= mean_residual as u32 {
            score -= 1.5;
        }
        if post_residual > 0 && post_residual < next_item_size && post_residual > next_item_size.saturating_sub(4) {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count == 0 {
        score -= 10.0;
    }

    // Open-bin pressure: consolidate when many bins are open.
    score += 3.0 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Prefer residuals near the mean (anti-fragmentation), plus tight-bin flavor.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;
    score += 0.1 * (bin_residual as f64);

    // Fill-ratio flavor: near-full placements are excellent.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.75 {
        score -= 4.0;
    }

    // Exact-gap micro-rewards.
    let exact_gap = bin_residual.saturating_sub(item_size);
    if exact_gap <= 2 {
