        }
        // gen56: fresh-bin leftover in a 10..=20 reusable band (multiple of 5) is a good handoff slot.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= 10 && new_left <= 20 && new_left % 5 == 0 {
