        if next_item_size > 0 && post_residual >= 15 && post_residual < 20 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.04;
        }
        // gen52: strong consolidation for post_residual >= 2x next with few fitting bins.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count <= 2 {
            score -= 1.0;
        }
        // gen56: post_residual == next*3 exactly with few fitting bins — perfect three-step chain.
        if next_item_size > 0 && post_residual == next_item_size * 3 && fitting_bins_count <= 3 {
            score -= 0.5 + 0.5 / (1.0 + fitting_bins_count as f64);
        }
        // gen56: small reusable residual band (5..=9) just below next — slight dead-space guard.
        if next_item_size > 0 && post_residual >= 5 && post_residual < 10 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
        // gen56: tail in 10..=20 after hosting next — progress-scaled consolidation bonus.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 10 && tail <= 20 {
                score -= 0.5 + 0.5 * progress;
            }
        }
        // gen56: late-stream exact handoff — post_residual == next item exactly is a perfect fill.
        if progress > 0.75 && next_item_size > 0 && post_residual == next_item_size {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Dead-space avoidance: residuals too small for typical future items are wasted.
    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 65.0 * deadness * deadness;
    }

    // Perfect fill reward (progress-scaled).
    if post_residual == 0 {
        score -= 80.0 + 2.0 * progress;
    }

    // Lookahead: reward leaving room for the next item; penalize unusable gaps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if next_item_size == post_residual {
                score -= 13.0;
            }
            let after = post_residual - next_item_size;
            if after % 10 == 0 && after >= 20 {
                score -= 3.0;
            }
            if after == 0 {
                score -= 6.0;
            }
            if after > 0 && after < next_item_size {
                score += 1.5;
            }
            if after < 10 {
                score += 2.0;
            }
            if after >= next_item_size * 2 {
                score -= 2.0 + 2.0 * progress;
            } else if after < 4 {
                score += 2.0;
            }
            if after < 3 {
                score -= 2.0;
            }
            if after >= next_item_size.max(8) {
                score -= 1.0;
            }
            if after >= next_item_size * 3 {
                score -= 1.0;
            }
            // Chain: after next item, still can host half of next size again.
            if after >= next_item_size / 2 && after <= next_item_size {
                score -= 1.0;
            }
            // gen41: two-step chain — after hosting next, still host next again.
            if after >= next_item_size * 2 && open_bins_count <= 4 {
                score -= 1.0;
            }
            // gen57: residual that can host next item twice with a tiny tail is premium.
            let tail = after % next_item_size.max(1);
            if after >= next_item_size * 2 && tail <= 2 {
                score -= 1.5;
            }
        } else if post_residual > 0 {
            // Gap the known next item cannot use.
            let gap = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score += 15.0 + gap * (0.15 + 0.45 * scarcity);
            let dead_ratio = gap / bin_capacity as f64;
            score += dead_ratio * 46.0;
            if dead_ratio < 0.04 {
                score -= 4.5;
            }
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += stranded * 18.0;
            if post_residual < 20 {
                score += 5.0;
            }
            if fitting_bins_count >= 2 {
                score += 2.0;
            }
            if fitting_bins_count <= 1 {
                score += 1.5;
            }
            score += gap * 0.08;
            if post_residual + item_size >= bin_capacity * 9 / 10 {
                score -= 1.5;
            }
            if post_residual <= 4 {
                score -= 2.5;
            }
            // Stranded chunk scaled with size when just under next item.
            if post_residual >= 15 {
                score += gap * 0.10;
            }
            // gen41: near-miss gap of 1-2 units is nearly a perfect fill — soften penalty.
            if gap <= 2.0 && post_residual >= 10 {
                score -= 3.0;
            }
            // gen57: when many bins can still fit the item, a stranded gap hurts less.
            if fitting_bins_count >= 3 {
                score -= gap * 0.12;
            }
        } else {
            if fitting_bins_count > 1 {
                score -= 3.0;
            }
        }
        if next_item_size > bin_capacity / 2 && post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
        if post_residual >= next_item_size && post_residual >= mean_residual as u32 {
            score -= 1.5;
        }
        if post_residual > 0 && post_residual < next_item_size && post_residual > next_item_size.saturating_sub(4) {
            score += 2.0;
        }
        // Exact-next fit on existing bins is ideal.
        if post_residual == next_item_size {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count == 0 {
        score -= 10.0;
    }

    // Open-bin pressure: consolidate when many bins are open.
    score += 3.0 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Prefer residuals near the mean (anti-fragmentation), plus tight-bin flavor.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;
    score += 0.1 * (bin_residual as f64);

    // Fill-ratio flavor: near-full placements are excellent.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
