        }
        if next_item_size > 0 && post_residual >= 10 && post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual as f64 > mean_residual * 0.8 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let twice_left = post_residual - next_item_size;
            if twice_left >= next_item_size.max(8) {
                score -= 1.0;
            }
            if twice_left >= 10 && twice_left % 10 == 0 {
                score -= 1.5;
            }
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count >= 1 {
            score -= 1.0 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 1 && progress > 0.5 {
            score -= 1.5;
        }
        if fitting_bins_count > 3 && post_residual > 30 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 3.0;
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 1.5;
        }
        let band = (post_residual as f64 - mean_residual).abs();
        if band < 5.0 && post_residual >= next_item_size.max(1) {
            score -= 1.0;
        }
        if post_residual < next_item_size && post_residual < mean_residual as u32 {
            score += 2.0;
        }
        // gen57: mid-band residual (25-40) that cannot host next is a prime fragmentation source.
        if next_item_size > 0 && post_residual >= 25 && post_residual <= 40 && post_residual < next_item_size {
            score += 1.5;
        }
        // gen41: existing bin that closes exactly with the item after next is ideal late-stream.
        if next_item_size > 0 && post_residual == 0 && progress > 0.5 {
            score -= 2.0;
        }
    }

    // NEW-BIN CANDIDATE LOGIC.
    if bin_residual == bin_capacity {
        let new_left = bin_capacity.saturating_sub(item_size);
        let big_item = item_size > bin_capacity / 2;
        let scarce = fitting_bins_count <= 1;

        if big_item && scarce {
            score -= 4.0;
        } else if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 2 {
            score -= 1.0;
        } else if item_size >= 40 && (fitting_bins_count == 0 || (item_size > bin_capacity / 3 && next_item_size > bin_capacity / 2)) {
            score -= 2.0;
        } else {
            score += 14.0;
        }

        if next_item_size > 0 && new_left == next_item_size && fitting_bins_count >= 1 {
            score -= 5.0;
        }
        if next_item_size > 0 && new_left < next_item_size && new_left < 15 && fitting_bins_count >= 1 {
            score += 3.0;
        }
        if new_left % 10 == 0 && new_left >= 20 && fitting_bins_count >= 1 {
            score -= 4.0;
        }
        if next_item_size > 0 && new_left >= next_item_size && new_left - next_item_size <= 3 && fitting_bins_count >= 1 {
            score -= 2.5;
        }
        if new_left <= 3 && fitting_bins_count >= 1 {
            score -= 6.0;
        }
        if new_left < 10 && fitting_bins_count >= 1 && next_item_size > new_left {
            score += 4.0;
        }
        if next_item_size > 0 && new_left >= next_item_size * 2 && fitting_bins_count >= 1 {
            score -= 2.5;
            if new_left < bin_capacity / 2 {
