pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: residuals divisible by large powers of 2
    // or by 10 pair well with common item sizes; odd tiny residuals are dead space.
    let mut r = post_residual;
    let mut two_div = 0u32;
    while r > 0 && r % 2 == 0 { two_div += 1; r /= 2; }
    score -= 4.0 * two_div as f64;

    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0; // round residual is highly reusable
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.5;
    } else if post_residual > 0 && post_residual < 10 {
        score += 15.0; // near-dead space: unusable for most items
    }

    // Integer-division thresholds on post_residual
    if post_residual >= 50 {
        score -= 8.0; // half-full or more room left: keep flexible
    } else if post_residual <= 5 && post_residual > 0 {
        score -= 20.0; // perfect tight fit, excellent closure
    }

    // Lookahead coupling: can next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic match: next item leaves a round remainder again
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 6.0; // next item won't chain into this bin
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening fresh bins when decent fits exist,
    // but allow it when this item would leave awkward residue in every open bin.
    if bin_residual == bin_capacity {
        let awkward = post_residual > 0 && post_residual < 10;
        if awkward {
            score -= 30.0; // opening fresh is better than creating dead space
        } else {
            score += 12.0 + 0.05 * open_bins_count as f64;
        }
    }

    // Late in the stream, tighten packing: prefer smallest residuals more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins already tighter than average
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

