}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps below a practical threshold (can only host tiny items) are near-waste.
    if post_residual > 0 && post_residual < 25 {
        score += 12.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Reward a residual that still fits the lookahead item (keeps bin useful).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 as u32 {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, discourage opening yet another.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 25.0 + 30.0 * (open_bins_count as f64 / 20.0).min(1.0) + 10.0 * progress;
    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate: neutral base + penalty so it only wins
        // when every open bin would create severe dead space.
        score = bin_capacity as f64 * 0.8 + new_bin_penalty;
        // A new bin is more attractive early when few bins are open.
        score -= 15.0 * (1.0 - (open_bins_count as f64 / 15.0).min(1.0));
        return score;
    }

    // Slight preference for bins with below-average residual (tighter bins
    // first), keeping wider gaps available for larger future items.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

