        if next_item_size > 0 && post_residual >= 15 && post_residual < 20 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.04;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count <= 2 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual % 5 == 0 && fitting_bins_count <= 2 {
            score -= 0.5 + 0.5 * progress;
        }
        // NEW: residual that fits next item exactly twice is a perfect handoff.
        if next_item_size > 0 && post_residual == next_item_size * 2 {
            score -= 2.5;
        }
        // NEW: mid-band residual (25..=35) that cannot host next is nearly dead when scarce alternatives exist.
        if next_item_size > 0 && post_residual >= 25 && post_residual <= 35 && post_residual < next_item_size && fitting_bins_count <= 2 {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item exactly fills the new residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - pair_waste / bin_capacity as f64);
            score += pair_waste * 0.5;
        } else {
            // next item cannot fit here; slight penalty proportional to overshoot.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Prefer bins tighter than the mean residual (fill full bins first).
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit decently.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 20.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.2 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space avoidance: residuals too small for typical future items are wasted.
    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 60.0 * deadness * deadness;
    }

    // Perfect fill reward (scaled with progress).
    if post_residual == 0 {
        score -= 80.0 + 2.0 * progress;
    }

    // Lookahead: reward leaving room for the next item; penalize unusable gaps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if next_item_size == post_residual {
                score -= 11.0;
            }
            let after = post_residual - next_item_size;
