        // COMBINED: fresh-bin leftover hosting next with 10..=20 tail — moderate reusable-slot reward.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && new_left - next_item_size >= 10 && new_left - next_item_size <= 20 {
