        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 20 {
            score += 1.5;
        }
        // mid-band reusable residuals (multiple of 5, 15..=35) are valuable handoff slots.
        if next_item_size > 0 && post_residual >= 15 && post_residual <= 35 && post_residual % 5 == 0 && post_residual >= next_item_size {
            score -= 1.0;
        }
        // post_residual hosting next item twice (2x..3x) is a strong consolidation signal.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual < next_item_size * 3 {
            score -= 1.0;
        }
        // near-exact chain — post_residual exceeds next item by exactly 1..=3 with progress: deepen reward.
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 && progress > 0.6 {
