        }
        // large post_residual (> half capacity) that cannot host next item is heavy dead space; penalize more.
        if next_item_size > 0 && post_residual > bin_capacity / 2 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
        // existing-bin exact double handoff — post_residual == 2*next with few fitting bins is a perfect chain.
        if next_item_size > 0 && post_residual == next_item_size * 2 && fitting_bins_count <= 3 {
            score -= 1.5;
        }
        // post_residual hosting next with a 10-multiple tail >= 10 leaves a reusable slot; reward with progress.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size >= 10 && (post_residual - next_item_size) % 10 == 0 && progress > 0.5 {
            score -= 1.0;
        }
        // mid-band dead-space guard for existing bins — post_residual just below next but 15..20 strands usable space.
        if next_item_size > 0 && post_residual >= 15 && post_residual < 20 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.04;
        }
        // chain deepening — existing bins whose post_residual hosts next twice and leaves a 10-multiple tail are perfect handoffs.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && (post_residual - next_item_size) % 10 == 0 {
            score -= 1.0 + 1.0 * progress;
        }
        // strong consolidation signal for post_residual >= 2x next with few fitting bins.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count <= 2 {
            score -= 1.0;
        }
        // COMBINED: exact triple handoff — post_residual == 3*next with few fitting bins.
        if next_item_size > 0 && post_residual == next_item_size * 3 && fitting_bins_count <= 3 {
            score -= 0.5 + 0.5 * (1.0 / (1.0 + fitting_bins_count as f64));
        }
        // COMBINED: reusable tail band 10..=20 after hosting next, progress-weighted.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 10 && tail <= 20 {
                score -= 0.5 + 0.5 * progress;
            }
        }
        // COMBINED: small recoverable band 5..=15 below next — mild slope.
        if next_item_size > 0 && post_residual >= 5 && post_residual < 15 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
        // COMBINED: late-stream exact-match post_residual is a perfect close-out.
        if progress > 0.75 && next_item_size > 0 && post_residual == next_item_size {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero is ideal).
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3) * 40.0;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Next item won't fit here; penalize leaving awkward leftovers.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance logic: this is the only bin that fits; reward heavily to
    // avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive if current fit is poor or few open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize new bins more as stream progresses (consolidation phase),
        // but allow early exploration when open bins are few.
        score += 45.0 + 55.0 * progress - (open_bins_count as f64).recip() * 10.0;
        // If the item fits very badly in all existing bins (tightness low means
        // perfect fit here since empty bin => post_residual = C - item), compare
        // against mean residual: if mean residual is much larger than item,
        // opening fresh may be reasonable.
        if mean_residual > item_size as f64 * 1.5 {
            score -= 20.0;
        }
        let _ = tightness;
    }

    // Mild reward for filling bins that are already much emptier than average
    // (balance the pool of open bins).
    if !is_new_bin {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Time-horizon modulation: late in the stream, prefer consolidation.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Dead-space avoidance: residuals too small for a typical future item are worthless.
    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 60.0 * deadness * deadness;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 80.0 + 2.0 * progress;
    }

    // 10-band reuse bonus (borrowed from best): multiples of 10 are reusable anchors.
    let fits_small = post_residual / 10;
    score -= fits_small as f64 * 1.5;

    // Lookahead: reward leaving room for the next item; penalize unusable gaps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            let after = post_residual - next_item_size;
            if after % 10 == 0 && after >= 20 {
                score -= 3.0;
            }
            if after == 0 {
                score -= 7.0;
            }
            if after > 0 && after < 6 {
                score += 3.0;
            }
            if after >= next_item_size * 2 {
                score -= 2.0 + 2.0 * progress;
            }
            if after < 3 {
                score -= 2.0;
            }
            // Two-step lookahead: residual after next item still hosts another copy.
            if after >= next_item_size.max(8) {
                score -= 1.0;
            }
            // Near-exact closure is ideal, stronger late.
            if after <= 1 && progress > 0.5 {
                score -= 1.5;
            }
            if after >= next_item_size && after < next_item_size * 3 {
                score -= 1.0;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score += 15.0 + gap * (0.35 + 0.25 * scarcity);
            let dead_ratio = gap / bin_capacity as f64;
            score += dead_ratio * 42.0;
            if dead_ratio < 0.04 {
                score -= 4.0;
            }
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += stranded * 18.0;
            if post_residual < 20 {
                score += 5.0;
            }
            if fitting_bins_count <= 1 {
                score += 1.5;
            }
            score += gap * 0.08;
        } else {
            if fitting_bins_count > 1 {
                score -= 3.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count == 0 {
        score -= 10.0;
    }

    // Open-bin pressure: consolidate when many bins are open.
    score += 3.0 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Prefer residuals near the mean (anti-fragmentation), plus tight-bin flavor.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;
    score += 0.1 * (bin_residual as f64);

    // Fill-ratio flavor: near-full placements are excellent.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.75 {
        score -= 4.0;
    }

    // Exact-gap micro-rewards.
    let exact_gap = bin_residual.saturating_sub(item_size);
    if exact_gap <= 2 {
        score -= 5.0;
    } else if exact_gap <= 5 {
        score -= 2.0;
    } else if exact_gap <= 9 {
        score -= 1.0;
    }

    // NEW-BIN CANDIDATE LOGIC.
    if bin_residual == bin_capacity {
        let new_left = bin_capacity.saturating_sub(item_size);
        let big_item = item_size > bin_capacity / 2;
        let scarce = fitting_bins_count <= 1;

        if big_item && scarce {
            score -= 6.0;
        } else if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 2 {
            score -= 2.0;
        } else if item_size >= 40 && (fitting_bins_count == 0 || (item_size > bin_capacity / 3 && next_item_size > bin_capacity / 2)) {
            score -= 2.0;
        } else {
            score += 14.0;
        }

        if next_item_size > 0 && new_left == next_item_size && fitting_bins_count >= 1 {
            score -= 5.0;
        }
        if next_item_size > 0 && new_left < next_item_size && new_left < 15 && fitting_bins_count >= 1 {
            score += 3.0;
        }
        if new_left % 10 == 0 && new_left >= 20 && fitting_bins_count >= 1 {
            score -= 4.0;
        }
        if next_item_size > 0 && new_left >= next_item_size && new_left - next_item_size <= 3 && fitting_bins_count >= 1 {
            score -= 2.5;
        }
        if new_left <= 3 && fitting_bins_count >= 1 {
            score -= 6.0;
        }
        if new_left < 10 && fitting_bins_count >= 1 && next_item_size > new_left {
            score += 4.0;
        }
        if next_item_size > 0 && new_left >= next_item_size * 2 && fitting_bins_count >= 1 {
            score -= 2.5;
            if open_bins_count <= 3 {
                score -= 1.5;
            }
        }
        // Chain lookahead: fresh bin hosting next item leaves a splittable residual.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size {
            let chain = new_left - next_item_size;
            if chain >= next_item_size / 2 && chain <= next_item_size {
                score -= 2.0;
            }
        }
        // Stranded fresh-bin leftover just under next item wastes proportionally.
        if next_item_size > 0 && new_left < next_item_size && new_left >= 15 {
            score += (next_item_size - new_left) as f64 * 0.18;
        }
        if fitting_bins_count >= 3 && item_size <= bin_capacity / 3 {
            score += 3.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 && mean_residual >= item_size as f64 * 1.2 && item_size <= bin_capacity / 4 {
            score += 5.0;
        }
        // Late-stream pressure: stop opening new bins near the end.
        if progress > 0.8 && fitting_bins_count > 0 && item_size < bin_capacity / 2 {
            score += 6.0 * (progress - 0.8) * 10.0;
        }
        if progress > 0.6 && fitting_bins_count >= 1 {
            score += 2.0 * (progress - 0.6) * 10.0;
        }
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count > 0 {
            score += 3.0 * progress;
        }
        // Medium leftover with next item fitting inside is a strong chain start.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= 25 && new_left < 35 && next_item_size <= new_left {
            score += 3.0;
        }
        // Small items leave large residuals in fresh bins; discourage when open bins exist.
        if fitting_bins_count >= 1 && new_left >= 30 && item_size <= 10 {
            score += 2.0;
        }
        // Big next item: prefer an existing bin even if the current one barely misses it.
        if next_item_size > bin_capacity / 2 && fitting_bins_count > 0 && new_left < next_item_size {
            score += 4.0;
        }
    } else {
        // Existing-bin refinements.
        if fitting_bins_count > 3 && post_residual > 30 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 3.0;
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 1.5;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && post_residual + item_size >= bin_capacity * 9 / 10 {
            score -= 1.5;
        }
        let band = (post_residual as f64 - mean_residual).abs();
        if band < 5.0 && post_residual >= next_item_size.max(1) {
            score -= 1.0;
        }
        if post_residual < next_item_size && post_residual < mean_residual as u32 {
            score += 2.0;
        }
        if post_residual >= 10 && post_residual <= 20 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 && post_residual > 20 {
            score -= 1.5;
        }
        // Near-exact next-item closure is ideal, stronger late.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 1 && progress > 0.5 {
            score -= 1.5;
        }
        if post_residual > 12 && post_residual < 25 && next_item_size > post_residual {
            score += 1.0;
        }
        // Tighten: residual hosting next item twice is valuable when bins are scarce.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count <= 2 {
            score -= 1.0;
        }
        // Small residual that next item cannot use: mild penalty to prefer other bins.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 20 {
            score += (next_item_size - post_residual) as f64 * 0.06;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Tight fits are strongly favored: reward low post_residual non-linearly.
    let tightness = 1.0 - post / cap; // in (0,1]
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.15 * (next_item_size as f64 - post as f64);
    } else if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        // Reward bins that remain useful for the lookahead item.
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Mild penalty when bin residual deviates from mean residual (keeps residuals uniform).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // Stream-progress coupling: late in the stream, be more aggressive at filling
    // existing bins (penalize new-bin opening and loose fits).
    let late = progress * progress;
    score += late * (post * 0.35);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, growing with stream progress and open bins.
        score += 6.0 + 12.0 * late + 0.4 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
