pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual in (0..=10] is nearly dead space
    let pr = post_residual;
    if pr > 0 {
        let small = pr.min(10) as f64;
        score += (11 - small) * 6.0; // penalize small unusable leftovers
        // modulo classes: residuals divisible by common item sizes are reusable
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 && pr > 0 {
                score -= 8.0;
            }
        }
    }

    // Lookahead coupling: can next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            score -= (next_item_size as f64) * 0.8;
        } else {
            score += (next_item_size as f64 - pr as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score = cap * 0.75;
        if fitting_bins_count == 0 {
            score -= 400.0; // forced: nothing fits elsewhere
        } else if item_size >= 60 && fitting_bins_count <= 2 {
            // large item: prefer fresh bin to avoid fragmenting
            score -= 120.0;
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 60.0; // reserve fresh space for big lookahead item
        }
    }

    // Waste relative to mean residual: discourage bins far below mean usable space
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Progress-based tightening: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 0.0 + progress * (post_residual as f64 / cap) * 10.0;

    // Integer-division thresholds on post_residual
    let q = pr / 25; // harmonic quarter-classes
    score -= q as f64 * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are wasted.
    if post_residual < item_size.min(20).max(10) {
        score += 60.0;
    }
    // Penalty grows steeply as post_residual shrinks into "dead zone" (1..=15).
    if post_residual > 0 && post_residual <= 15 {
        score += (16 - post_residual as i32) as f64 * 8.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Next-item lookahead: bonus if residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap just below the next item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins early.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mean residual alignment: prefer bins close to the fleet mean.
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate: make it attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: open new bin
        } else {
            // discourage opening new bin when fits exist, unless fits are loose
            let loose = (bin_residual as f64 - item_size as f64) > 50.0;
            score += if loose { 40.0 } else { 15.0 };
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack (<= 5)
    else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 30.0 - (post_residual - next_item_size) as f64 * 4.0;
    }
    // Next item does NOT fit in the residual left behind: penalize wasted space
    if next_item_size > 0 && post_residual < next_item_size {
        // residual too small to be useful for the next item
        let waste = post_residual as f64;
        score += waste * 0.3;
        if post_residual < 10 {
            score += 15.0; // dead space
        }
    }

    // Reward tight fits relative to mean residual of open bins
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.4;
    } else {
        score += (pr - mean_residual) * 0.25;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, especially early in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 40.0 + 30.0 * (1.0 - progress);
        // But allow opening if no open bin fits well
        if fitting_bins_count == 0 {
            score = -10.0;
        } else {
            score += penalty;
        }
    }

    // Slight preference to fill more-open bins when many are open
    score += open_bins_count as f64 * 0.05;

    score
}

