pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let tightness = 1.0 - (post / cap);
    score -= 60.0 * tightness * tightness;

    // Dead-space penalty: residuals too small to hold the smallest plausible item (<=5)
    if post_residual < 5 {
        score -= 25.0; // perfect fill, excellent
    } else if post_residual <= 10 {
        score -= 10.0;
    } else if post_residual < 20 {
        // awkward zone: residual too small for many items but not zero
        score += 8.0;
    }

    // Lookahead: if the next item can fit in the post-residual, this placement
    // preserves a useful chain; reward it proportionally to how well it fits.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
