    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.2 * (item_size as f64);
    }

    // New-bin candidate handling: an empty bin has post_residual = cap - item.
    // It should only win when fits in open bins are poor. Make empty bins
    // mildly unattractive so tight existing fits win, but attractive when
    // open bins are fragmented.
    if bin_residual == bin_capacity {
        // base cost of consuming a fresh bin
        score += 12.0;
        // if many open bins are highly fragmented, opening fresh is fine
        let fragmentation = (mean_residual / cap).max(0.0).min(1.0);
        score -= 10.0 * (1.0 - fragmentation);
        // early in the stream, opening bins is cheap and flexible
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        // if the item is large relative to capacity, a fresh bin is natural
        score -= 0.1 * (item_size as f64);
    } else {
