            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 3 {
            score -= 1.0;
        }
        if next_item_size > 0 && new_left < next_item_size && new_left >= 8 && (next_item_size - new_left) <= 4 {
            score += 4.0;
        }
        if next_item_size > 0 && new_left >= 20 && new_left < next_item_size && (next_item_size - new_left) <= 6 {
            score += 2.5;
        }
        if new_left == 10 || new_left == 15 || new_left == 20 || new_left == 25 || new_left == 30 {
            score -= 1.5;
        }
        if fitting_bins_count >= 3 && item_size <= bin_capacity / 3 {
            score += 3.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 && mean_residual >= item_size as f64 * 1.2 && item_size <= bin_capacity / 4 {
            score += 5.0;
        }
        if progress > 0.8 && fitting_bins_count > 0 && item_size < bin_capacity / 2 {
            score += 6.0 * (progress - 0.8) * 10.0;
        }
        if progress > 0.6 && fitting_bins_count >= 1 {
            score += 2.0 * (progress - 0.6) * 10.0;
        }
        if next_item_size >= bin_capacity * 2 / 5 && fitting_bins_count > 0 && item_size <= bin_capacity / 3 {
            score += 4.0;
        }
        if fitting_bins_count == 0 && open_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 6.0;
        }
        if next_item_size > 0 && new_left >= next_item_size {
            let leftover = new_left - next_item_size;
            if leftover > 0 && leftover < 8 {
                score -= 2.0;
            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && new_left < next_item_size {
            score += (next_item_size - new_left) as f64 * 0.12;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left > next_item_size && (new_left - next_item_size) % 10 == 0 && new_left - next_item_size >= 10 {
            score -= 2.5;
        }
        if next_item_size > 0 && new_left >= next_item_size && new_left < next_item_size * 3 && fitting_bins_count >= 1 {
            score -= 1.0;
        }
        if item_size >= bin_capacity * 2 / 5 && item_size <= bin_capacity / 2 && fitting_bins_count == 0 && open_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 && new_left >= 25 && new_left < 35 && fitting_bins_count > 0 && next_item_size <= new_left {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= 11 && new_left <= 19 && new_left < next_item_size {
            score += 2.0;
        }
        if fitting_bins_count > 2 && open_bins_count > 0 && mean_residual > new_left as f64 * 1.5 {
