        // MUTATION: fragmentation veto — when open residuals are large relative to the
        // fresh leftover, prefer consolidating into existing bins.
        if fitting_bins_count >= 2 && new_left >= next_item_size * 3 && mean_residual > new_left as f64 * 0.8 {
            score += 2.5;
