        }
        let usable_ratio = new_left as f64 / bin_capacity.max(1) as f64;
        if next_item_size > 0 && new_left < next_item_size {
            let overflow = (next_item_size - new_left) as f64 / next_item_size.max(1) as f64;
            score += overflow * 2.0 * (1.0 - usable_ratio);
            if fitting_bins_count <= 1 {
                score += overflow * 1.5 * (1.0 - usable_ratio);
            } else if fitting_bins_count >= 4 {
                score -= 0.8;
            }
        }
        // G71: capped stranded-capacity penalty for dead new-bin leftovers.
        if next_item_size > 0 && new_left < next_item_size {
            let stranded_amt = (next_item_size - new_left) as f64;
            let strand_frac = stranded_amt / bin_capacity.max(1) as f64;
            let penalty = (strand_frac * 18.0).min(6.0);
            score += penalty * (0.5 + 0.5 * (1.0 - usable_ratio));
            let pressure = (mean_residual / bin_capacity.max(1) as f64).min(1.0);
            if pressure > 0.35 && fitting_bins_count >= 1 {
                score += (pressure - 0.35) * 10.0;
            }
        }
        // G71: reward new bins whose leftover supports a two-item chain.
        if next_item_size > 0 && new_left >= next_item_size * 2 && new_left <= bin_capacity / 2 {
            score -= 1.5 + 1.0 * progress;
        }
        // G71: late-stream consolidation — a new bin opened late rarely pays back.
        if progress > 0.85 && fitting_bins_count >= 1 && new_left > bin_capacity / 3 {
            score += 2.0 + 2.0 * (progress - 0.85) * 10.0;
        }
        // G71: reward new bins whose chain gap stays within a reusable band.
        if next_item_size > 0 && new_left >= next_item_size {
            let chain_gap = new_left - next_item_size;
            if (chain_gap as f64) <= mean_residual * 0.5 {
                score -= 1.0 + 0.5 * progress;
            }
        }
        // G72: new-bin dead-economy — if the leftover after this item would be
        // nearly dead (next item misses by a hair) and many bins already fit
        // the current item, make the fresh bin clearly worse so the item
        // compacts into an existing bin instead.
