            let stranded_gap = (next_item_size - new_left) as f64;
            let strand_frac = stranded_gap / bin_capacity.max(1) as f64;
            let cap = 6.0;
            score += (strand_frac * 18.0).min(cap) * (0.5 + 0.5 * (1.0 - progress));
        }
        if progress > 0.85 && fitting_bins_count >= 1 && new_left > bin_capacity / 3 {
            score += 2.0 + 2.0 * (progress - 0.85) * 10.0;
        }
        // G73 mutation: mean-aligned leftover preference. A new-bin leftover
        // that lands within a tight band around the mean residual is the most
        // likely to be absorbed by future items — reward it; a leftover far
        // above the mean band is likely to strand — penalize mildly.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= 5 {
            let left_dev = ((new_left as f64) - mean_residual).abs() / mean_residual.max(1.0);
