        }
        // G73: when many bins are open and mean residual is high, opening a new
        // bin wastes absorbable capacity — scale the new-bin cost with the
        // fragmentation pressure so existing bins get consolidated first.
        if open_bins_count >= 4 && (mean_residual / bin_capacity.max(1) as f64) > 0.25 && item_size <= bin_capacity / 2 {
