        if next_item_size > 0 && post_residual > 0 {
            let pr_dev = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
            if pr_dev > 1.2 && open_bins_count >= 3 {
                score += 0.8 + 0.8 * progress;
            } else if pr_dev <= 0.3 {
                score -= 0.6 + 0.4 * progress;
            }
        }
    }

    score
}

