        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= next_item_size {
                score -= 1.0 + 1.2 * progress;
            } else if tail > 0 && (tail as f64) < mean_residual * 0.35 && fitting_bins_count >= 2 {
                score += 0.6 + 0.6 * progress;
            }
        }
        if open_bins_count >= 5 && post_residual <= 4 {
            score -= 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 3 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            let tail_dev = ((tail as f64) - mean_residual).abs();
            if tail > 0 && tail_dev <= mean_residual * 0.3 {
                score -= 0.6 + 0.6 * progress;
            } else if (tail as f64) > mean_residual * 2.5 && tail > next_item_size {
                score += 0.5 + 0.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 6.0 && fitting_bins_count >= 1 && post_residual >= 8 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        // NEW (G75): residual-reuse alignment for existing bins — a tail
        // close to the mean residual is prime space for a future item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && ((tail as f64) - mean_residual).abs() <= 2.0 {
                score -= 0.8 + 0.8 * progress;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 60.0 * deadness * deadness;
    }

    if post_residual == 0 {
        score -= 80.0 + 2.0 * progress;
    }

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let strand_frac = (next_item_size - post_residual) as f64 / bin_capacity.max(1) as f64;
        score += (strand_frac * 20.0).min(7.0) * (0.5 + 0.5 * progress);
    }

    // G75 mutation: residual-quality anchor — bins whose post-placement
    // residual sits near the stream's mean residual are the most reusable;
    // reward them proportionally, scaled by remaining stream length.
    if post_residual > 0 {
        let near_mean = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
        if near_mean <= 0.25 {
            score -= (0.25 - near_mean) * (4.0 + 4.0 * progress);
        } else if near_mean >= 0.9 {
            score += (near_mean - 0.9) * 3.0;
        }
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if next_item_size == post_residual {
                score -= 11.0;
            }
            let after = post_residual - next_item_size;
            if after % 10 == 0 && after >= 20 {
                score -= 3.0;
            }
            if after == 0 {
                score -= 6.0;
            }
            if after > 0 && after < next_item_size {
                score += 1.5;
            }
            if after < 10 {
                score += 2.0;
            }
            if after >= next_item_size * 2 {
                score -= 2.0 + 2.0 * progress;
            } else if after < 4 {
                score += 2.0;
            }
            if after < 3 {
                score -= 2.0;
            }
            if after >= next_item_size.max(8) {
                score -= 1.0;
            }
            if after >= next_item_size * 3 {
                score -= 1.0;
            }
            if after >= 10 && after <= 20 {
                score -= 1.5 + 0.5 * progress;
            }
            if after >= next_item_size && after < next_item_size * 2 && fitting_bins_count >= 1 {
                score -= 1.0;
            }
            if after > 0 && after <= 5 {
                score -= 1.0 + 1.0 * progress;
            }
            if after >= next_item_size * 2 && fitting_bins_count <= 2 {
                score -= 1.0;
            }
            if after >= next_item_size && after % 5 == 0 && fitting_bins_count >= 1 {
                score -= 1.0;
            }
            if after >= next_item_size * 2 && after % 10 == 0 {
                score -= 1.0 + 1.0 * progress;
            }
            if after == next_item_size && fitting_bins_count <= 3 {
                score -= 1.0 + 0.5 / (1.0 + fitting_bins_count as f64);
            }
            if after >= 10 && after <= 20 && fitting_bins_count >= 1 {
                score -= 0.5 + 0.5 * (1.0 / (1.0 + fitting_bins_count as f64));
            }
            if after >= next_item_size * 2 && after % 5 == 0 && fitting_bins_count <= 3 {
                score -= 0.5 + 0.8 * progress;
            }
            if after >= 1 && after <= 6 && (after as f64) <= mean_residual * 0.4 {
                score -= 1.0 + 1.5 * progress;
            }
            if fitting_bins_count >= 2 {
                let near = (after as f64) / (next_item_size.max(1) as f64);
                score += near * 1.2;
            }
            if after >= 5 && after <= 40 {
                score -= 0.8 + 0.8 * progress;
            }
            if after > 0 && after <= 2 {
                score -= 1.5;
            }
            if after >= next_item_size * 2 && after < next_item_size * 3 && (after as f64) <= mean_residual * 1.5 {
                score -= 1.0 + 0.8 * progress;
            }
            if after >= next_item_size {
                score -= 1.0 + 1.2 * progress;
            } else if after > 0 && (after as f64) < mean_residual * 0.35 && fitting_bins_count >= 2 {
                score += 0.6 + 0.6 * progress;
            }
            if after >= next_item_size * 2 && fitting_bins_count >= 1 {
                score -= 1.5 + 1.5 * progress;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score += 15.0 + gap * (0.15 + 0.45 * scarcity);
            let dead_ratio = gap / bin_capacity as f64;
            score += dead_ratio * 46.0;
            if dead_ratio < 0.04 {
                score -= 4.5;
            }
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += stranded * 18.0;
            if post_residual < 20 {
                score += 5.0;
            }
            if fitting_bins_count >= 2 {
                score += 2.0;
            }
            if fitting_bins_count <= 1 {
                score += 1.5;
            }
            score += gap * 0.08;
            if post_residual + item_size >= bin_capacity * 9 / 10 {
                score -= 1.5;
            }
            if post_residual <= 4 {
                score -= 2.5;
            }
            if post_residual % 2 == 1 && post_residual > 5 {
                score += 1.5;
            }
            if post_residual >= 20 {
                score += (next_item_size - post_residual) as f64 * 0.06;
            }
            if gap <= 2.0 && post_residual >= 15 {
                score -= 3.0;
            }
            if post_residual >= 15 && post_residual < 20 {
                score += (next_item_size - post_residual) as f64 * 0.04;
            }
            if gap <= 4.0 && fitting_bins_count <= 2 {
                score -= 1.5;
            }
            let near_close = item_size as f64 >= bin_residual as f64 * 0.85;
            if !near_close {
                score += gap * (0.06 + 0.10 * progress);
            }
            if (post_residual as f64) >= mean_residual * 0.9 {
                score -= 1.0;
            }
            if gap <= 3.0 && (post_residual as f64) >= mean_residual * 0.6 {
                score -= 2.0 + 1.0 * progress;
            }
            if (post_residual as f64) < mean_residual * 0.5 {
                score += gap * 0.10;
            } else {
                score -= 0.4;
            }
            let gap_frac = gap / (next_item_size.max(1) as f64);
            if gap_frac <= 0.25 && post_residual >= 8 {
                score -= 1.0 + 1.0 * progress;
            } else if gap_frac > 0.75 {
                score += 0.8 + 0.8 * progress;
            }
        } else {
            if fitting_bins_count > 1 {
                score -= 3.0;
            }
        }
        if next_item_size > bin_capacity / 2 && post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
        if post_residual >= next_item_size && post_residual >= mean_residual as u32 {
            score -= 1.5;
        }
        if post_residual > 0 && post_residual < next_item_size && post_residual > next_item_size.saturating_sub(4) {
            score += 2.0;
        }
    }

    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count == 0 {
        score -= 10.0;
    }

    score += 3.0 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;
    score += 0.1 * (bin_residual as f64);

    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.75 {
