pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post residual), with non-linear shaping.
    let mut score = post;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, prefer leaving mid-sized space (mild penalty for very small x),
    // late in stream, strongly prefer small x (tight packing).
    let w = progress * progress;
    score -= 30.0 * w * (1.0 - x) * (1.0 - x);
    score += 12.0 * (1.0 - w) * x * (1.0 - x);

    // Penalize dead space: unusable residual relative to smallest possible item.
    let dead = (post - 1.0).max(0.0);
    score += 0.15 * dead * dead / cap;

    // Lookahead coupling: reward residual that can host next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_quality = (post - nxt) / cap;
            score -= 8.0 * (1.0 - fit_quality * fit_quality);
        } else {
            let gap = (nxt - post) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x * x);
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    let mean_x = mean_residual / cap;
    score += 3.0 * (mean_x - x).abs() * (open_bins_count as f64).sqrt() / (1.0 + progress);

    // Smooth preference for filling fuller bins overall (quadratic in x inverted).
    score -= 6.0 * (1.0 - x) * (1.0 - x) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: classify leftover into residue classes mod 10.
    let cls = (post_residual % 10) as f64;
    // Residues that pair well with typical small items (multiples of 10) are rewarded.
    if post_residual % 10 == 0 {
        score -= 8.0 + post * 0.05;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    } else {
        // Awkward residue classes penalized proportionally to how far from a multiple of 10.
        score += cls.min(10.0 - cls) * 0.6;
    }

    // Dead-space penalty: very small leftovers are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let frac = nxt / post.max(1.0);
