pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be useful.
    // Residuals below the minimum item size (1) are impossible, but small residuals
    // (e.g. < 20) are likely dead space given unknown item sizes.
    if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 3.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 50.0;
    }

    // Penalize when this placement blocks the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward fitting into an existing bin when few bins fit (last-chance effect).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    // (a new bin has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
    } else {
        // Mild reward for using already-open bins, scaled by congestion.
        score -= 2.0 + open_bins_count as f64 * 0.5;
    }

    // Prefer placing into bins with below-average residual (tighter bins),
    // keeping larger residual bins flexible.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Late in the stream, be more aggressive about avoiding new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

