    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // 2-step lookahead: strong reward if the next item exactly fills this bin afterwards.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how tight the chain is
            score -= 25.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            // next item won't fit here: penalize leaving a gap smaller than next item
            score += 10.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Reward exact / near-exact fills now.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize leaving dead space relative to bin capacity for very small leftovers.
    if post_residual > 0 && (post_residual as f64) < cap * 0.1 {
        score -= 5.0;
    }

    // New-bin candidate: only attractive early in the stream or when nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.5 + 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size as f64 >= cap * 0.9 {
            score -= 10.0; // next item is huge, fresh bin useful
