pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Polynomial coupling of post residual with stream progress:
    // early on, tolerate larger residuals; late, penalize dead space strongly
    let coupling = x * x * (1.0 - progress) - x * progress;
    score += 40.0 * coupling;

    // Reward tight fits (small x) increasingly as stream advances
    score -= (1.0 - x).powi(3) * (20.0 + 30.0 * progress);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins whose residual deviates from mean (fragmentation avoidance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead: if next item fits exactly in the post residual, reward
    if next_item_size > 0 && (next_item_size as f64) == pr {
        score -= 25.0;
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 3.0; // next item can't use this bin anyway
    }

    // Mild pressure to reuse existing bins as open bin count grows
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * pr / cap;

    score
}

