        score = 55.0 + mean_residual * 0.3 - progress * 20.0;
        if tight {
            score += 30.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(100)) {
        // gap too small for the next item -> dead space
        score += 40.0 + 2.0 * (post_residual as f64);
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // generically tiny gap below known min size
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins with residuals below the mean (consolidate large gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Late-stream tightening: as stream progresses, avoid waste more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual close to 0)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) == next {
            score -= 500.0; // perfect chain: next item exactly fills this bin
        } else if (post_residual as f64) >= next {
            let diff = post_residual as f64 - next;
            score -= 150.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to leftover dead space
            let dead = next - post_residual as f64;
            score += 0.5 * dead;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize opening a new bin when open bins could still absorb the item well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 150.0;
        // but allow a new bin if the item is huge and fits poorly anywhere
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 100.0;
        }
    }

    // Mild late-stream pressure to consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * (post_residual as f64);

    score
}

