    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 9.0;
    }

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 6.0 * (1.0 - (slack_after_next as f64) / (bin_capacity as f64));
    }
    // Penalize if next item cannot use post_residual (wasted space ahead)
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Crowd factor: many open bins -> prefer consolidating into existing bins
    let crowd = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 2.5 * crowd;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average)
    score += 0.35 * ((post_residual as f64) - mean_residual);

    // Time horizon: early in stream, be conservative (favor new bins for large items);
    // late in stream, squeeze into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    // New-bin candidate: make it attractive only when fit is poor or item is huge
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) / (bin_capacity as f64) < 0.35 || tightness < 0.45;
        if poor_fit {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    score
}

