pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: normalized post residual with smooth progress interaction
    let npr = pr / cap;
    score += npr * npr * 40.0 * (0.5 + progress);

    // Tight fits rewarded with smooth cubic term
    score -= (1.0 - npr).powi(3) * 30.0;

    // Lookahead: penalize if next item cannot use the residual (dead space)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr as f64 {
            score += 12.0 * (1.0 - pr / ns.max(1.0));
        } else {
            score -= 8.0 * (1.0 - (pr - ns) / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Penalize opening new bins when many bins are open and mean residual is high
    let mean_n = mean_residual / cap;
    if bin_residual as f64 == cap {
        score += 10.0 + 20.0 * mean_n + 5.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        score += 3.0 * (mean_n - npr).abs();
    }

    score
