pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact capacity fractions are prime targets
    let pr = post_residual;
    let frac = pr as f64 / cap;

    // Reward post-residuals that are "harmonic" fractions of capacity (50, 25, 75, 20, 33...)
    let harmonic_bonus = if pr == 0 { 30.0 }
        else if pr == 50 { 22.0 }
        else if pr == 25 || pr == 75 { 16.0 }
        else if pr == 20 || pr == 40 || pr == 60 || pr == 80 { 12.0 }
        else if pr == 10 || pr == 30 || pr == 70 || pr == 90 { 8.0 }
        else if pr == 33 || pr == 66 { 6.0 }
        else { 0.0 };
    score -= harmonic_bonus;

    // Integer-division threshold: post_residual divisible by 10 packs well with 10..80 items
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Dead space penalty: tiny unusable remainders (1..9) are wasted capacity
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly or harmonically
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 28.0; // perfect chain fit
        } else if next_item_size <= pr {
            let nxt_frac = (pr - next_item_size) as f64 / cap;
            // prefer leaves whose next leftover is again a harmonic fraction
