    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that are too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual >= 10 {
        // Usable leftover space is mildly rewarded relative to raw value.
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
