pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let norm_post = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * norm_post * norm_post;

    // Harmonic classes: classify post_residual dead-space by capacity fraction classes.
    // Residuals in (0..10] are near-perfect (reward), (10..30] are awkward (penalize),
    // (30..50] medium, >50 large slack that may still host future items.
    let post = post_residual;
    if post == 0 {
        score -= 25.0; // perfect fill
    } else if post <= 10 {
        score -= 12.0; // near-perfect dead space, small enough to be useless anyway
    } else if post <= 30 {
        score += 15.0; // awkward zone: too small for typical items (>=10), wasted
    } else if post <= 50 {
        score += 3.0;
    } else {
        score -= 4.0; // large residual still flexible
    }

    // Modulo coupling with next item: does the next item divide into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // Next item fits here: reward proportionally to how well it nests.
            let waste = (post - next_item_size) as f64;
            let nest_quality = 1.0 - waste / bin_capacity as f64;
            score -= 18.0 * nest_quality;
            // Harmonic bonus: exact division-like nesting (waste < 5).
            if waste < 5.0 {
                score -= 10.0;
            }
        } else {
            // Next item will NOT fit: penalize more if this bin was the only option.
            score += 8.0;
            // Harmonic class of next item size vs post residual gap.
            let gap = (next_item_size - post) as f64;
            if gap <= 10.0 {
                score += 10.0; // just barely misses: painful near-fit loss
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral baseline, slightly penalized early,
    // favored late in the stream or when open bins are congested.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.5;
        score -= 15.0 * progress; // late stream: keep packing into open bins cheaper
        score += (open_bins_count as f64).ln().max(0.0) * 6.0; // many open bins: prefer new one
        // If next item is huge, a fresh bin is valuable.
        if next_item_size >= 70 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // already crammed; using it keeps other bins flexible.
    let diff = mean_residual - bin_residual as f64;
    score -= 0.15 * diff;

    // Mild step-based annealing: early stream, be pickier about slack (scale penalties).
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - t);

    score
}

