}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (1..100 range) are pure waste. Penalize any
    // post_residual below a "usable threshold" aggressively.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but reward reusing bins when few are open.
    score += (open_bins_count as f64) * 0.4;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if the item fits
    // poorly everywhere else (large post_residual waste avoided by fresh space)
    if bin_residual == bin_capacity {
        // Neutral base: new bin starts with large post_residual already,
        // add pressure so it's chosen only when genuinely better.
        score += 10.0;
        // Early in stream, slightly discourage hoarding new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 5.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item cannot fit in post_residual but would fit a fresh bin,
    // mildly penalize leaving a gap that strands the next item.
    if next_item_size > post_residual && next_item_size <= bin_capacity {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., tighter bins) to consolidate filling.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    score
}

