    score += (post_residual as f64) * (0.5 * (1.0 - tightness));

    // Penalize tiny dead space that nothing can use (items >= 1, so residual 0 is perfect).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 0.3 * item_size as f64;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual as i64 == next_item_size as i64 {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here: mild penalty proportional to overflow gap
            score += 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Global state coupling: if mean residual across bins is high, prefer consolidating
    // into bins with below-average residual (larger residual than mean).
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (keep flexibility);
    // late in stream, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 20.0 + 30.0 * progress;
        // but early on, opening a bin is cheap-ish
        score -= 10.0 * (1.0 - progress);
        // if no open bin fits at all, new bin is fine (fitting_bins_count counts open fitting bins)
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else if fitting_bins_count == 0 {
        // shouldn't happen for non-new bin, but guard
        score += 0.0;
    }

    // Many open bins: discourage opening more, encourage using existing ones.
    score += 0.5 * open_bins_count as f64 * if bin_residual == bin_capacity { 1.0 } else { -0.2 };

    score
}

