        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear base: favor small post residual with saturation
    let mut score = 60.0 * norm_pr / (1.0 + norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early stream: tolerate larger residuals; late stream: punish them hard
    let coupling = (norm_pr * norm_pr) * (0.5 + 1.5 * progress) * (2.0 - progress);
    score += 40.0 * coupling;

    // Lookahead: reward if next item fits the post residual (smooth quadratic bonus)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 25.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - progress);
    }

    // Penalize deviating too far from mean residual (fragmentation smoothing)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Mild reward for keeping bins count low
    score += 2.0 * open_bins_count as f64 / (total_items as f64).sqrt();

    score
}

