    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are hard to fill later
    // (post_residual in 1..10 or 11..19 typical dead zones) get penalized,
    // exact "nice" residuals (multiples of 20/25/50) get rewarded.
    let pr = post_residual as i64;
    let nice = if post_residual == 0 {
        -40.0
    } else if pr % 50 == 0 {
        -25.0
