        score += (30.0 - pr) * 1.5;
    }

    // Reward near-perfect fits strongly (waste = 0 is the ideal).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills post_residual,
    // this placement chains perfectly - reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item fits in post_residual, mild reward; if it cannot fit anywhere
