            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left < next_item_size && new_left >= 15 {
            score += (next_item_size - new_left) as f64 * 0.18;
        }
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count > 0 {
            score += 3.0 * progress;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 2 && open_bins_count <= 3 {
            score -= 1.5;
        }
        if next_item_size == 0 && new_left > bin_capacity * 3 / 5 && open_bins_count > 2 {
            score += 2.0;
        }
        if fitting_bins_count >= 1 && item_size <= bin_capacity / 5 && mean_residual >= item_size as f64 * 2.0 {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && (new_left - next_item_size) <= 1 {
            score -= 2.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 3 && new_left % 5 == 0 {
            score -= 1.5;
        }
        if next_item_size > 0 && new_left < next_item_size && new_left > bin_capacity * 2 / 5 {
            score += (next_item_size - new_left) as f64 * (0.05 + 0.10 * progress);
        }
        if next_item_size > 0 && new_left < next_item_size && new_left > bin_capacity / 4 && new_left <= bin_capacity * 2 / 5 {
            score += (next_item_size - new_left) as f64 * (0.03 + 0.06 * progress);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && new_left - next_item_size >= 5 && new_left - next_item_size <= 9 {
