pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are worse than large leftovers.
    // Treat residuals below the minimum plausible item size (1..~20) as dead space.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 - 3.0 * post_residual as f64; // heavy penalty for tiny gaps
    }
    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many exist.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.5 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits into the post residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 0.15 * next_item_size as f64;
        }
    }

    // Mean residual alignment: prefer bins whose residual is below average (tighter bins).
    score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild stream progression: tighten packing later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

