pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fill (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: does the next item fit into the leftover?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward tight chains: leftover just fits next item.
            let tightness = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.5 * tightness;
        } else {
            // Leftover too small for next item: penalize dead space,
            // worse when it's small-but-unusable.
            let waste = post_residual as f64;
            score += 40.0 * (1.0 - waste / bin_capacity as f64);
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // or the item is large and would strand a bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let strand_risk = (item_size as f64) / bin_capacity as f64;
        score = 150.0 - 50.0 * strand_risk - 30.0 * progress;
