pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: post_residual near zero is rewarded.
    let tight_bonus = 40.0 * (-post_residual as f64 / 25.0).exp();
    score -= tight_bonus;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Reward leaving exactly room for the next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.25 * bin_residual as f64;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, softened when open bins have large residuals
        // that cannot be used anyway.
        let waste_proxy = (mean_residual - post_residual as f64).max(0.0);
        score += 35.0 - waste_proxy.min(30.0);
        // Early in the stream, new bins are cheaper (exploration).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 50 {
            score -= 12.0;
        }
    }

    // Prefer filling bins that are already small-residual (consolidate waste).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    // Mean-residual coupling: if mean residual is high, prefer using bins
    // below the mean (they are the odd ones out and should be drained).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

