pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer tight fits; penalize dead space quadratically.
    let mut score = post + 40.0 * post_norm * post_norm * cap;

    // Smooth non-linear coupling with stream progress: mid-stream, tolerate
    // larger post_residual slightly less (bins still have time to fill);
    // late-stream, penalize dead space more heavily.
    let progress_curve = progress * (1.0 - progress) * 4.0; // peaks at 0.5
    score += (1.0 - progress_curve) * 25.0 * post_norm * cap;

    // Lookahead: reward residual that can hold the next item (smooth gate).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (post - nxt).max(0.0);
        let gate = 1.0 / (1.0 + (post - nxt).abs());
        score -= 15.0 * gate * (1.0 - fits / cap);
        // Penalize residual just barely missing the next item (smoothly).
        let miss = ((nxt - post) / cap).max(0.0);
        score += 12.0 * miss * (1.0 - miss);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - post_norm);
    }

    // New-bin candidate: mildly penalize when good open bins exist, mildly
    // reward when open bins are congested (small mean residual).
