        let congestion = 1.0 - (mean_residual / cap).min(1.0);
        score += 8.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (1.0 - congestion);
        score -= 6.0 * congestion * (1.0 - progress);
    } else {
        // Favor bins deviating from mean residual (diversity of sizes).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score -= 5.0 * dev * (1.0 - dev);
