pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify by capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Dead-space class: residuals that are "harmonically useless" get penalized
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else if post_residual < 10 {
        score += 20.0; // tiny dead space, hard to fill
    } else if frac < 0.2 {
        score += 8.0;
    } else if frac < 0.35 {
        score += 0.0;
    } else if frac < 0.55 {
        score -= 5.0; // sweet spot: fits mid-size items
    } else if frac < 0.8 {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Modulo-10 arithmetic on post_residual vs next_item_size:
    // if next item divides cleanly into post_residual, big reward
    if next_item_size > 0 && post_residual > 0 {
        if post_residual % next_item_size == 0 {
            score -= 12.0;
        } else if next_item_size % 10 == 0 && post_residual % 10 == 0 {
            score -= 6.0;
        } else if post_residual % 10 == 0 {
            score -= 2.0; // round residual is flexible
        } else {
            score += 3.0; // ragged residual
        }
        // next item exactly fills the bin
        if next_item_size == post_residual {
            score -= 25.0;
        }
        // next item cannot fit here anyway: slight penalty if residual small
        if next_item_size > post_residual && post_residual < 20 {
            score += 5.0;
        }
    }

    // Integer-division threshold: how many size-10 units of waste
    let waste_units = post_residual / 10;
    score += (waste_units % 3) as f64 * 1.5;

    // Last-chance bonus: only this bin fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening new bin unless current bins are fragmented
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow new bin late in stream or when mean residual is high (fragmented)
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual > 35.0 {
            score -= 20.0;
        }
        if progress > 0.9 {
            score += 10.0; // near end, prefer filling existing bins
        }
    }

    // Mild preference for tighter bins overall
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

