pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold anything
    // useful (below minimum item size) are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 500.0; // unreachable given sizes >= 1, but guards intent
    }
    // Penalize small-but-technically-usable gaps: they rarely get filled.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (12.0 - post_residual as f64) / 12.0;
    }
    // Sweet spot: leaving a gap that can accommodate a mid-size item is good.
    if post_residual >= 25 && post_residual <= 60 {
        score -= 15.0;
    }
    // Perfect/near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Last-chance bin pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, allow opening new ones less painfully.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open or residual
        // capital (mean_residual) is still large.
        score += 80.0 + 6.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // But if no open bin fits well (this call reached here with lowest
        // competition), the last-chance logic above already favors open bins;
        // soften new-bin penalty early in the stream.
        score -= 40.0 * (1.0 - progress);
    } else {
        // Using an existing bin slightly relieves open-bin pressure.
        score -= 2.0 * bin_pressure.min(20.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement strongly (pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 40.0;
            }
        } else if next_item_size > bin_residual && post_residual < next_item_size {
            // next item won't fit here anyway; neutral small bonus for using space now
            score -= 10.0;
        }
    }

    // Mean-residual coupling: prefer placing into bins whose residual is
    // below average (concentrate waste into fewer bins).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

