    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual exactly equals next item -> subtract heavily.
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 60.0 - chain_fit.min(60.0) * 0.5;
        } else {
            // Next item cannot follow here: penalize, scaled by how much space is wasted
            // relative to the next item's size.
            let gap = (post_residual - next_item_size) as f64; // negative
            score -= gap * 0.35; // makes score higher (worse) when gap very negative
        }
    } else {
        // Last item: just minimize residual.
        score -= 40.0;
    }

    // Favor tight fits: small post_residual relative to item size.
    let tightness = post_residual as f64 / (bin_residual.max(1) as f64);
    score += tightness * 25.0;

    // Penalize bins that deviate strongly from mean residual (keep residual profile balanced),
    // unless this is the only fitting bin (last chance).
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.25;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless residual after is tiny/dead).
