        score -= 55.0;
        if post_residual < 10 {
            score += 30.0; // dead-space penalty reduces last-chance appeal
        }
    }

    // New-bin candidate: neutral base, slightly favored early when stream is young,
    // discouraged later as stream matures (prefer consolidating into open bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
