        if item_size <= 10 && fitting_bins_count >= 1 && new_left >= 30 {
            score += 2.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size {
            let chain = new_left - next_item_size;
            if chain >= next_item_size / 2 && chain <= next_item_size {
                score -= 2.0;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left < next_item_size && new_left >= 15 {
            score += (next_item_size - new_left) as f64 * 0.18;
        }
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count > 0 {
            score += 3.0 * progress;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 2 && open_bins_count <= 3 {
            score -= 1.5;
        }
        if next_item_size == 0 && new_left > bin_capacity * 3 / 5 && open_bins_count > 2 {
            score += 2.0;
        }
        if fitting_bins_count >= 1 && item_size <= bin_capacity / 5 && mean_residual >= item_size as f64 * 2.0 {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && (new_left - next_item_size) <= 1 {
            score -= 2.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 3 && new_left % 5 == 0 {
            score -= 1.5;
        }
        if next_item_size > 0 && new_left < next_item_size && new_left > bin_capacity * 2 / 5 {
            score += (next_item_size - new_left) as f64 * (0.05 + 0.10 * progress);
        }
        if next_item_size > 0 && new_left < next_item_size && new_left > bin_capacity / 4 && new_left <= bin_capacity * 2 / 5 {
            score += (next_item_size - new_left) as f64 * (0.03 + 0.06 * progress);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && new_left - next_item_size >= 5 && new_left - next_item_size <= 9 {
            score -= 1.0;
        }
        if progress > 0.7 && fitting_bins_count >= 1 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score += 2.0;
        }
        if fitting_bins_count >= 2 && item_size <= bin_capacity / 4 && progress > 0.4 {
            score += 2.0 + 2.0 * progress;
        }
        if new_left >= 20 && new_left % 10 == 0 && fitting_bins_count >= 1 && next_item_size > 0 && next_item_size <= new_left {
            score -= 1.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && (new_left == next_item_size * 2 || new_left == next_item_size * 3) {
            score -= 1.0 + 0.5 / (1.0 + fitting_bins_count as f64);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 3 && new_left % 10 == 0 {
            score -= 1.0 + 1.0 * progress;
        }
        if progress > 0.7 && fitting_bins_count >= 1 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score += 1.0 + progress;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && open_bins_count > 0 && mean_residual >= next_item_size as f64 * 0.8 && new_left > next_item_size && (new_left - next_item_size) > 12 {
            score += 1.5;
        }
        if progress > 0.75 && fitting_bins_count >= 1 && next_item_size > 0 && new_left != next_item_size && item_size <= bin_capacity / 3 {
            score += 1.0 + 2.0 * progress;
        }
        if next_item_size > 0 && new_left < next_item_size {
            let slack_factor = 1.0 + (mean_residual / bin_capacity.max(1) as f64).min(1.0) * 0.5;
            score += ((next_item_size - new_left) as f64 / bin_capacity as f64) * 38.0 * slack_factor;
        }
        if open_bins_count >= 4 && mean_residual > item_size as f64 * 1.3 && new_left > bin_capacity / 3 {
            score += 2.0 + 1.0 * progress;
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && new_left >= next_item_size {
            let chain2 = new_left - next_item_size;
            if chain2 > 0 && chain2 < next_item_size / 2 && mean_residual >= item_size as f64 {
                score += 1.5 + 1.5 * progress;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left > next_item_size {
            let chain3 = new_left - next_item_size;
            if chain3 > 0 && chain3 < 8 && mean_residual > chain3 as f64 {
                score += (8 - chain3) as f64 * (0.4 + 0.4 * progress);
            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size && new_left >= next_item_size && (post_residual as f64) < mean_residual * 0.5 {
            score -= 2.0 + 1.5 * progress;
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && post_residual >= mean_residual as u32 {
            score -= 3.0 + 2.5 * progress;
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && new_left > next_item_size && new_left < next_item_size * 2 && (new_left - next_item_size) > next_item_size / 2 && open_bins_count >= 2 {
            score += 1.0 + 1.0 * progress;
        }
        if progress > 0.85 && fitting_bins_count >= 1 && (new_left as f64) > item_size as f64 {
            score += 4.0 * (progress - 0.85) * 10.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && (new_left as f64) <= mean_residual {
            score -= 1.0 + 0.8 * progress;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left > 0 && new_left < 5 && new_left != next_item_size {
            score += 2.5;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && new_left - next_item_size >= next_item_size / 2 {
            score -= 0.5 + 0.5 * progress;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left > 0 && next_item_size > new_left && next_item_size - new_left <= 2 && mean_residual >= next_item_size as f64 {
            score += 3.0 + 1.5 * progress;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 3 && mean_residual < item_size as f64 * 1.2 {
            score -= 1.0 + 0.8 * progress;
        }
        if next_item_size > 0 && new_left < next_item_size {
            let strand_frac = (next_item_size - new_left) as f64 / bin_capacity.max(1) as f64;
            score += ((strand_frac * 18.0).min(6.0)) * (0.5 + 0.5 * (1.0 - progress));
            let pressure = (mean_residual / bin_capacity.max(1) as f64).min(1.0);
            if pressure > 0.35 && fitting_bins_count >= 1 {
                score += (pressure - 0.35) * 10.0;
            }
        }
        if next_item_size > 0 && new_left >= next_item_size * 2 && new_left <= bin_capacity / 2 {
            score -= 1.5 + 1.0 * progress;
        }
        if progress > 0.85 && fitting_bins_count >= 1 && new_left > bin_capacity / 3 {
            score += 2.0 + 2.0 * (progress - 0.85) * 10.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size {
            let tail = new_left - next_item_size;
            let tail_dev = ((tail as f64) - mean_residual).abs();
            if tail_dev < mean_residual * 0.5 {
                score -= 1.2 + 0.8 * progress;
            } else if tail > next_item_size * 2 && (tail as f64) > mean_residual * 2.0 {
                score += 0.8;
            }
        }
        if fitting_bins_count >= 3 && item_size <= bin_capacity / 3 {
            score += 2.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count == 0 {
            score -= 2.0;
        }
        if next_item_size > 0 && new_left < next_item_size {
            let stranded_gap = (next_item_size - new_left) as f64;
            let strand_frac = stranded_gap / bin_capacity.max(1) as f64;
            let cap = 6.0;
            score += (strand_frac * 18.0).min(cap) * (0.5 + 0.5 * (1.0 - progress));
        }
        if progress > 0.85 && fitting_bins_count >= 1 && new_left > bin_capacity / 3 {
            score += 2.0 + 2.0 * (progress - 0.85) * 10.0;
        }
        if next_item_size > 0 && new_left == next_item_size {
            score -= 1.5 + 1.5 * progress;
        }
        if fitting_bins_count >= 2 && new_left > bin_capacity / 2 && progress > 0.3 {
            score += 1.0 + 1.5 * progress;
        }
        if fitting_bins_count >= 2 && (new_left as f64) > mean_residual * 1.3 && next_item_size > 0 {
            score += 1.0 + 1.2 * progress;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left > next_item_size {
            let tail = new_left - next_item_size;
            if ((tail as f64) - mean_residual).abs() <= 2.0 {
                score -= 1.2 + 1.0 * progress;
            }
        }
        // NEW (G91): fresh-bin reuse-value test — open a new bin only when its
        // leftover can chain the next item AND the best existing alternative
        // would strand a near-miss remainder; otherwise penalize opening.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let fresh_reusable = new_left >= next_item_size
                || (new_left % 10 == 0 && new_left >= 20 && new_left >= next_item_size / 2);
            let existing_strands = post_residual > 0 && post_residual < next_item_size
                && (next_item_size - post_residual) <= 3;
            if fresh_reusable && existing_strands {
                score -= 2.0 + 2.0 * progress;
            }
            if new_left < 8 && new_left % 2 == 1 && new_left != next_item_size {
                score += 1.5;
            }
            if new_left >= next_item_size * 2 && next_item_size <= bin_capacity / 4 && open_bins_count <= 5 {
                score -= 1.2 + 1.2 * progress;
            }
        }
    } else {
        if fitting_bins_count > 3 && post_residual > 30 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 3.0;
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 1.5;
        }
        let band = (post_residual as f64 - mean_residual).abs();
        if band < 5.0 && post_residual >= next_item_size.max(1) {
            score -= 1.0;
        }
        if post_residual < next_item_size && post_residual < mean_residual as u32 {
            score += 2.0;
        }
        let fits_small = post_residual / 10;
        score -= fits_small as f64 * 3.0;
        if post_residual >= 10 && post_residual <= 20 && next_item_size > post_residual {
            score += 13.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 && post_residual > 20 {
            score -= 1.5;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < next_item_size / 2 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size >= next_item_size {
            score -= 1.0;
        }
        if post_residual > 12 && post_residual < 25 && next_item_size > post_residual {
            score += 1.0;
        }
        if post_residual >= 18 && post_residual <= 22 && next_item_size > post_residual {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= 10 && post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual as f64 > mean_residual * 0.8 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let twice_left = post_residual - next_item_size;
            if twice_left >= next_item_size.max(8) {
                score -= 1.0;
            }
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 10 && after <= 20 {
                score -= 1.0;
            }
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count >= 1 {
            score -= 1.0 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 1 && progress > 0.5 {
            score -= 1.5;
        }
        if post_residual > 0 && (post_residual as f64) < 0.05 * bin_capacity as f64 {
            score -= 2.0 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 20 {
            score += 1.5;
        }
        if next_item_size > 0 && post_residual >= 15 && post_residual <= 35 && post_residual % 5 == 0 && post_residual >= next_item_size {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual < next_item_size * 3 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 && progress > 0.6 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual > bin_capacity / 2 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && (post_residual - next_item_size) % 10 == 0 {
            score -= 1.0 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fitting_bins_count <= 3 {
            score -= 1.0 + 0.5 / (1.0 + fitting_bins_count as f64);
        }
        if next_item_size > 0 && post_residual >= 15 && post_residual < 20 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.04;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count <= 2 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual % 5 == 0 && fitting_bins_count <= 2 {
            score -= 0.5 + 0.5 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let stranded_gap = (next_item_size - post_residual) as f64;
            let near_close = item_size as f64 >= bin_residual as f64 * 0.85;
            if !near_close {
                score += stranded_gap * (0.10 + 0.15 * progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let dev2 = (post_residual as f64 - mean_residual).abs() / (mean_residual.max(1.0));
            score += dev2 * 1.5;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && post_residual >= next_item_size * 2 && post_residual < next_item_size * 3 && mean_residual > post_residual as f64 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 5 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= 10 && post_residual < 20 && post_residual < next_item_size {
            score += 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 0.5 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 1.0 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 5 && tail <= 40 {
                score -= 0.6 + 0.6 * progress;
            }
        }
        if post_residual == 0 && next_item_size > 0 {
            score -= 1.0 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 2 {
            let near = (post_residual - next_item_size) as f64 / (next_item_size.max(1) as f64);
            score += near * 1.2;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            if (post_residual as f64) < mean_residual * 0.5 {
                score += (next_item_size - post_residual) as f64 * 0.06;
            } else {
                score -= 0.4;
            }
        }
        if progress > 0.8 && post_residual == 0 {
            score -= 2.0 + 2.0 * (progress - 0.8) * 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= next_item_size {
                score -= 1.0 + 1.2 * progress;
            } else if tail > 0 && (tail as f64) < mean_residual * 0.35 && fitting_bins_count >= 2 {
                score += 0.6 + 0.6 * progress;
            }
        }
        if open_bins_count >= 5 && post_residual <= 4 {
            score -= 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 3 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            let tail_dev = ((tail as f64) - mean_residual).abs();
            if tail > 0 && tail_dev <= mean_residual * 0.3 {
                score -= 0.6 + 0.6 * progress;
            } else if (tail as f64) > mean_residual * 2.5 && tail > next_item_size {
                score += 0.5 + 0.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 6.0 && fitting_bins_count >= 1 && post_residual >= 8 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        // NEW (G91): dead-space ratio trade-off — reward existing bins whose
        // post-fit tail remains a usable fraction of capacity, scaled by
        // scarcity of alternatives.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            let usable = tail as f64 / bin_capacity.max(1) as f64;
            if usable >= 0.10 && usable <= 0.35 {
                score -= 0.5 + 0.5 * progress / (1.0 + fitting_bins_count as f64);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize tiny slivers
    // (< 10, unusable by any item) more than proportionally.
    if post_residual < 10 {
        score -= 18.0; // sliver = efficient packing, strongly reward
    } else {
        score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement is excellent. If next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 * (miss / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many candidates: prefer the tightest, mild extra pressure.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Compare against mean residual: bins with residual well below mean
    // are "tight" and should be consolidated into.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 3.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 1.5 * (res - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals large); late, squeeze everything into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the item is large relative to capacity or when
    // no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 * (1.0 - large_item); // small items: discourage new bin
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // pairing potential with next item
        }
    }

    // Mild penalty for accumulating too many open bins early.
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

