    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: items and residuals live in
    // capacity fractions; classify post_residual into residue classes mod 10
    // (typical item granularity) and reward residuals likely to be reusable.
    let cap = bin_capacity as f64;

