pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled non-linearly by stream progress.
    // Late in the stream, waste matters more -> steeper penalty on large residuals.
    let progress_coupling = 1.0 + progress * progress * 2.0;
    let mut score = pr * progress_coupling;

    // Smooth convex penalty for mid-range residuals (dead space that fits nothing useful).
    score += 30.0 * norm_pr * (1.0 - norm_pr) * (norm_pr - 0.5) * (norm_pr - 0.5) * 4.0;

    // Reward tight fits: subtract for small post_residual, stronger when few alternatives exist.
    let tightness = 1.0 - norm_pr;
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 40.0 * tightness * tightness * scarcity;

    // Lookahead coupling: if next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr - nxt).abs() / cap;
        let bonus = (1.0 - fit_next).max(0.0);
        score -= 25.0 * bonus * bonus * (1.0 - progress * 0.5);
    }

    // Mild penalty when this bin's residual deviates from mean residual (fragmentation control).
