    // Last-chance bonus: if only this bin fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Brand-new bin candidate: penalize mildly unless residual savings are large.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

