        }
        // G71 mutation: existing-bin two-step chain lookahead.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= next_item_size {
                score -= 1.0 + 1.2 * progress;
            } else if tail > 0 && (tail as f64) < mean_residual * 0.35 && fitting_bins_count >= 2 {
                score += 0.6 + 0.6 * progress;
            }
        }
        // G71: consolidation pressure.
        if open_bins_count >= 5 && post_residual <= 4 {
            score -= 1.5 + 1.0 * progress;
        }
        // G72 mutation: exact-fill lookahead.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 3 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        // G73 mutation: existing-bin three-step chain — when the tail after the
        // next item still hosts the next item again, prefer this bin strongly;
        // combined with the dead-space ratio penalty this tightens residual
        // compaction across the stream.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count >= 1 {
            score -= 1.2 + 1.2 * progress;
        }
        // G74 mutation: existing-bin dead-space ratio — penalize near-misses
        // quadratically in the fraction of the next item that would be wasted,
        // while rewarding bins whose tail stays reusable (near mean residual).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap_frac = (next_item_size - post_residual) as f64 / (next_item_size.max(1) as f64);
            score += gap_frac * gap_frac * (3.0 + 3.0 * (1.0 - progress));
            if (post_residual as f64) >= mean_residual * 0.7 {
                score -= 0.8 + 0.8 * progress;
            }
        }
        // G75 mutation: tail-reuse quality — when the tail after the next item
        // is close to the mean residual (a highly reusable chunk), reward it
        // more aggressively; when the tail is a tiny sliver, penalize it.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 {
                let reuse = 1.0 - ((tail as f64) - mean_residual).abs() / (mean_residual.max(1.0));
                if reuse > 0.8 {
                    score -= 0.8 + 0.8 * progress;
                } else if tail <= 2 {
                    score -= 0.8 + 0.8 * progress;
                }
            }
        }
        // G75: exact-match chain — post_residual equal to the next item leaves
        // a perfectly closed bin; reward strongly at any progress.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count >= 1 {
            score -= 1.0 + 1.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual relative to capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else if post_residual < 10 {
        score -= 25.0; // tiny dead space, effectively full
    } else {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0; // cannot fit lookahead item
        }
        if post_residual % 10 == 0 {
            score -= 6.0; // harmonic slot: divisible by 10
        } else {
            score += 4.0;
        }
        if frac >= 0.5 {
            score -= 3.0;
        } else if frac < 0.2 {
            score += 5.0;
        }
    }

    // Integer-division threshold classes on next_item_size
    if next_item_size > 0 {
        let nxt_class = next_item_size / 20;
        if post_residual >= next_item_size {
            score -= 2.0 + nxt_class as f64;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 12.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 20.0 && open_bins_count > 2 {
            score -= 10.0;
        }
        if progress < 0.2 {
            score -= 3.0;
        }
    }

    // Mild consolidation pressure
    score += open_bins_count as f64 * 0.05;

    score
}

