pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items (1..=10 minimum sizes) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Reward tight fits (high fill ratio of the current residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading when many
    // bins are already open; encourage consolidation.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize alternatives implicitly by
    // rewarding this one).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward strongly (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item won't fit here; if post residual is small dead
            // space, extra penalty.
            if post_residual < next_item_size {
                score += 6.0;
            }
        }
    }

    // Mean residual coupling: if this bin's residual is far below the
    // mean, it's a good candidate to close out (fill the tightest bins).
    let residual_gap = mean_residual - post_residual as f64;
    score -= 0.25 * residual_gap;

    // Slight preference to keep the brand-new-bin option only when
    // nothing tight is available: new bins (residual == capacity) get a
    // mild penalty so consolidation wins by default.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

