    // Compare against mean residual: prefer bins that are tighter than average.
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge relative to capacity
    // or no good fit exists (encourage consolidation).
