pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into modulo bands.
    let pr = post_residual;
    let pr_class = pr / 10; // 0..=10 harmonic band

    // Reward near-perfect fits strongly (small dead space is fine).
    if pr == 0 {
        score -= 120.0;
    } else if pr <= 5 {
        score -= 60.0;
    } else if pr <= 15 {
        score -= 15.0;
    } else if pr <= 30 {
        score += 10.0;
    } else {
        // Large residual left behind: penalize unless it can host next item.
        score += 20.0;
    }

    // Lookahead coupling: does post_residual accommodate next_item_size?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward, scaled by how snugly it fits.
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 + 0.5 * slack.max(0.0).min(40.0);
        } else {
            // Dead space relative to next item: penalize proportionally to waste.
            let waste = (next_item_size - pr) as f64;
            score += 0.6 * waste.min(60.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when current bin's fit is poor.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened frivolously.
        score += 45.0;
        // But if post_residual of an existing placement would be in a bad class
        // (tiny unusable sliver), opening a fresh bin becomes competitive.
        if pr > 0 && pr < 10 {
            score -= 30.0;
        }
        // Early in stream, new bins are cheaper (more future to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many open bins already, discourage proliferation.
        score += 2.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (drain the tightest bins first, keep loose bins flexible).
    score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.3;

    // Harmonic modulo term: residuals that are multiples of 10 pair well
    // with typical item sizes; slightly favor them.
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Mild preference for filling fuller bins (lower residual before placement).
    score += 0.2 * bin_residual as f64 * 0.1;

    score
}

