            // next item fits here: penalize leftover gap after both placements
            let gap_after_next = post_residual - next_item_size;
            score -= 200.0;
            score += gap_after_next as f64 * 0.8;
        } else {
            // next item cannot fit in residual: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // general proximity reward of post_residual to next_item_size
