pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Penalize leaving dead space that likely can't be filled by small items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny slivers are dead space
    }

    // Lookahead coupling: reward bins whose post_residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 10.0;
        }
        // Chain fit: post residual equals next item exactly
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Prefer fullest bins (low residual) when many bins are open
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Time horizon: early in stream, be conservative with new bins; late, allow slack
    let progress = step_index as f64 / total_items.max(1) as f64;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more when many bins are open and early
        score += 80.0 + 60.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 300.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0; // new bin can chain
        }
    }

    // Mild penalty for opening bins when a decent fit exists elsewhere
    if open_bins_count > 0 && fitting_bins_count > 1 {
        score += 5.0;
    }

    score
}

