pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize dead space that no future item (min size 1) can plausibly use efficiently:
    // small but nonzero post_residuals are the worst (fragmentation).
    if post_residual > 0 && post_residual < 6 {
        score += 8.0;
    }

    // Lookahead: reward if the next item also fits into the post residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 6.0 + 4.0 * chain_quality;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual too small for next item: mild penalty proportional to waste.
        score += 1.5 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: penalize opening a new bin, unless current bin
    // would leave an awkward residual and mean residual across open bins is low.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If open bins are mostly empty (low mean residual relative to capacity),
        // opening yet another bin is wasteful.
        score += 15.0 * (mean_residual / bin_capacity as f64);
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * (1.0 - progress);
        // Many open bins: extra penalty for adding another.
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    } else {
        // Prefer using bins whose residual deviates from the mean (harmonize residuals).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild bonus for using bins late in the stream to close them out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 2.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

