pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near "perfect" fill points
    // (multiples of 25, 33, 50) are more reusable by future items.
    let pr = post_residual;
    let residue_class = pr % 25;
    let class_bonus: f64 = match residue_class {
        0 => 12.0,
        1 | 24 => 6.0,
        2 | 23 => 3.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: post_residual divisible by common item sizes
    // (10..=20) means a "standard" item slots in perfectly later.
    for d in 10..=20u32 {
        if pr >= d && pr % d == 0 {
            score -= 8.0;
            break;
        }
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect chained fit
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            // harmonic class of the leftover gap
            score -= match gap % 10 {
                0 => 10.0,
                5 => 5.0,
                _ => 0.0,
            };
            score += (gap as f64) * 0.3;
        } else {
            // next item cannot use this bin's remainder -> dead space penalty grows
            score += (pr as f64) * 0.15 + 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating very small unusable slivers (dead space).
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // New-bin candidate handling: prefer reuse when mean residual is healthy.
    if bin_residual == bin_capacity {
        score += 40.0
            + (mean_residual.max(0.0)) * 0.5
            + (open_bins_count as f64) * 2.0;
    } else {
        // tightness reward: the smaller the post_residual (tighter pack), the better
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Stream progression: early on, be more willing to open bins (spread risk);
    // later, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 3.0;
    }

    score
}

