    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += 2.5 * open_bins_count as f64;

    // Lookahead: if next item fits the post-residual, bonus; else mild penalty.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate: make it attractive only when current bins would leave bad gaps.
