        score -= 5.0;
        if post_residual < 20 || (next_item_size > 0 && next_item_size > post_residual && fitting_bins_count <= 2) {
            score -= 20.0;
        }
    }

    // Slight preference for bins with residual near mean (balanced packing).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
