pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well it aligns with common item sizes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize residuals that fall into awkward harmonic classes.
    // Class by quarter-capacity bands: residuals near multiples of 25 are reusable.
    let quarter = (pr % 25.0) / 25.0;
    let quarter_penalty = (quarter - (quarter.min(1.0 - quarter))).abs();
    score += 8.0 * quarter_penalty;

    // Reward residuals that can host the lookahead item exactly or with small waste
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let waste = pr - nx;
            // perfect lookahead fit => strong reward
            if waste == 0.0 {
                score -= 30.0;
            } else {
                // harmonic bonus: lookahead fits with residual still in a good class
                let nw = (waste % 25.0) / 25.0;
                let nw_good = nw.min(1.0 - nw);
                score -= 12.0 * (1.0 - nw_good) - 4.0 * nw_good;
                // extra reward if lookahead leaves a residual matching small item sizes
                if waste % 10.0 == 0.0 {
                    score -= 6.0;
                }
            }
        } else {
            // lookahead cannot fit here; mild penalty scaled by how far off
            score += 5.0 + 0.1 * (nx - pr);
        }
    } else {
        // last item: just minimize leftover
        score -= 5.0;
    }

    // Integer division thresholds on post_residual
    let pr_u = post_residual;
    if pr_u == 0 {
        score -= 40.0; // perfect packing
    } else if pr_u < 10 {
        score += 15.0; // dead space below minimum item size
    } else if pr_u <= 20 {
        score -= 3.0;  // usable by small items
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when all open bins would create bad fits.
    if bin_residual == bin_capacity {
        score = cap * 0.5 + 10.0;
