    } else if post_residual >= 10 && post_residual < 25 {
        // awkward mid gap: partially usable, moderate penalty scaled by gap smallness
        score += (25 - post_residual) as f64 * 1.5;
    } else {
        // good fit: tight packing reward proportional to how full the bin becomes
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= fill * 15.0;
    }

    // Perfect fit bonus: leaving exactly zero or next-item-sized residual is great
