        score -= 60.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // residual can host the lookahead item: mild reward
        score -= 8.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
