            } else if tail > 0 && (tail as f64) < mean_residual * 0.35 && fitting_bins_count >= 2 {
                score += 0.6 + 0.6 * progress;
            }
        }
        // G71: consolidation pressure.
        if open_bins_count >= 5 && post_residual <= 4 {
            score -= 1.5 + 1.0 * progress;
        }
        // G72 mutation: exact-fill lookahead.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 3 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        // G73 mutation: existing-bin three-step chain.
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count >= 1 {
            score -= 1.2 + 1.2 * progress;
        }
        // G74 mutation: existing-bin dead-space ratio.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap_frac = (next_item_size - post_residual) as f64 / (next_item_size.max(1) as f64);
            score += gap_frac * gap_frac * (3.0 + 3.0 * (1.0 - progress));
            if (post_residual as f64) >= mean_residual * 0.7 {
                score -= 0.8 + 0.8 * progress;
            }
        }
        // G75 mutation (COMBINE): residual compaction — when several bins can
        // host the item, prefer the one whose post-residual tail best matches
        // the mean residual (most reusable), and penalize tails far below it
        // (likely dead space) to squeeze residual variance down.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 2 {
            let tail = post_residual - next_item_size;
            let tail_ratio = (tail as f64) / mean_residual.max(1.0);
            if tail_ratio >= 0.8 && tail_ratio <= 1.5 {
                score -= 1.0 + 1.0 * progress;
            } else if tail_ratio < 0.3 {
                score += 0.5 + 0.5 * progress;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small for typical items.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 200.0 * (10.0 - dead);
        }
        // Reward if the next item can exactly fill the residual (2-step lookahead).
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 500.0;
            } else if post_residual >= next_item_size {
                // Next item fits here later: mild reward proportional to snugness.
                let snug = (post_residual - next_item_size) as f64;
                score -= 50.0 * (1.0 - snug / bin_capacity as f64);
            } else {
                // Next item cannot use this residual: penalize proportionally.
                let gap = (next_item_size - post_residual) as f64;
                score += 20.0 * gap / (bin_capacity as f64);
            }
        }

        // Compare against mean residual: prefer bins tighter than average.
        score += (mean_residual - bin_residual as f64) * 0.5;

        // Last-chance bin: avoid opening a new bin when this is the only fit.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 150.0;
        }

        // Penalize opening a new bin when good open bins exist.
        if bin_residual == bin_capacity {
            // New-bin candidate: base cost plus penalty if item fits poorly anyway.
            score += 80.0;
            if post_residual as f64 > mean_residual {
                score += 60.0;
            }
            // Favor a new bin if the item is huge and would leave awkward residue.
            if item_size > bin_capacity / 2 && post_residual < 20 {
                score -= 100.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

