pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits mildly; Late: penalize waste strongly (quartic).
    let waste_weight = 1.0 + 3.0 * progress * progress * progress;
    score += waste_weight * norm_post * norm_post * 20.0;

    // Reward near-perfect fits with a smooth bump around post_residual ~ 0.
    let tightness = (-norm_post * 8.0).exp();
    score -= 12.0 * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space that next item likely cannot use (smooth interaction).
    let gap = post_residual as f64 - next_item_size as f64;
    if next_item_size > 0 {
        let unusable = (gap / bin_capacity as f64).max(0.0);
        score += 8.0 * unusable * unusable * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for spreading across many bins vs mean residual deviation.
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 4.0 * dev * dev * (0.3 + 0.7 * progress);

    // New-bin candidate: make empty bins moderately attractive unless current
    // bin fits extremely well; smooth in item size.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * norm_item - 8.0 * tightness;
    }

    score
}

