            if new_left >= 11 && new_left <= 19 && new_left < next_item_size { score += 2.0 ; }
        }
        if new_left < 10 && fitting_bins_count >= 1 && next_item_size > new_left { score += 4.0 ; }
        let avg_open = if open_bins_count > 0 { mean_residual } else { 0.0 } ;
        if avg_open > item_size as f64 * 1.5 && fitting_bins_count > 2 { score += 2.5 ; }
        if fitting_bins_count > 0 && avg_open > (new_left as f64) * 1.2 && item_size <= bin_capacity / 4 { score += 5.0 ; }
        if fitting_bins_count >= 3 && item_size <= bin_capacity / 3 { score += 3.0 ; }
        if progress > 0.8 && fitting_bins_count > 0 && item_size < bin_capacity / 2 { score += 6.0 * (progress - 0.8) * 10.0 ; }
        if fitting_bins_count == 0 && open_bins_count > 0 && avg_open >= item_size as f64 { score += 6.0 ; }
        if progress > 0.6 && fitting_bins_count >= 1 { score += 2.0 * (progress - 0.6) * 10.0 ; }
        if item_size >= bin_capacity * 2 / 5 && item_size <= bin_capacity / 2 && fitting_bins_count == 0 && open_bins_count > 0 { score += 3.0 ; }
        if next_item_size > 0 && new_left < next_item_size {
            let slack_factor = 1.0 + (mean_residual / bin_capacity . max (1) as f64) . min (1.0) * 0.5 ;
            score += ((next_item_size - new_left) as f64 / bin_capacity as f64) * 42.0 * slack_factor ;
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && post_residual >= mean_residual as u32 { score -= 3.0 + 2.5 * progress ; }
        if next_item_size > 0 && new_left >= next_item_size {
            let chain = new_left - next_item_size ;
            if chain >= next_item_size / 2 && chain <= next_item_size { score -= 2.0 ; }
            if (chain as f64) <= mean_residual * 0.5 { score -= 1.0 + 0.5 * progress ; }
            if chain > 0 && chain < next_item_size / 2 && avg_open >= item_size as f64 { score += 1.5 + 1.5 * progress ; }
            let tail_reuse = ((chain as f64) / mean_residual . max (1.0)) . min (2.0) ;
            if tail_reuse >= 1.0 { score -= 0.6 + 0.6 * progress * tail_reuse * 0.5 ; }
        }
