        if next_item_size > 0 && post_residual >= 10 && post_residual % 10 == 0 && post_residual >= next_item_size { score -= 2.0 ; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { score += (next_item_size - post_residual) as f64 * 0.08 ; }
        if next_item_size > 0 && post_residual == next_item_size { score -= 2.0 + 1.5 * progress ; }
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count >= 1 { score -= 1.0 + 1.5 * progress ; }
        if post_residual == 0 { score -= 1.0 + 2.0 * progress ; }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size ;
            if tail > 0 && tail <= 5 { score -= 1.0 + 1.0 * progress ; }
            if tail >= 10 && tail <= 20 { score -= 0.5 + 0.5 * progress ; }
            if tail == 0 { score -= 1.0 + 1.0 * progress ; }
            else if tail <= next_item_size / 4 { score -= 0.8 + 0.8 * progress ; }
