        }
        if post_residual <= 2 && item_size as f64 >= bin_residual as f64 * 0.9 { score -= 1.5 + 1.0 * progress ; }
        if progress > 0.8 && post_residual == 0 { score -= 2.0 + 2.0 * (progress - 0.8) * 10.0 ; }
