        // cannot hold the next item is nearly dead; penalize harder as scarcity rises.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && (post_residual as f64) < mean_residual * 0.4 {
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64) ;
            score += ((next_item_size - post_residual) as f64 / bin_capacity as f64) * 20.0 * (0.5 + scarcity) ;
        }
        // MUTATION: reward open bins whose post-residual stays within one mean-item of reuse,
        // reinforcing compaction along the residual mean.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size ;
            if (tail as f64) <= mean_residual * 0.6 { score -= 0.8 + 0.8 * progress ; }
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: prefer leftovers that are
    // "harmonically useful" (divisible into common small item sizes).
    let pr = post_residual as u32;
    if pr > 0 {
        // Dead-space penalty grows super-linearly for small unusable leftovers.
        if pr < 10 {
            score += 40.0 * (10.0 - pr as f64);
        }
        // Reward leftovers that divide cleanly by common item granularities.
        for &d in &[5u32, 10, 20, 25, 50] {
            if pr % d == 0 {
                score -= 6.0;
            }
        }
        // Exact fill is perfect.
        if pr == 0 {
            score -= 200.0;
        }
    } else {
        score -= 200.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            score += 0.15 * (next_item_size - pr) as f64;
        } else {
            // next item fits but leaves another residual; check harmonic chain
            let nr = pr - next_item_size;
            if nr % 10 == 0 {
                score -= 8.0;
            }
            score += 0.05 * nr as f64;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // A fresh bin should only win when the item is large or fit is poor.
        let waste = (bin_capacity - item_size) as f64;
        score += 30.0 + 0.2 * waste;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Tight fits are good: reward small relative slack.
    let slack = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * slack;

    // Progress-based mild pressure to consolidate early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual deviates favorably from the mean (tighter than average).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

