pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1) can use
    // are pure waste. Penalize tiny unusable gaps heavily (non-linearly).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Exact next-item lookahead: if the next item fits the post residual,
    // reward this placement (chains well).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.5 + 10.0;
    }
    // If the next item cannot fit and the post residual is small, penalize.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 15 {
        score += 12.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (avoid spreading); with few bins, tolerate looser fits.
