    score += pressure * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin; filling it tightens the bin set.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Mild progress term: early in the stream, be conservative about
    // creating small gaps; later, tighter packing matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    // New-bin candidate handling: an empty bin has high residual; make it
    // attractive only when the item is large relative to capacity or no
    // good fit exists among open bins.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
