pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but weight it more strongly
    score += 0.8 * (post_residual as f64 / bin_capacity as f64) * 50.0;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match (next item exactly fills remaining space) -> strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits with some slack left: mild reward proportional to closeness
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit in the leftover: penalize dead space creation
            score += 10.0 + 0.5 * gap;
        }

        // Coupling with mean residual: if this bin is far below mean residual,
        // it is a "junk" bin; penalize leaving junk there, reward filling it fully.
        let dev = post_residual as f64 - mean_residual;
        score += 0.15 * dev;

        // Two-step chain: if next item exactly fills post_residual, and item after
        // conceptually could use bin_residual - item_size - next_item_size, encourage chains
        let chain_left = post_residual as i64 - next_item_size as i64;
        if chain_left >= 0 && chain_left < 10 {
            score -= 15.0; // near-perfect two-item chain completion
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Make empty bins mildly unattractive by default.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so when many bins are already open
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if the current item is large, a fresh bin is fine
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is already small (consolidate waste)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Slight progression-awareness: late in the stream, tighten up more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
