    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: modulo arithmetic on capacity fractions ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: residuals that few item sizes can fill.
    // Items are 1..100; residual r is "usable" if next items can commonly fit.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Harmonic class via integer division thresholds on post_residual.
    if post_residual == 0 {
        // already handled
    } else if post_residual <= 10 {
        score += 60.0; // near-dead space
    } else if post_residual <= quarter {
        score += 25.0;
    } else if post_residual <= half {
        score -= 5.0;
    } else {
        score -= 10.0; // roomy bin
    }

    // Modulo coupling: residuals divisible by common item sizes are more reusable.
    let r = post_residual;
    let div_bonus = if r % 10 == 0 {
        12.0
    } else if r % 5 == 0 {
        6.0
    } else if r % 2 == 0 {
        3.0
    } else {
        0.0
    };
    score -= div_bonus;

    // --- Lookahead: does next_item_size fit exactly / well in the post residual? ---
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 200.0; // perfect chain
        } else if next_item_size < r {
            let slack = r - next_item_size as u32;
            // harmonic class of the double residual
            score -= 20.0 * (slack as f64 / cap);
            if slack % 10 == 0 {
