            score += 5.0;
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Prefer reusing an existing well-filled bin unless this one is the only option.
        if open_bins_count > 0 && fitting_bins_count >= 1 {
            score += 35.0;
        } else {
            score -= 15.0;
        }
