pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize bins with large residuals (wasteful bins) mildly.
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if next item fills the bin almost exactly.
        let chain = post_residual.saturating_sub(next_item_size);
        score -= 6.0 * (1.0 - chain as f64 / bin_capacity as f64);
    }
    // If next item is large and would NOT fit here, slight penalty for wasting a good bin.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 2.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current residuals are small / fragmented and many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64);
        // Penalize opening new bins normally...
