        new_bin_score -= 40.0 * fragmentation * fragmentation;
        // If the item barely fits nowhere well (post_residual tiny), new bin is fine.
        score = new_bin_score + post_residual as f64;
    }

    // Late in stream: consolidate, avoid leaving many small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

