pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // If many bins fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 40.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Last-chance situations favor reusing the fitting bin.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // Large items relative to capacity favor a fresh bin.
        score -= 0.3 * item_size as f64;
        // If mean residual is large, prefer using existing space.
        score += 0.4 * mean_residual;
        return score;
    }

    // --- Aggressive 2-step lookahead matching for existing bins ---

    // Perfect fit reward: exact match leaves zero waste.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item exactly fills the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if next_item_size <= post_residual {
