pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly (waste grows superlinearly)
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * dead * dead;

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 8.0;
        if post_residual as f64 > item_size as f64 * 0.5 {
            score += 5.0;
        }
    }

    // Time horizon: late in the stream, prefer tighter packing
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
