}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let post_frac = post / cap;

    // Base: prefer small post-residual (tight fit), mildly non-linear.
    let mut score = post + 8.0 * post_frac * post_frac * cap;

    // Smooth reward for tight fits, strengthened as the stream progresses.
    let tightness = (1.0 - post_frac).powi(3);
    score -= (20.0 + 40.0 * progress) * tightness;

    // Non-linear coupling: reward large item fraction more late in the stream.
    score -= fit_frac * fit_frac * (10.0 + 30.0 * progress) * cap * 0.05;

    // Penalize dead space that cannot fit the next item (lookahead awareness).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = ((nxt - post) / cap).max(0.0);
        score += 15.0 * unusable * (1.0 + progress);

        // Bonus if this placement leaves room exactly usable by next item.
        if post >= nxt && post - nxt < nxt {
            score -= 5.0 * (1.0 - ((post - nxt) / nxt));
        }
    } else {
        // Last item: reward filling as fully as possible.
        score -= 25.0 * tightness;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly early, allow it when open bins are
    // poor fits (their residuals far from post_residual) or stream is early.
    if bin_residual == bin_capacity {
        let dispersion = (mean_residual - post).abs();
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 6.0 - 4.0 * progress + 0.15 * dispersion - 2.0 * open_pressure * progress;
    } else {
        // Mild penalty for bins whose residual deviates strongly from the mean
        // (keeps residual distribution balanced, smooth coupling).
        let dev = (mean_residual - bin_residual as f64).abs() / cap;
        score += 4.0 * dev * dev * cap;
    }

    score
}

