pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps
    let min_item = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 50.0;
    }

    // Pressure from number of open bins
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
        score += 10.0;
    }

