pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0 + (10 - post_residual) as f64 * 10.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 150.0 - leftover as f64 * 2.0;
        } else {
            // Next item cannot follow here; penalize wasting space the next item could use elsewhere
            let gap = next_item_size - post_residual;
            score += gap as f64 * 1.5;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first)
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strong incentive to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 50.0 + (bin_capacity as f64 - post_residual as f64);
        if next_item_size > 0 && next_item_size >= post_residual && item_size >= 60 {
            score -= 120.0; // big item with big follower: fresh bin is fine
        }
    }

    // Late in stream: consolidate aggressively, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 30.0;
    }

    score
