    // Lookahead coupling: reward leaving exactly room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Dead space smaller than next item is wasted.
            score += 0.5 * (next_item_size - post_residual) as f64;
