    // Global fragmentation pressure: if mean residual is low, conserve space.
    let frag = (mean_residual - post_residual as f64).abs();
    score += 0.2 * frag;

    // Prefer bins whose residual is close to the item (perfect-ish fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
