        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size {
            let tail = new_left - next_item_size;
            let tail_dev = ((tail as f64) - mean_residual).abs();
            if tail_dev < mean_residual * 0.5 {
