            }
        }
        if fitting_bins_count >= 3 && item_size <= bin_capacity / 3 {
            score += 2.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count == 0 {
            score -= 2.0;
        }
        if next_item_size > 0 && new_left < next_item_size {
            let stranded_gap = (next_item_size - new_left) as f64;
            let strand_frac = stranded_gap / bin_capacity.max(1) as f64;
            let cap = 6.0;
            score += (strand_frac * 18.0).min(cap) * (0.5 + 0.5 * (1.0 - progress));
        }
        if progress > 0.85 && fitting_bins_count >= 1 && new_left > bin_capacity / 3 {
            score += 2.0 + 2.0 * (progress - 0.85) * 10.0;
        }
        if next_item_size > 0 && new_left >= next_item_size * 2 && fitting_bins_count >= 1 {
            score -= 1.2 + 1.2 * progress;
        }
        if next_item_size > 0 && new_left < next_item_size && fitting_bins_count >= 1 {
            let near_mean = ((new_left as f64) - mean_residual).abs() <= mean_residual * 0.3;
            if near_mean {
                score -= 0.8 + 0.6 * progress;
            } else if (new_left as f64) < mean_residual * 0.4 {
                score += 0.6 + 0.6 * progress;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            if new_left < next_item_size {
                let gap_frac = (next_item_size - new_left) as f64 / (next_item_size.max(1) as f64);
                score += gap_frac * gap_frac * (2.5 + 2.5 * (1.0 - progress));
            } else if new_left == next_item_size {
                score -= 1.5 + 1.0 * progress;
            }
        }
        // G75 mutation: fresh-bin chain-length harmonic — a fresh bin whose
        // leftover hosts the next item k>=2 times is a high-quality opening;
        // reward scales with chain length but stays modest so forced openings
        // remain cheap.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size {
            let chain_len = new_left / next_item_size;
            if chain_len >= 2 {
                score -= (0.6 * chain_len as f64).min(3.0) + 0.6 * progress;
            }
        }
        // G75 mutation: fresh-bin sliver guard — a leftover that is a tiny odd
        // sliver is almost surely dead space; penalize opening such a bin when
        // alternatives exist.
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left < 8 && new_left % 2 == 1 && new_left != next_item_size {
            score += 1.5 + 1.0 * progress;
        }
        // G111 mutation: dead-space-aware new-bin decision — prefer opening a
        // fresh bin when the fresh residual is a reusable chunk and the best
        // existing fit would strand a tiny unusable remainder.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let fresh_is_reusable = new_left >= next_item_size
                || (new_left % 10 == 0 && new_left >= 20 && new_left >= next_item_size / 2);
            let best_existing_strands = post_residual < next_item_size
                && (next_item_size - post_residual) <= 3;
            if fresh_is_reusable && best_existing_strands {
