        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 5 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= 10 && post_residual < 20 && post_residual < next_item_size {
            score += 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 0.5 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 1.0 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 5 && tail <= 40 {
                score -= 0.6 + 0.6 * progress;
            }
        }
        if post_residual == 0 && next_item_size > 0 {
            score -= 1.0 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 2 {
            let near = (post_residual - next_item_size) as f64 / (next_item_size.max(1) as f64);
            score += near * 1.2;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            if (post_residual as f64) < mean_residual * 0.5 {
                score += (next_item_size - post_residual) as f64 * 0.06;
            } else {
                score -= 0.4;
            }
        }
        if progress > 0.8 && post_residual == 0 {
            score -= 2.0 + 2.0 * (progress - 0.8) * 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= next_item_size {
                score -= 1.0 + 1.2 * progress;
            } else if tail > 0 && (tail as f64) < mean_residual * 0.35 && fitting_bins_count >= 2 {
                score += 0.6 + 0.6 * progress;
            }
        }
        if open_bins_count >= 5 && post_residual <= 4 {
            score -= 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 3 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count >= 1 {
            score -= 1.2 + 1.2 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap_frac = (next_item_size - post_residual) as f64 / (next_item_size.max(1) as f64);
            score += gap_frac * gap_frac * (3.0 + 3.0 * (1.0 - progress));
            if (post_residual as f64) >= mean_residual * 0.7 {
                score -= 0.8 + 0.8 * progress;
            }
        }
        // G75 mutation: existing-bin chain-length harmonic — prefer bins whose
        // tail after the next item hosts the next item k>=2 more times; this
        // compounds the three-step lookahead into a general chain rule.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_len = post_residual / next_item_size;
            if chain_len >= 3 {
                score -= (0.5 * (chain_len - 1) as f64).min(2.5) + 0.5 * progress;
            }
        }
        // G111 mutation: late-stream exact-match boost — near the end of the
        // stream, bins whose post-residual exactly equals the next item are
        // near-perfect compactions; reward them more aggressively.
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.6 {
            score -= 1.5 + 1.5 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for leaving space exactly matching the next item (2-step lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits perfectly in this bin afterwards: excellent.
            score -= (cap - gap) * 1.5;
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            score += gap * 0.5;
        }
    }

    // Perfect fit now is always great.
    if post_residual == 0 {
        score -= cap * 2.0;
    } else {
        // Penalize creating small unusable dead space (< typical min item).
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 3.0;
        }
        // Reward residuals that are large enough to stay reusable.
        score -= (pr / cap) * 8.0;
    }

    // Tightness of current fit: prefer bins where item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Relative to mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current fit is bad or item is large.
    if bin_residual == bin_capacity {
        let poor_fit = fill_ratio < 0.5;
        let late_stream = step_index as f64 / total_items as f64 > 0.8;
        if !poor_fit && !late_stream {
            score += 60.0;
        } else {
            score += 15.0;
        }
    }

    // Mild preference to keep number of open bins from exploding.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 60.0 * deadness * deadness;
