pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize by how well item fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Penalize large dead space quadratically (unusable gaps).
    let dead = post_residual as f64;
    score += 0.02 * dead * dead;

    // Lookahead: if the next item could fit into the post residual,
    // reward leaving useful space; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Wasted residual relative to next item size.
            let waste = post_residual as f64 - (next_item_size as f64 * (post_residual as f64 / bin_capacity as f64).min(1.0));
            score += 0.03 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good fit exists (item leaves large residual everywhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = (bin_residual - item_size) as f64 > 0.6 * bin_capacity as f64;
        if fitting_bins_count == 0 || (bad_fit && progress < 0.7) {
            score -= 20.0;
        } else {
            score += 15.0 + 10.0 * progress;
        }
    }

    // Global state: prefer bins with residual far from mean (balance spread),
    // slightly favor bins close to mean residual to keep flexibility.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling nearly-full bins as stream progresses (consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Mild penalty for having many open bins: encourage consolidation.
    score += 0.1 * open_bins_count as f64 * (1.0 - fill_ratio);

    score
}

