pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "perfect fits"
    // for common item sizes (multiples of 10 / small divisors of 100) are
    // dead space; residuals that can host another item are valuable.
    let r = post_residual;
    let cap = bin_capacity as f64;

    // Reward residuals that can still host a plausible next item.
    if next_item_size > 0 && r >= next_item_size {
        score -= 12.0 + 0.25 * (r as f64 - next_item_size as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to the miss.
        score += 0.6 * (next_item_size as f64 - r as f64);
    }

    // Modulo-10 harmonic classes: residuals in {0} are ideal; tiny residuals
    // (1..=9) are nearly dead space; mid residuals (10..=50) are reusable.
    if r == 0 {
        score -= 30.0; // perfect closure
    } else if r <= 9 {
        score += 15.0; // unusable sliver
    } else if r % 10 == 0 {
        score -= 8.0; // harmonically clean residual
    }

    // Integer-division thresholds: residual in the "half-full band" is
    // flexible; residual above 3*cap/4 risks becoming dead space.
    if r > (3.0 * cap / 4.0) as u32 {
        score += 10.0;
    } else if r > cap as u32 / 2 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or the
    // item is huge relative to the tightest fit.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += pressure + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // room for lookahead pairing in a fresh bin
