            let best_existing_strands = post_residual > 0 && post_residual < next_item_size && (next_item_size - post_residual) <= 3;
            if new_left >= next_item_size && best_existing_strands {
                score -= 2.0 + 2.0 * progress;
            }
        }
    } else {
        if fitting_bins_count > 3 && post_residual > 30 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 3.0;
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 1.5;
        }
        let band = (post_residual as f64 - mean_residual).abs();
        if band < 5.0 && post_residual >= next_item_size.max(1) {
            score -= 1.0;
        }
        if post_residual < next_item_size && post_residual < mean_residual as u32 {
            score += 2.0;
        }
        let fits_small = post_residual / 10;
        score -= fits_small as f64 * 3.0;
        if post_residual >= 10 && post_residual <= 20 && next_item_size > post_residual {
            score += 13.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 && post_residual > 20 {
            score -= 1.5;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < next_item_size / 2 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size >= next_item_size {
            score -= 1.0;
        }
        if post_residual > 12 && post_residual < 25 && next_item_size > post_residual {
            score += 1.0;
        }
        if post_residual >= 18 && post_residual <= 22 && next_item_size > post_residual {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= 10 && post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual as f64 > mean_residual * 0.8 {
            score += 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let twice_left = post_residual - next_item_size;
            if twice_left >= next_item_size.max(8) {
                score -= 1.0;
            }
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 10 && after <= 20 {
                score -= 1.0;
            }
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count >= 1 {
            score -= 1.0 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 1 && progress > 0.5 {
            score -= 1.5;
        }
        if post_residual > 0 && (post_residual as f64) < 0.05 * bin_capacity as f64 {
            score -= 2.0 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 20 {
            score += 1.5;
        }
        if next_item_size > 0 && post_residual >= 15 && post_residual <= 35 && post_residual % 5 == 0 && post_residual >= next_item_size {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual < next_item_size * 3 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 && progress > 0.6 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual > bin_capacity / 2 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && (post_residual - next_item_size) % 10 == 0 {
            score -= 1.0 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fitting_bins_count <= 3 {
            score -= 1.0 + 0.5 / (1.0 + fitting_bins_count as f64);
        }
        if next_item_size > 0 && post_residual >= 15 && post_residual < 20 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.04;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count <= 2 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual % 5 == 0 && fitting_bins_count <= 2 {
            score -= 0.5 + 0.5 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let stranded_gap = (next_item_size - post_residual) as f64;
            let near_close = item_size as f64 >= bin_residual as f64 * 0.85;
            if !near_close {
                score += stranded_gap * (0.10 + 0.15 * progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let dev2 = (post_residual as f64 - mean_residual).abs() / (mean_residual.max(1.0));
            score += dev2 * 1.5;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && post_residual >= next_item_size * 2 && post_residual < next_item_size * 3 && mean_residual > post_residual as f64 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 5 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= 10 && post_residual < 20 && post_residual < next_item_size {
            score += 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 0.5 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 1.0 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 5 && tail <= 40 {
                score -= 0.6 + 0.6 * progress;
            }
        }
        if post_residual == 0 && next_item_size > 0 {
            score -= 1.0 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 2 {
            let near = (post_residual - next_item_size) as f64 / (next_item_size.max(1) as f64);
            score += near * 1.2;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            if (post_residual as f64) < mean_residual * 0.5 {
                score += (next_item_size - post_residual) as f64 * 0.06;
            } else {
                score -= 0.4;
            }
        }
        if progress > 0.8 && post_residual == 0 {
            score -= 2.0 + 2.0 * (progress - 0.8) * 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= next_item_size {
                score -= 1.0 + 1.2 * progress;
            } else if tail > 0 && (tail as f64) < mean_residual * 0.35 && fitting_bins_count >= 2 {
                score += 0.6 + 0.6 * progress;
            }
        }
        if open_bins_count >= 5 && post_residual <= 4 {
            score -= 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 3 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count >= 1 {
            score -= 1.2 + 1.2 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap_frac = (next_item_size - post_residual) as f64 / (next_item_size.max(1) as f64);
            score += gap_frac * gap_frac * (3.0 + 3.0 * (1.0 - progress));
            if (post_residual as f64) >= mean_residual * 0.7 {
                score -= 0.8 + 0.8 * progress;
            }
        }
        // G75 mutation: existing-bin chain-length harmonic — prefer bins whose
        // tail after the next item hosts the next item k>=2 more times; this
        // compounds the three-step lookahead into a general chain rule.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_len = post_residual / next_item_size;
            if chain_len >= 3 {
                score -= (0.5 * (chain_len - 1) as f64).min(2.5) + 0.5 * progress;
            }
        }
        // G75 mutation: late-stream exact-match boost — near the end of the
        // stream, bins whose post-residual exactly equals the next item are
        // near-perfect compactions; reward them more aggressively.
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.6 {
            score -= 1.5 + 1.5 * progress;
        }
        // G112 mutation: waste-pressure existing-bin tightening — with many
        // open bins and high mean slack, reward existing bins whose residual
        // can host the next item and still leave a mean-sized reusable tail.
        if next_item_size > 0 && post_residual >= next_item_size && open_bins_count >= 4 {
            let tail = post_residual - next_item_size;
            if (tail as f64) >= mean_residual * 0.7 && (tail as f64) <= mean_residual * 1.3 {
                score -= 1.0 + 1.0 * progress;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // Gaps below the minimum item size (1..~10) are pure waste; gaps that
    // can't fit the next item are semi-waste.
    if post_residual < 10 {
        score += 60.0; // dead space penalty
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 18.0; // gap can't host the lookahead item
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0; // perfect lookahead fit: strong reward
    }

    // Reward tight fits relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 15.0 + 0.5 * open_bins_count as f64 + 20.0 * progress;
    } else {
        score -= 0.2 * open_bins_count as f64;
    }

    // Prefer bins with residual below mean (consolidating fuller bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference for bins whose post-residual can still host mid-size items.
    if post_residual >= 50 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    let r = post_residual as f64;
