        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size && new_left >= next_item_size && (post_residual as f64) < mean_residual * 0.5 {
            score -= 2.0 + 1.5 * progress;
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && post_residual >= mean_residual as u32 {
            score -= 3.0 + 2.5 * progress;
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && new_left > next_item_size && new_left < next_item_size * 2 && (new_left - next_item_size) > next_item_size / 2 && open_bins_count >= 2 {
            score += 1.0 + 1.0 * progress;
        }
        if progress > 0.85 && fitting_bins_count >= 1 && (new_left as f64) > item_size as f64 {
            score += 4.0 * (progress - 0.85) * 10.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size && (new_left as f64) <= mean_residual {
            score -= 1.0 + 0.8 * progress;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left > 0 && new_left < 5 && new_left != next_item_size {
