pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space after placement).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // Quadratic penalty on growing dead space.
        score += (post_residual as f64).powi(2) / 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize creating a residual that is useless for the next item
            // but too small to be attractive generally.
            if post_residual < next_item_size && post_residual < 20 {
                score += 18.0;
            }
        }
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or the current fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = mean_residual / bin_capacity as f64;
        // Penalize new bins early; relax as stream progresses or bins fill up.
