pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets (dead-space regimes).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1

    // Penalize leftovers in the "unusable" band (0 < frac < 0.1): dead space.
    if frac > 0.0 && frac < 0.1 {
        score += 25.0 * (0.1 - frac);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Integer-division threshold: post_residual / 10 class parity.
    let class = post_residual / 10;
    score -= (class % 3) as f64 * 2.0;

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this bin becomes a perfect pair -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let nfrac = next_item_size as f64 / post_residual as f64;
            // reward high fill ratios of the remaining space
