            if post2 < 10 {
                score += 10.0;
            }
        } else {
            // next item cannot use this leftover: mild penalty if leftover small
            if post_residual < 25 {
                score += 8.0;
            }
        }
    }

    // Last-chance bonus: only this bin fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin gets a base cost so it is chosen
    // only when open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Early in the stream, opening bins is fine; late, be frugal.
