    }

    // Modulo-arithmetic affinity: item and leftover sharing a harmonic class
    // (both divisible by 5) suggests future combinability.
    if post_residual % 5 == 0 {
        score -= 4.0;
    }
    if item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 6.0;
    }

    score
}

