pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer tight fits (small post_residual), with quadratic sharpening.
    let mut score = post + 0.35 * (post * post) / cap;

    // New-bin candidate: penalize opening fresh bins, more strongly late in the stream.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
        return score;
    }

    // Smooth coupling: post_residual interacts with stream progress.
    // Early on, waste is cheaper; late, dead space is heavily penalized.
    score += 12.0 * (post / cap) * (post / cap) * (0.3 + 1.4 * progress);

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - ((post - nxt) / cap)) * (0.5 + progress);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Slight preference for bins below mean residual (consolidate slack).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

