pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "reusable" grid points
    // (multiples of 10) are favored, since future items (10..80) more likely fit exactly.
    let post_class = post_residual % 10;
    let class_bonus: f64 = match post_class {
        0 => 30.0,          // perfectly aligned leftover
        5 => 12.0,          // half-grid, still reusable
        _ => 0.0,
    };
    score -= class_bonus;

    // Penalize tiny unusable dead space (< 10) — nothing can ever fit there.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Integer-division threshold: post_residual bucket quality.
    // Buckets: [0,10) bad, [10,30) tight, [30,60) medium, [60,100] good.
    let bucket = post_residual / 30;
    let bucket_penalty = match bucket {
        0 => 20.0,
        1 => 5.0,
        _ => 0.0,
    };
    score += bucket_penalty;

    // Lookahead coupling: reward if next item fits exactly in post_residual (harmonic match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let nxt = next_item_size as f64;
            // fraction of next item's size consumed by this bin's leftover
            score -= 15.0 * (nxt / (nxt + (post_residual - next_item_size) as f64));
            // modulo harmony between next item and post residual
            if (post_residual % next_item_size.max(1)) < 5 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; mild penalty scaled by how much it overshoots
            let over = (next_item_size - post_residual) as f64;
            score += 6.0 * (over / cap);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Tight fit reward: ratio of item to residual (mod-fraction style).
    if bin_residual > 0 {
        let fill = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fill * fill; // reward high fill fraction quadratically
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin, discounted when stream is young or bins are scarce
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = 1.0 / (open_bins_count.max(1) as f64);
        score = 70.0 - 30.0 * scarcity - 10.0 * (1.0 - progress);
