        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let stranded_gap = (next_item_size - post_residual) as f64;
            let near_close = item_size as f64 >= bin_residual as f64 * 0.85;
            if !near_close {
                score += stranded_gap * (0.10 + 0.15 * progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let dev2 = (post_residual as f64 - mean_residual).abs() / (mean_residual.max(1.0));
            score += dev2 * 1.5;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && post_residual >= next_item_size * 2 && post_residual < next_item_size * 3 && mean_residual > post_residual as f64 {
            score -= 1.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 5 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= 10 && post_residual < 20 && post_residual < next_item_size {
            score += 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 0.5 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 1.0 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 5 && tail <= 40 {
                score -= 0.6 + 0.6 * progress;
            }
        }
        if post_residual == 0 && next_item_size > 0 {
            score -= 1.0 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 2 {
            let near = (post_residual - next_item_size) as f64 / (next_item_size.max(1) as f64);
            score += near * 1.2;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            if (post_residual as f64) < mean_residual * 0.5 {
                score += (next_item_size - post_residual) as f64 * 0.06;
            } else {
                score -= 0.4;
            }
        }
        if progress > 0.8 && post_residual == 0 {
            score -= 2.0 + 2.0 * (progress - 0.8) * 10.0;
        }
        // existing-bin two-step chain lookahead.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= next_item_size {
                score -= 1.0 + 1.2 * progress;
            } else if tail > 0 && (tail as f64) < mean_residual * 0.35 && fitting_bins_count >= 2 {
                score += 0.6 + 0.6 * progress;
            }
        }
        // consolidation pressure.
        if open_bins_count >= 5 && post_residual <= 4 {
            score -= 1.5 + 1.0 * progress;
        }
        // exact-fill lookahead.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 3 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        // residual-reuse alignment.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            let tail_dev = ((tail as f64) - mean_residual).abs();
            if tail > 0 && tail_dev <= mean_residual * 0.3 {
                score -= 0.6 + 0.6 * progress;
            } else if (tail as f64) > mean_residual * 2.5 && tail > next_item_size {
                score += 0.5 + 0.5 * progress;
            }
        }
        // dead-space ratio trade-off — an existing bin whose post-fit tail is
        // small relative to the next item's chain capacity is nearly closed;
        // reward closing it out, scaled by progress.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 6.0 && fitting_bins_count >= 1 && post_residual >= 8 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        // NEW (G121): combine fine-grained residual fitting with lookahead —
        // an existing bin whose tail after the next item can still hold the
        // lookahead item again (double chain) is prime consolidation space.
        if next_item_size > 0 && post_residual >= next_item_size * 2 {
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.6 + 1.0 * scarcity * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize leaving gaps that are too small for the smallest possible item (1..=100 range, min item 1).
    // A residual of 0 is a perfect fit: reward it strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Exact-fit lookahead: if the next item exactly fills post_residual, strongly reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // If next item cannot fit in post_residual but post_residual is small, penalize (dead space chain).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Perfect pre-fit reward: item exactly matches residual.
    if item_size == bin_residual {
        score -= 50.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 25.0;
        // But if all open bins would leave large dead space, new bin becomes attractive.
        let avg_dead = mean_residual - post_residual as f64;
        if fitting_bins_count > 0 && avg_dead > 20.0 {
            score -= avg_dead * 1.2;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Mild preference for tighter existing bins relative to mean residual.
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.4;
    }

