pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals divisible by large chunk sizes
    // are more reusable, so reward them.
    let cap_frac = bin_capacity as f64;
    let pr = post_residual as f64;

    // Modulo classes on post_residual (capacity 100 => classes of 10, 25, 50)
    if post_residual % 50 == 0 {
        score -= 20.0;
    } else if post_residual % 25 == 0 {
        score -= 12.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Penalize very small unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward tight fits for next item, penalize large leftover
            score -= 15.0 * (1.0 - slack / cap_frac);
            // harmonic bonus if leftover after next item is in a good class
            let rem = post_residual - next_item_size;
            if rem % 25 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; mild penalty unless this is last chance
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap_frac;
        // open new bin only if mean residual is small (bins mostly full)
        score += 40.0 * (1.0 - crowding);
        // late in stream, prefer reusing existing bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
    } else {
        // Favor bins whose residual is close to item size (tight fit)
        let tightness = 1.0 - (bin_residual - item_size) as f64 / cap_frac;
        score -= 10.0 * tightness;
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.5;

    // Integer division threshold: residuals >= half capacity are valuable
    if post_residual >= bin_capacity / 2 {
        score -= 10.0;
    }

    score
}

