pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable for
    // future items (min size 1..100, but tiny gaps rarely match) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate penalty for gaps that only fit very small items.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
