        if item_size > 70 {
            score -= 30.0;
        }
    } else {
        // Slight reward for consolidating into existing bins when crowded.
        score -= pressure * 0.5;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; penalize leaving a gap it can't use.
            score += 8.0;
        }
    }

    // Prefer bins below mean residual (tighter bins) slightly.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

