    // Penalize dead space that no plausible item can fill.
    let dead = if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if x < nx { 25.0 * (nx - x) * (1.0 + progress) } else { -10.0 * x * x }
    } else {
        -10.0 * x * x
    };

    // Last-chance bonus: only one bin can fit this item.
    let last_chance = if fitting_bins_count == 1 { -30.0 * (1.0 + progress) } else { 0.0 };

    // Slight preference to spread load when many bins are open and mean residual is high.
    let spread = 0.05 * (open_bins_count as f64) * (mean_residual / cap) * (1.0 - progress);

    // New-bin candidate: neutral-ish score that competes with poor fits.
    let is_new = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_adjust = if is_new > 0.0 { 15.0 - 20.0 * progress } else { 0.0 };

    base + tightness + dead + last_chance + spread + new_bin_adjust
}

