    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions via integer division.
    let q = post_residual * 4 / bin_capacity; // 0..3 quarter classes
    match q {
        0 => score -= 12.0,               // near-perfect fit, reward strongly
        1 => score += 6.0,                // awkward small dead space, penalize
        2 => score -= 3.0,                // half-ish residual, mild reward
        _ => score -= 1.5,                // roomy bin, slight reward
    }

