pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: leave nothing usable behind
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space that no realistic item can fill
        let min_item = 1.0f64.min(bin_capacity as f64);
        if (post_residual as f64) < min_item {
            score -= 10.0;
        }
        // Dead-space penalty grows quadratically for small residuals
        let r = post_residual as f64;
        score += 0.05 * (30.0 - r).max(0.0) * (30.0 - r).max(0.0) * 0.0;
        if r < 10.0 {
            score += 5.0; // tiny unusable slivers are wasted capacity
        }
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly or closely
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 40.0; // chain placement: next item fills this bin perfectly
        } else if post_residual >= next_item_size {
            score -= (10.0 - gap.min(10.0)) * 1.5; // closer gap => better chaining
        } else {
            // next item won't fit here; mild penalty scaled by overflow
            score += gap * 0.3;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are poor fits
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 6.0; // fresh bin supports future chaining
        }
    }

    // Early stream: be slightly conservative, keep bins flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

