    // Normalized stream progress
    let progress = step_index as f64 / total_items as f64;

    // Smooth non-linear coupling of post_residual with progress
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Progress-weighted dead-space penalty: waste matters more late in the stream
    score -= 0.5 * (1.0 - progress) * pr;
    score += 0.2 * progress * pr * pr / bin_capacity as f64;

    // Penalize bins with residual far from mean (imbalance), smooth quadratic
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / bin_capacity as f64;

    // Reward tight fits: cubic smooth term favoring small post_residual
    let fit = 1.0 - pr / bin_capacity as f64;
    score -= 30.0 * fit * fit * fit;

    // Last-chance bonus: only one fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress);
    } else {
        score += 0.05 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.4 * next_item_size as f64;
        } else {
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Mild penalty for very crowded bin sets (encourage consolidation early)
    score += 0.02 * open_bins_count as f64 * progress;

    score
