            let slack = (post_residual - next_item_size) as f64;
            // reward proportional fit, penalize large slack left after next item
            score -= 25.0 * (1.0 - slack / (bin_capacity as f64));
            score += 0.15 * slack;
        } else {
            // next item cannot use this bin's remainder: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste.min(50.0);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.4 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Discourage opening a new bin when existing bins can absorb the item well.
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty unless the item is huge relative to capacity
        score += 20.0;
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 25.0;
        }
        // late in stream, prefer reusing open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    score
}

