    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 0.9 * t + 0.8 * t * t;
    score += 0.35 * (pr * pr) / cap * poly;

    // Reward tight fits, scaled smoothly by progress
    let tightness = 1.0 - pr / cap;
    score -= 25.0 * tightness * tightness * (1.0 + 0.5 * t);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.6 + 0.8 * t);
        } else {
            score -= 2.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bin bonus: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 18.0 + 12.0 * (1.0 - pr / cap);
    }

    // Mild penalty when many bins are open and residual is near mean (fragmentation)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * (open_bins_count as f64).sqrt() * (1.0 - t);

    // New-bin candidate: prefer it only when residual is large and stream is early
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - t) - 0.05 * pr;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

