    let mut score = post_residual as f64;

    // Reward tight fits strongly (best-fit core with non-linear shaping).
    let frac_used = item_size as f64 / bin_capacity as f64;
    score -= (frac_used * frac_used) * 40.0;

    // Penalize dead space that can never be used by typical items.
    if post_residual < 10 {
        score -= 25.0; // nearly perfect fill
    } else if post_residual < 20 {
        score -= 8.0;
    } else if post_residual > 60 {
        score += 12.0; // large leftover is wasteful unless unavoidable
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
