    score -= 40.0 * (1.0 - fit_ratio).powf(4.0);

    // Penalize creating awkward dead space (post residual in 1..=15 zone is hard to fill).
    if post_residual > 0 && post_residual <= 15 {
        score += 12.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * (1.0 - next_tightness);
        } else if next_item_size > post_residual {
            // Next item won't fit here; slight penalty proportional to waste risk.
            score += 5.0 * (next_item_size as f64 / bin_capacity as f64);
        }
