    // Last-chance bonus: this is the only fitting bin; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when residuals are already fragmented.
    if bin_residual != bin_capacity {
        let frag = (mean_residual - post_residual as f64).abs();
        score += 0.15 * frag;
        score += 0.5 * open_bins_count as f64;
    }

    // New-bin candidate handling: only attractive for very large items or late stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score += waste * (1.2 - 0.6 * progress);
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Early stream: be slightly conservative, prefer filling existing bins fully.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
