    score += 40.0 * poly * (1.0 - progress);

    // Late-stream penalty grows quadratically with normalized residual.
    score += 30.0 * norm_pr * norm_pr * progress;

    // Reward near-perfect fits smoothly (residual close to zero).
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness;

    // Last-chance bonus: only one fitting bin, avoid opening a new one.
