pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong primary reward: post_residual exactly matches next item's size (perfect 2-step chain)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Secondary: next item fits into the post residual with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize wasted residual
        score += 0.15 * post_residual as f64;
    }

    // Tight fits are good (small post residual relative to capacity)
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins with less residual than average are more valuable
