    let tight = (2.0 * fit - 1.0).tanh();
    score -= 25.0 * tight * (1.0 - 0.5 * progress);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead synergy: smooth quadratic interaction with next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let synergy = (pr - n) / cap;
        let s = synergy * synergy;
        score += 12.0 * s * (1.0 - progress);
        if n <= pr {
            score -= 8.0 * (1.0 - s);
        }
