        score -= 6.0; // perfectly divisible residual, easy to fill later
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else if post_residual % 2 == 0 {
        score -= 1.0;
    } else {
        score += 2.0; // odd residual, harder to pair
    }

    // Integer-division thresholds: penalize residuals too small for the smallest class (1..10)
