    if fill_frac >= 0.9 {
        score -= 10.0;
    } else if fill_frac >= 0.7 {
        score -= 5.0;
    } else if fill_frac < 0.4 {
        score += 4.0;
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer reusing open bins unless residual is very tight
    if bin_residual == bin_capacity {
        // opening a new bin is only good when current item is large and mean residual is small
