pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // 2-step lookahead: reward when next item fits the post residual exactly-ish
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual as f64 - next_item_size as f64;
            // Perfect chain match gets strong reward
            if slack < 5.0 {
                score -= 60.0;
            } else {
                score -= 25.0 / (1.0 + slack * 0.1);
            }
        } else {
            // Next item won't fit here: penalize large dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += (next_item_size as f64 - dead) * 0.3;
            }
        }
    } else {
        // Last item: just minimize post residual (already base)
    }

    // Penalize deviating far from mean residual (avoid fragmenting the bin pool)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * mean_residual;
        // But if next item is large and current fit is terrible, opening is fine
        if next_item_size > post_residual && post_residual < 15 {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate, prefer filling existing bins harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

