        if open_bins_count >= 5 && post_residual <= 4 {
            score -= 1.5 + 1.0 * progress;
        }
        // exact-fill lookahead.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 3 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        // residual-reuse alignment.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            let tail_dev = ((tail as f64) - mean_residual).abs();
            if tail > 0 && tail_dev <= mean_residual * 0.3 {
                score -= 0.6 + 0.6 * progress;
            } else if (tail as f64) > mean_residual * 2.5 && tail > next_item_size {
                score += 0.5 + 0.5 * progress;
            }
        }
        // dead-space ratio trade-off — near-closed bins get closing reward.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 6.0 && fitting_bins_count >= 1 && post_residual >= 8 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        // MUTATION (gen 142): late-stream closing of nearly-full bins.
        if progress > 0.85 && post_residual > 0
            && (post_residual as f64) / (bin_capacity.max(1) as f64) <= 0.05 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * (1.0 - progress);
    score += 12.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = (item_size as f64) / cap;
    score -= tightness * tightness * (1.0 + 2.0 * progress) * 15.0;

    // Penalize dead space: small post_residual that is unusable
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            let waste = (nxt - pr) / cap;
            score += waste * (30.0 + 40.0 * progress);
        } else if pr >= nxt {
            // reward leaving room for the lookahead item
            score -= (nxt / cap) * 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Last-chance bonus: only fitting bin should absorb the item
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 2.0;
    }

    // Penalize spreading across many open bins late in the stream
    score += (open_bins_count as f64) * 0.5 * progress;

    // Mild deviation from mean residual
    score += (pr - mean_residual).abs() * 0.1;

    // New-bin candidate: keep it attractive only for large items / tight fits
    if bin_residual == bin_capacity {
        score += 8.0 - 10.0 * tightness;
    }

