    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += (11.0 - post_residual as f64) * 8.0; // unusable sliver penalty
        } else if post_residual < item_size {
            // gap smaller than current item: likely dead space unless future items fit
            score += (item_size - post_residual) as f64 * 0.5;
        } else {
            score += post_residual as f64 * 0.15; // mild waste pressure otherwise
