    } else {
        score -= 12.0; // perfect fill is excellent
    }

    // Reward tight fits (item dominates residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 6.0;

    // Open-bin pressure: discourage spreading across many bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

