        score += 4.0;
    } else {
        score -= 1.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Lookahead: check whether the next item can consume the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64 / 100.0) * 10.0; // residual is reusable
