pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: exact fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 250.0;
        }
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use.
        score += 0.5 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize creating very small unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: discourage opening a new bin unless the current
    // fit is terrible or the item nearly fills the fresh bin.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 200.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    score
}

