pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual > 0 {
        // dead space grows worse if smaller than the smallest conceivable item
        let unusable = (10u32.saturating_sub(post_residual)) as f64;
        score += 3.0 * unusable;
    }

    // Lookahead: bonus if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty for wasting the lookahead
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0 + 0.1 * item_size as f64;
    }

    // Scarcity pressure: when few bins can fit the item, prefer using them.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state coupling: prefer filling bins when mean residual is high
    // (lots of scattered space) to consolidate.
    score -= 0.05 * mean_residual;

    // Penalize bins that deviate far from the mean residual (keep portfolio balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, expensive late.
        score -= 10.0 * (1.0 - progress);
        score += 15.0 * progress;
        // Opening a new bin is worse when many bins are already open.
        score += 0.5 * open_bins_count as f64;
    } else {
        score -= 5.0 * progress;
    }

    // Mild bonus for using bins with larger residuals (big holes first).
    score -= 0.02 * bin_residual as f64;

    score
