pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residuals too small for any item (min size 1, but tiny slivers
    // below ~10 are rarely usable given the 10..80 regime) are heavily penalized.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Harmonic class of post_residual: classify leftover into capacity fractions.
    // Residuals in the "quarter band" (25..=50) are versatile; the near-half band
    // (50..=75) is even better; exact small classes are good.
    let band = (post_residual * 4) / bin_capacity; // 0..4 harmonic class
    match band {
        0 => score += 12.0,             // tiny leftover, mostly dead
        1 => score -= 6.0,              // quarter-ish leftover: flexible
        2 => score -= 14.0,             // half-ish leftover: very valuable
        3 => score -= 4.0,              // three-quarter leftover: big gap
        _ => {}                          // full-ish leftover (new bin case)
    }

    // Modulo-10 class of post_residual: residuals divisible into common item
    // sizes (multiples of 10) compose better.
    let m = post_residual % 10;
    if m == 0 {
        score -= 5.0;
    } else {
        score += m as f64 * 0.8; // ragged leftover penalized
    }

