    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further residue; mild reward scaled by fit tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalty grows with how much it misses
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.5;
