    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): neutral-ish baseline, but discourage opening
    // a new bin when the item is small and open bins have plenty of room.
    if bin_residual == bin_capacity {
        score += 8.0;
        if item_size <= bin_capacity / 4 && mean_residual > 40.0 {
            score += 25.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Slight preference for bins whose residual is below the mean (consolidate
    // fragmented space, keep large-residual bins open for big future items).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    score
}

