        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, with a mild quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * (bin_capacity as f64);

    // Lookahead: penalize this bin if the next item would fit perfectly here
    // but not in the post-residual (waste a "perfect slot").
    if next_item_size > 0 {
        let next_fits_now = next_item_size <= bin_residual;
        let next_fits_after = next_item_size <= post_residual;
        if next_fits_now && !next_fits_after {
            score += 0.9 * (bin_residual - next_item_size) as f64;
        }
        // Reward keeping post_residual usable for the next item.
        if next_fits_after {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        }
        // If next item is huge, prefer leaving large residuals elsewhere;
        // slightly favor big residual bins for the big item.
        score += 0.15 * (next_item_size as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Global pressure: many open bins -> discourage spreading; few bins -> consolidation.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64).sqrt();
    score += 8.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual deviates from the mean,
    // prefer bringing residuals toward balance (reduces fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.25 * dev;

    // Time horizon: early in stream, be picky (penalize loose fits more);
    // late in stream, just close bins out (favor any fit in an open bin).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 10.0 * (post_residual as f64 / bin_capacity as f64);
    score -= t * 5.0;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this empty bin call has perfect residual but we gate it by state).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced under high load / many bins.
        let mut new_bin_cost = 55.0 + 0.4 * post_residual as f64;
        new_bin_cost -= 10.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            // If next item is large too, a fresh bin may serve both poorly -> extra cost.
            new_bin_cost += 0.2 * next_item_size as f64;
        }
        if fitting_bins_count == 0 {
            // No open bin fits at all: must open (or this is the only option).
            new_bin_cost -= 200.0;
        } else if fitting_bins_count == 1 {
            // One bin fits: prefer it over a new bin.
            new_bin_cost += 40.0;
        }
        score += new_bin_cost;
    }

    score
}

