        }
        if fitting_bins_count >= 3 && item_size <= bin_capacity / 3 {
            score += 2.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count == 0 {
            score -= 2.0;
        }
        if next_item_size > 0 && new_left < next_item_size {
            let stranded_gap = (next_item_size - new_left) as f64;
            let strand_frac = stranded_gap / bin_capacity.max(1) as f64;
            let cap = 6.0;
            score += (strand_frac * 18.0).min(cap) * (0.5 + 0.5 * (1.0 - progress));
        }
        if progress > 0.85 && fitting_bins_count >= 1 && new_left > bin_capacity / 3 {
            score += 2.0 + 2.0 * (progress - 0.85) * 10.0;
        }
        if next_item_size > 0 && new_left >= next_item_size * 2 && fitting_bins_count >= 1 {
            score -= 1.2 + 1.2 * progress;
        }
        if next_item_size > 0 && new_left < next_item_size && fitting_bins_count >= 1 {
            let near_mean = ((new_left as f64) - mean_residual).abs() <= mean_residual * 0.3;
            if near_mean {
                score -= 0.8 + 0.6 * progress;
            } else if (new_left as f64) < mean_residual * 0.4 {
                score += 0.6 + 0.6 * progress;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            if new_left < next_item_size {
                let gap_frac = (next_item_size - new_left) as f64 / (next_item_size.max(1) as f64);
                score += gap_frac * gap_frac * (2.5 + 2.5 * (1.0 - progress));
            } else if new_left == next_item_size {
                score -= 1.5 + 1.0 * progress;
            }
        }
        // G145 mutation: fresh-bin near-mean leftover — a fresh bin whose
        // leftover lands close to the mean open residual is redundant with
        // existing capacity when several bins already fit; make it costlier.
        if next_item_size > 0 && fitting_bins_count >= 3
            && ((new_left as f64) - mean_residual).abs() <= 3.0 {
