        }
        // G145 mutation: late-stream exact-fit closing — near the end, prefer
        // existing bins that fill to near-exact fits over opening fresh bins.
        if progress > 0.9 && fitting_bins_count >= 2
            && post_residual >= next_item_size && (post_residual - next_item_size) <= 6 {
