        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 5 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= 10 && post_residual < 20 && post_residual < next_item_size {
            score += 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 0.5 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 1.0 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 5 && tail <= 40 {
                score -= 0.6 + 0.6 * progress;
            }
        }
        if post_residual == 0 && next_item_size > 0 {
            score -= 1.0 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 2 {
            let near = (post_residual - next_item_size) as f64 / (next_item_size.max(1) as f64);
            score += near * 1.2;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            if (post_residual as f64) < mean_residual * 0.5 {
                score += (next_item_size - post_residual) as f64 * 0.06;
            } else {
                score -= 0.4;
            }
        }
        if progress > 0.8 && post_residual == 0 {
            score -= 2.0 + 2.0 * (progress - 0.8) * 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= next_item_size {
                score -= 1.0 + 1.2 * progress;
            } else if tail > 0 && (tail as f64) < mean_residual * 0.35 && fitting_bins_count >= 2 {
                score += 0.6 + 0.6 * progress;
            }
        }
        if open_bins_count >= 5 && post_residual <= 4 {
            score -= 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 3 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count >= 1 {
            score -= 1.2 + 1.2 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap_frac = (next_item_size - post_residual) as f64 / (next_item_size.max(1) as f64);
            score += gap_frac * gap_frac * (3.0 + 3.0 * (1.0 - progress));
            if (post_residual as f64) >= mean_residual * 0.7 {
                score -= 0.8 + 0.8 * progress;
            }
        }
        // G145 mutation: exact-chain bonus — residual after placing the next
        // item equals half the next item; deep reward for near-perfect chains.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail == next_item_size / 2 && tail >= 3 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        // G145 mutation: late-stream closing — prefer existing bins that fill
        // to >= 95% of capacity near the end of the stream.
        if progress > 0.85 && post_residual > 0
            && (post_residual as f64) / (bin_capacity.max(1) as f64) <= 0.05 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tight fit preferred, with non-linear (quadratic/cubic) coupling.
    let mut score = pr + 0.8 * (pr * pr) / cap + 0.4 * (pr * pr * pr) / (cap * cap);

    // Normalize residual relative to mean residual of open bins: penalize
    // leaving more slack than average, reward below-average slack.
    let norm = if mean_residual > 0.0 { pr / mean_residual } else { 1.0 };
    score += 6.0 * (norm - 1.0).tanh();

    // Stream-progress coupling: late in the stream, tightness matters more;
    // early on, be slightly more willing to spread items.
    score *= 1.0 + 0.35 * progress * (pr / cap);

    // Lookahead: reward if next item fits into post_residual (smooth bonus).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (1.0 - (nx - pr).abs() / cap).max(0.0);
        if nx <= pr {
            score -= 4.0 * fits;
        } else {
            // Penalize post_residuals that are awkwardly small (dead space)
            let dead = ((nx - pr) / cap).min(1.0);
            score += 3.0 * dead * dead;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty scaled by number of alternatives to encourage diversity.
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine for big items, wasteful for tiny ones.
        score = cap - it + 8.0 - 0.5 * progress * it;
        if fitting_bins_count <= 1 {
            score -= 6.0; // no good alternative: new bin is attractive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 60.0 * deadness * deadness;
