        // plausible host for a small follow-up; deep reward in existing bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail == next_item_size / 2 && tail >= 3 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        // G147: strand-gap gradient — existing bins stranding the next item by
        // exactly 1-2 on a sizeable item are dead ends; graded penalty.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 2 && next_item_size >= 15 {
                score += 2.0 + 1.5 * progress;
            }
        }
        // G147: late-stream near-full closing — reward existing bins that
        // fill to >= 95% capacity near the end of the stream.
        if progress > 0.85 && post_residual > 0
            && (post_residual as f64) / (bin_capacity.max(1) as f64) <= 0.05 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fill_ratio * fill_ratio;

    // Penalize post-residuals that are too small to be useful for typical items,
    // but only mildly when they are exactly zero (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.5 * fill_ratio * cap;
    }

    // Lookahead coupling: if the next item could use the post-residual well,
    // reward leaving that exact amount of space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64 - nx).abs() < 3.0 {
            score -= 20.0; // next item fits this bin perfectly afterwards
        } else if post_residual as f64 >= nx {
            score -= 6.0; // next item could still go here
        } else {
            score += 8.0 * (1.0 - post_residual as f64 / nx); // dead space for lookahead
        }
    }

    // Global state: with many open bins, prefer consolidating into existing bins
    // with larger residuals; with few open bins, new bins are cheaper.
    let congestion = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / cap);
    score += 0.35 * congestion;

    // Mean residual coupling: when mean residual is large (waste accumulating),
    // push harder toward filling existing bins.
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Time horizon: late in the stream, avoid opening new bins at almost any cost.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus escalating late-stream penalty.
        score += cap * 0.55 + 60.0 * progress * progress;
        // But early on, if the item is huge and no bin fits well, new bin is fine.
        if item_size as f64 > 0.7 * cap && progress < 0.3 {
            score -= 25.0;
        }
    }

    score
}

