        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 0.5 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 1.0 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 5 && tail <= 40 {
                score -= 0.6 + 0.6 * progress;
            }
        }
        if post_residual == 0 && next_item_size > 0 {
            score -= 1.0 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 2 {
            let near = (post_residual - next_item_size) as f64 / (next_item_size.max(1) as f64);
            score += near * 1.2;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            if (post_residual as f64) < mean_residual * 0.5 {
                score += (next_item_size - post_residual) as f64 * 0.06;
            } else {
                score -= 0.4;
            }
        }
        if progress > 0.8 && post_residual == 0 {
            score -= 2.0 + 2.0 * (progress - 0.8) * 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= next_item_size {
                score -= 1.0 + 1.2 * progress;
            } else if tail > 0 && (tail as f64) < mean_residual * 0.35 && fitting_bins_count >= 2 {
                score += 0.6 + 0.6 * progress;
            }
        }
        if open_bins_count >= 5 && post_residual <= 4 {
            score -= 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 3 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count >= 1 {
            score -= 1.2 + 1.2 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap_frac = (next_item_size - post_residual) as f64 / (next_item_size.max(1) as f64);
            score += gap_frac * gap_frac * (3.0 + 3.0 * (1.0 - progress));
            if (post_residual as f64) >= mean_residual * 0.7 {
                score -= 0.8 + 0.8 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_len = post_residual / next_item_size;
            if chain_len >= 3 {
                score -= (0.5 * (chain_len - 1) as f64).min(2.5) + 0.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.6 {
            score -= 1.5 + 1.5 * progress;
        }
        // G147: exact half-chain bonus — tail equal to half the next item is a
        // plausible host for a small follow-up; deep reward in existing bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail == next_item_size / 2 && tail >= 3 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        // G147: strand-gap gradient — existing bins stranding the next item by
        // exactly 1-2 on a sizeable item are dead ends; graded penalty.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 2 && next_item_size >= 15 {
                score += 2.0 + 1.5 * progress;
            }
        }
        // G147: late-stream near-full closing — reward existing bins that
        // fill to >= 95% capacity near the end of the stream.
        if progress > 0.85 && post_residual > 0
            && (post_residual as f64) / (bin_capacity.max(1) as f64) <= 0.05 {
            score -= 2.0;
        }
        // G148: near-full closing anywhere in the stream — a bin that fills
        // to >= 97% is near-perfect compaction; graded reward.
        if post_residual > 0 && (post_residual as f64) / (bin_capacity.max(1) as f64) <= 0.03 {
            score -= 1.0 + 1.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let fit_frac = if open_bins_count > 0 { fitting_bins_count as f64 / open_bins_count as f64 } else { 0.0 };

    let mut score = pr;

    // Smooth polynomial coupling: prefer small post_residual, weighted by stream progress.
    let poly = norm_pr * norm_pr * (1.0 - norm_item) * (1.0 + progress);
    score += 60.0 * poly;

    // Reward tight fits more as stream advances (quadratic in progress).
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress * progress);

    // Penalize leaving dead space that cannot fit the lookahead item (smooth gate).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += 20.0 * gap * gap * (1.0 - progress);
    }

    // Last-chance bonus: smooth sigmoid-like reward when few bins fit.
    let scarcity = 1.0 / (1.0 + fit_frac * fit_frac * 4.0);
    score -= 15.0 * scarcity;

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * (pr - mean_residual);

    // Small penalty for opening new bins late in the stream.
    score += 2.0 * progress * (1.0 - norm_item);

