pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: penalize residuals that are just under the next item size
    // (dead space), reward residuals that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Next item can fit here afterwards: reward proportional to snugness
            score -= 3.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proximity to nxt from below
            let gap = nxt - post_residual as f64;
            score += 2.0 * (1.0 - gap / nxt.max(1.0));
        }
    }

    // Relative to mean residual: prefer bins with residual above the mean (more room)
