pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes via integer division.
    // post_residual <= 10 is essentially perfect; <= 25 is a "harmonic" class
    // that can still host small items (sizes 1..=25 possible).
    let cls = post_residual / 25; // 0: 0-24, 1: 25-49, 2: 50-74, 3: 75+
    match cls {
        0 => score -= 12.0,
        1 => score -= 4.0,
        2 => score += 6.0,
        _ => score += 14.0,
    }

    // Exact-fill reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but not perfectly: mild reward scaled by tightness
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: penalize large residuals slightly
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to
    // the residual we abandon. Penalize proportionally to mean_residual.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.5;
    } else {
        // Prefer tighter-than-average bins (best-fit style)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 2.0;
        }
    }

    // Late in the stream, avoid opening new bins; consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Modulo harmonic: residuals divisible by common item sizes (5,10,20,25)
    // are more reusable.
    if post_residual > 0 && (post_residual % 5 == 0) {
        score -= 3.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

