pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post-residual: small residues are dead space, but
    // residues that are multiples of small integers (harmonic classes) are
    // more likely to be filled by future items.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        0.0
    } else if pr % 10 == 0 {
        15.0
    } else if pr % 5 == 0 {
        8.0
    } else if pr % 2 == 0 {
        4.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize residues in awkward ranges (too small for min item, too large
    // to be "nearly full" credit).
    if pr > 0 && pr < 10 {
        score += 40.0; // unusable dead space below min item size
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next item fits: residual is reusable
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mildly penalize
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit
    // is very poor or stream is early and consolidation is unlikely.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 60.0 && item_size <= 30;
        if fitting_bins_count > 0 && !poor_fit {
            score += 200.0 + 100.0 * (1.0 - progress);
        } else {
            // still slightly prefer reusing when possible
            score += 50.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor with
    // harmonic modulation).
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev;

    // Mild penalty for very large item into nearly-empty bin when many bins
    // are open (fragmentation control).
    if item_size >= 70 && bin_residual == bin_capacity && open_bins_count > 3 {
        score -= 20.0;
    }

    score
}

