    // that leaves dead space), unless it's a near-perfect fill.
    let slack = bin_residual as f64 - item_size as f64;
    if slack > 0.0 && slack < 10.0 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild bonus scaled by how well it nests
            let nest = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - nest / bin_capacity as f64);
