    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, prefer the tightest one; slight exploration bonus.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
