    // Smooth coupling with stream progress: early on, tolerate waste; late, punish it
    score += 40.0 * norm_pr * progress * progress;

    // Reward tight fits smoothly (post residual near zero)
    score -= 10.0 * (1.0 - norm_pr).powi(4);

    // Last chance bin: smooth bonus when few fitting bins
    let fit_term = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 8.0 * fit_term;

    // Lookahead: reward leaving space for the next item (smooth quadratic gap)
    let gap = (pr - next_item_size as f64).abs();
    score += 0.15 * gap * gap / (1.0 + gap);

    // Penalize bins far from mean residual (fragmentation smoothing)
    score += 0.05 * (pr - mean_residual).abs();

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

