            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            if new_left < next_item_size {
                let gap_frac = (next_item_size - new_left) as f64 / (next_item_size.max(1) as f64);
                score += gap_frac * gap_frac * (2.5 + 2.5 * (1.0 - progress));
            } else if new_left == next_item_size {
                score -= 1.5 + 1.0 * progress;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size {
            let chain_len = new_left / next_item_size;
            if chain_len >= 2 {
                score -= (0.6 * chain_len as f64).min(3.0) + 0.6 * progress;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left < 8 && new_left % 2 == 1 && new_left != next_item_size {
            score += 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left > 0 && new_left < 5 && new_left != next_item_size {
            score += 2.0 + 1.5 * progress;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && new_left >= next_item_size * 2
            && (new_left - next_item_size * 2) <= 5 && post_residual < next_item_size {
            score -= 1.2 + 1.2 * progress;
        }
        if progress > 0.9 && fitting_bins_count >= 2
            && post_residual >= next_item_size && (post_residual - next_item_size) <= 6 {
            score -= 1.5 + 1.0 * (progress - 0.9) * 10.0;
        }
        // G158 mutation: fresh-bin redundancy — opening a bin whose leftover
        // duplicates the mean open residual while many bins already fit this
        // item wastes capacity; penalize so existing bins get the item.
        if next_item_size > 0 && fitting_bins_count >= 3
            && new_left >= next_item_size
            && ((new_left as f64) - mean_residual).abs() <= 4.0 {
            score += 1.0 + 1.0 * progress;
        }
        // G158 mutation: existing-bin near-perfect closing — an existing bin
