        // regardless of next-item chaining; deepen the reward slightly.
        if bin_residual != bin_capacity && post_residual > 0 && post_residual <= 4 {
            score -= 0.8 + 0.8 * progress;
        }
        // G158 mutation: dead-space ratio guard — an existing bin whose
