        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 0.5 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 1.0 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 5 && tail <= 40 {
                score -= 0.6 + 0.6 * progress;
            }
        }
        if post_residual == 0 && next_item_size > 0 {
            score -= 1.0 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 2 {
            let near = (post_residual - next_item_size) as f64 / (next_item_size.max(1) as f64);
            score += near * 1.2;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            if (post_residual as f64) < mean_residual * 0.5 {
                score += (next_item_size - post_residual) as f64 * 0.06;
            } else {
                score -= 0.4;
            }
        }
        if progress > 0.8 && post_residual == 0 {
            score -= 2.0 + 2.0 * (progress - 0.8) * 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= next_item_size {
                score -= 1.0 + 1.2 * progress;
            } else if tail > 0 && (tail as f64) < mean_residual * 0.35 && fitting_bins_count >= 2 {
                score += 0.6 + 0.6 * progress;
            }
        }
        if open_bins_count >= 5 && post_residual <= 4 {
            score -= 1.5 + 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 3 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && fitting_bins_count >= 1 {
            score -= 1.2 + 1.2 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap_frac = (next_item_size - post_residual) as f64 / (next_item_size.max(1) as f64);
            score += gap_frac * gap_frac * (3.0 + 3.0 * (1.0 - progress));
            if (post_residual as f64) >= mean_residual * 0.7 {
                score -= 0.8 + 0.8 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_len = post_residual / next_item_size;
            if chain_len >= 3 {
                score -= (0.5 * (chain_len - 1) as f64).min(2.5) + 0.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.6 {
            score -= 1.5 + 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail == next_item_size / 2 && tail >= 3 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 2 && next_item_size >= 15 {
                score += 2.0 + 1.5 * progress;
            }
        }
        if progress > 0.85 && post_residual > 0
            && (post_residual as f64) / (bin_capacity.max(1) as f64) <= 0.05 {
            score -= 2.0;
        }
        // G158 mutation: existing-bin sliver closing — an existing bin left
        // with <= 3 after placement is near-perfect compaction; deepen the
        // reward so near-full bins beat bins leaving 5-15 dead space.
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.0 + 1.0 * progress;
        }
        // G158 mutation: mid-dead-space penalty gradient — existing bins
        // leaving 10-25 unused after placement (with next item unable to
        // chain) are the primary source of waste; graded penalty scaled by
        // how far the leftover exceeds the mean residual.
        if next_item_size > 0 && post_residual >= 10 && post_residual <= 25
            && post_residual < next_item_size {
            let excess = (post_residual as f64 - mean_residual).max(0.0);
            score += 0.06 * excess;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: prefer using existing bins; penalize spreading across many bins.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: make empty bins attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Progress pressure: as stream advances, discourage leaving scattered small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * progress;
    }

