        0 => score += 8.0,                    // near-perfect fill -> reward
        1 => score -= 2.0,                    // quarter-left: usable
        2 => score += 1.5,                    // half-left
        3 => score += 3.0,                    // three-quarter left
        _ => {}                               // empty-ish bin
    }

    // Exact-fill bonus: post_residual zero is ideal
    if pr == 0 {
        score -= 25.0;
    }

    // Modulo coupling: does next_item_size fit harmonically into post_residual?
