        let nxt = next_item_size;
        if nxt <= pr {
            // next item fits exactly into the new residual -> strong reward
            if pr % nxt == 0 {
                score -= 6.0;
            } else {
                score -= 2.0;
            }
            // next item fits into the harmonic class of residual
