    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: if next item exactly fills post_residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 60.0 - slack * 3.0;
            } else {
                score += slack * 0.5;
            }
        } else {
            // Next item cannot fit here; residual becomes dead space relative to next item.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: prefer minimal residual.
        score -= 30.0;
    }

    // Compare residual against mean residual across open bins: prefer bins
    // with residuals near/below the mean (well-filled bins).
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly prefer using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless no good fit exists.
    if bin_residual == bin_capacity {
        score += 90.0;
        // Opening a new bin is acceptable if the item is large and would leave
        // a very awkward residual in existing bins.
        if item_size >= bin_capacity / 2 && post_residual <= 10 {
            score -= 100.0;
        }
        // Fewer open bins relative to progress: new bin is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
    }

    score
}

