pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    score -= 2.0 * (1.0 - (post_residual as f64) / cap).powi(3) * 20.0;

    // Perfect/near-perfect closure reward.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 8.0;
    } else if post_residual < 20 {
        score -= 3.0;
    }

    // Lookahead: reward if the next item fits into the post-residual (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // Reward proportional to how snugly next item would fit.
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // Dead space for the known next item: penalize.
            score += 3.0 * (nxt - pr) / cap;
        }
        // Reward if next item exactly closes the bin.
        if (post_residual as u32) == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize bins whose residual is far from mean residual (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer using already-open bins over opening new ones, especially late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty that grows with progress and open bins.
        score += 18.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
        // Exception: large items are hard to place later; allow new bin for big items.
        if item_size >= 60 {
            score -= 22.0;
        }
        // If many bins are open with low mean residual, opening a fresh bin is fine.
        if mean_residual < 30.0 && open_bins_count > 3 {
            score -= 10.0;
        }
    } else {
        // Reusing an open bin reduces bin count: reward.
        score -= 5.0;
        // Extra reward when bin count is high (consolidation pressure).
        score -= 0.1 * open_bins_count as f64;
    }

    // Early stream: be lenient, allow spreading to create future fit options.
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 6.0;
    }

    // Small penalty for leaving awkward residuals (prime-like gaps ~ hard to fill).
    let pr = post_residual;
    if pr >= 40 {
        score += 2.0; // large leftover is fine actually; mild
        score -= 4.0; // net: large residual is flexible, slight reward
    }

    score
