        0 => 60.0,
        1 => 30.0,
        2 => 12.0,
        3 => 4.0,
        _ => 0.0,
    };

    // Perfect fit reward: modulo arithmetic on capacity fractions.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0; // leftover aligns with typical item granularity
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if next item fits the post residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item can't use this bin's leftover: mild penalty proportional to gap
