    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer fuller bins relative to mean residual of open bins.
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            -50.0
        } else {
            let best_alt = 10.0 * fitting_bins_count as f64;
            best_alt.min(45.0)
        };
