        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big-next-item: fresh bin may absorb chain
        }
    }

    // Slight stream-progression tiebreak to diversify bin states.
    score += 0.01 * (step_index as f64 / total_items.max(1) as f64);

