pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, min item size) are pure waste.
    if post_residual < 10 {
        score -= 60.0; // perfect-ish fit, strongly favored
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 35 {
        score -= 3.0;
    } else if post_residual <= 60 {
        // medium dead space: mild penalty on top of raw residual
        score += 8.0;
    } else {
        // large gap left behind: squandering a big residual on a small item
        score += 25.0 + 0.2 * (post_residual as f64 - 60.0);
    }

    // Tight-fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
