        let dead = post_residual as f64 / bin_capacity as f64;
        score += 60.0 * dead * dead;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: reward if the next item fits exactly into the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
