    score += 6.0 * progress_gain;

    // Reward tight fits: subtract when post_residual is small relative to item size.
    let tightness = (cap - pr).max(1.0) / cap;
    score -= 4.0 * tightness * tightness * (isz / cap);

    // Interaction with mean residual of open bins: if this bin's residual deviates
    // strongly below the mean, placing here balances residual distribution.
    let mean_res = mean_residual.max(0.0);
    let dev = (bin_residual as f64 - mean_res) / cap;
