    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate handling: an empty bin has pr = cap - item_size, which is
    // large; the quadratic base already penalizes it. Add extra guard so a new bin
    // is only chosen when no open bin offers a decent fit.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 10.0 + 20.0 * progress - 0.02 * fitting_bins_count as f64 * (fitting_bins_count as f64);
    }

