    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 30.0;
    }
    // Mid-size awkward gaps (10..=20) get a milder penalty.
    if post_residual >= 10 && post_residual <= 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Lookahead synergy: reward if the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            score -= 40.0;
        } else {
            // next item cannot use this bin's leftover: penalize leftover more
