pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // 2-step lookahead: if the next item fits exactly in the post residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        if diff == 0 {
            score -= 40.0;
        } else {
            score += diff as f64 * 0.5;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: penalize dead space creation.
        score += 10.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Penalize opening a new bin mildly when open bins exist that fit decently.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0;
    }

    score
}

