    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it expensive unless we have many open bins
    // already (consolidation pressure) or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 45.0;
        penalty -= 20.0 * (open_bins_count as f64 / 8.0).min(1.0);
        penalty -= 10.0 * progress;
        score += penalty.max(5.0);
    }

    // Mild global pressure: prefer fuller bins relative to the fleet mean.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

