pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically < 12) are wasted capacity -> heavy penalty.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (1.0 - post_residual as f64 / 12.0);
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 15.0 * tightness * tightness;

    // Lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 12 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this bin's leftover -> mild penalty for hoarding space
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer packing into existing bins,
    // penalize opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when mean residual is small
        // (existing bins nearly full) or item is large and fits nowhere well.
        score += 25.0 + pressure;
        score -= 0.6 * mean_residual;
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
    } else {
        score -= pressure.min(15.0);
    }

    // Prefer bins whose residual is close to mean (balanced packing).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

