pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small divisors: prefer residuals
    // that fall into "usable" classes (small multiples of common item sizes).
    let pr = post_residual;
    // Perfect fit bonus
    if pr == 0 {
        score -= 60.0;
    }
    // Dead-space penalty: residual too small for the smallest plausible item
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Modulo-10 classes: residuals that are multiples of 10 keep future pairing options
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    } else if pr % 10 != 0 {
        score += 3.0;
    }
    // Modulo-5 refinement
    if pr % 5 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Capacity fraction thresholds: penalize leaving residual in awkward bands
    let cap_f = bin_capacity as f64;
    let pr_f = pr as f64;
    if pr_f > 0.5 * cap_f {
        score -= 5.0; // roomy leftover is fine
    } else if pr_f < 0.2 * cap_f {
        score += 6.0; // cramped leftover risks dead space
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            // next item fits: mild reward scaled by how much slack remains
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 - 0.15 * slack;
            // harmonic class: next item + residual divisible classes
            if (pr % next_item_size.max(1)) == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += 0.05 * pr_f;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many open bins: discourage spreading; prefer tight fills
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_f = open_bins_count as f64;
    score += 0.02 * open_f * (1.0 - progress);

    // Deviation from mean residual: prefer bins below mean (tighter bins)
    score += 0.3 * (mean_residual - pr_f);

    // New-bin candidate handling: empty bin gets a neutral-ish baseline so it's
    // chosen only when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 40.0 + 0.1 * open_f;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a new bin is attractive if item + next item pair well
            if item_size + next_item_size <= bin_capacity {
                score -= 15.0;
            }
        }
        if fitting_bins_count <= 1 {
            score -= 25.0; // open bins nearly exhausted -> new bin is fine
        }
    }

    score
}

