}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < f64::EPSILON;

    // Base: minimize wasted residual, with a non-linear (quadratic) penalty on dead space.
    let mut score = pr + 0.9 * (pr / cap) * (pr / cap) * cap;

    // Smooth reward for tight fits: coupling of item size and post-residual.
    let tightness = item_size as f64 / cap;
    score -= 18.0 * tightness * (1.0 - pr / cap) * (1.0 - pr / cap);

    // Non-linear progress coupling: early on, tolerate larger residuals less
    // (favor consolidation); later, favor leaving room shaped for future items.
    score *= 1.0 + 0.25 * progress * (pr / cap);

    // Lookahead shaping: reward residuals that still fit the next item,
    // penalize residuals that waste space relative to the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: opening a new bin is attractive when existing bins
    // are crowded (high mean residual) or few bins fit the item.
    if is_new_bin {
        let crowding = mean_residual / cap;
        score -= 12.0 * crowding * crowding;
        if fitting_bins_count > 0 {
            score += 10.0 * (1.0 - 1.0 / fitting_bins_count as f64);
        }
        // Early stream: opening bins cheaply builds capacity; late stream: consolidate.
        score += 10.0 * progress;
    }

    score
}

