    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "usable slot" classes.
    let post = post_residual;
    let residue = post % 10;
    // Dead space penalty: residuals that cannot hold small items (min size 1) are fine,
    // but residuals in awkward bands (just below common item sizes) are penalized.
    // Class the residual by integer division into harmonic buckets.
    let class = post / 10; // 0..=10
    // Harmonic weighting: residual value discounted by class rarity
    score += match class {
        0 => 0.0,                 // tiny residual, essentially full bin - great
        1 => 2.0,                 // 10-19: usable by small items
        2 => 1.0,                 // 20-29
        3 => 3.0,                 // 30-39: awkward zone
        4 => 1.5,
        5 => 2.5,
        6 => 1.0,
        7 => 2.0,
        8 => 1.0,
        9 => 1.5,
        _ => 0.0,                 // near-empty bin
    };
    // Fine-grained residue penalty: residues just below multiples of 10 are wasteful
    if residue >= 1 && residue <= 4 {
        score += 1.5;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;
        } else if next_item_size <= post {
            // reward proportional to how tightly next item fits
            let slack = (post - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic class of (post - next): perfect pairing classes
            let pc = (post - next_item_size) % 10;
            if pc == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this residual: penalize leaving large residual
            score += (post as f64) * 0.15;
        }
    } else {
        // last item: prefer fullest bin
        score -= 5.0;
    }

