        score -= 4.0;
    }

    // Stream progression: late in stream, close out bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (bin_capacity - post) as f64 / bin_capacity as f64;

    score
}

