    // prefer packing into them (they have less residual to waste).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default score so that
    // only genuinely poor fits in open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
