pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: prefer small post-residual relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain placement
        } else if next_item_size <= post_residual {
            // reward proportional closeness of next item to remaining space
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * ratio;
        } else {
            // next item cannot fit: penalize dead space that is too small to be useful
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 25.0;
            } else {
                score += 10.0 * (1.0 - waste / 100.0);
            }
        }
    }

    // Compare against mean residual across open bins
