        score -= 35.0;
    }

    // Penalize opening a new bin when many bins are open and could fit
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if post_residual large and few alternatives
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else if next_item_size > 0 && next_item_size >= post_residual.max(item_size) {
            score -= 15.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Slight preference for compact bins (small residual before placement)
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

