pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Perfect chain: post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 10.0;
    }

    // Last-chance bin bonus: only bin that fits -> avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, opening bins is cheap; later, consolidate.
        score += 18.0 - 12.0 * progress;
        if fit_ratio > 0.7 {
            score += 20.0; // existing bin fits well; don't open new
        }
        if mean_residual < item_size as f64 {
            score -= 10.0; // no open bin can really help
        }
    }

    // Mild penalty when this bin is far above mean residual (wasteful choice).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Prefer using bins with small residual overall (best-fit flavor).
    score += 0.1 * bin_residual as f64 * (1.0 - fit_ratio);

    score
}

