            0 => score += 25.0,                 // tiny unusable sliver -> penalize
            1..=4 => score -= 6.0 * band as f64, // 10..=40 leftover: good future fit
            5 => score -= 30.0,                  // exactly 50: golden residual
            6..=8 => score -= 10.0,              // 60..=80: roomy, fine
            _ => score -= 2.0,                   // near-empty bin placement
