    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;
    score += 0.1 * (bin_residual as f64);

    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.75 {
        score -= 4.0;
    }

    let exact_gap = bin_residual.saturating_sub(item_size);
    if exact_gap <= 2 {
        score -= 5.0;
    } else if exact_gap <= 5 {
        score -= 2.0;
    } else if exact_gap <= 9 {
        score -= 1.0;
    }

    if bin_residual != bin_capacity && post_residual <= 2 && item_size as f64 >= bin_residual as f64 * 0.9 {
        score -= 1.5 + 1.0 * progress;
    }

    if bin_residual == bin_capacity {
        let new_left = bin_capacity.saturating_sub(item_size);
        let big_item = item_size > bin_capacity / 2;
        let scarce = fitting_bins_count <= 1;

        if big_item && scarce {
            score -= 4.0;
        } else if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 2 {
            score -= 1.0;
        } else if item_size >= 40 && (fitting_bins_count == 0 || (item_size > bin_capacity / 3 && next_item_size > bin_capacity / 2)) {
            score -= 2.0;
        } else {
            score += 14.0;
        }

        if next_item_size > 0 && new_left == next_item_size && fitting_bins_count >= 1 {
            score -= 5.0;
        }
        if next_item_size > 0 && new_left < next_item_size && new_left < 15 && fitting_bins_count >= 1 {
            score += 3.0;
