    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual (capacity = 100) ---
    // Class bins into harmonic bands: 0 (perfect), 1-10 (near-perfect),
    // 11-30 (usable), 31-60 (awkward), >60 (wasteful).
