    if pr == 0 {
        score -= 50.0; // perfect fit: extremely desirable
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 30 {
        score -= 8.0;
    } else if pr <= 60 {
        score += 5.0;
    } else {
        score += 12.0;
    }

    // Modulo-10 class of the dead space: residues divisible by 10 align with
    // the coarse item grid and are more reusable.
    let m10 = (pr % 10) as f64;
    score -= 1.5 * (5.0 - (m10 - 5.0).abs()) / 5.0 * 2.0; // reward m10 near 0 or 10

