pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space strongly (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill bonus
    }
    if post_residual > 50 {
        score += 3.0; // large leftover less useful later
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this leftover: penalize small awkward leftovers
            score += 2.0;
        }
    }

    // Global state coupling: when many bins are open, prefer consolidating into tight fits
    // (reduce fragmentation); when few bins are open, new bins are cheap.
    let open_pressure = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).min(10.0);
    score -= 0.4 * open_pressure * fit_ratio;

    // Time horizon: early in the stream, be more willing to open new bins (spread load);
    // late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 4.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 3.0 * fit_ratio;

    // New-bin candidate handling: an empty bin has full residual; make it attractive only
    // when existing bins would leave very wasteful residuals.
    if bin_residual == bin_capacity {
        let best_existing_waste = (fitting_bins_count > 0) as u8 as f64;
        let waste_penalty = 8.0 * best_existing_waste;
        // Base new-bin score: post_residual = capacity - item_size, naturally large.
        // Bonus for big items that would fragment any bin badly.
        if item_size >= 70 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= waste_penalty + 5.0; // no choice anyway
        } else {
            // compete fairly: new bin only wins if existing fits are poor
            score += 2.0;
        }
    }

    // Mild mean-residual awareness: if average residual is high, tightening one bin helps.
    score -= 0.05 * mean_residual * fit_ratio;

    score
}

