        score -= 40.0; // perfect fit is excellent
    } else if r < 10 {
        score += 60.0; // unusable dead space
    } else if residue10 == 0 {
        score -= 12.0; // decadic harmony: divisible by 10 leaves clean chunks
    } else if residue25 == 0 {
        score -= 8.0; // quarter-class harmony
    } else if r <= 20 {
        score += 15.0; // small awkward remainder
    }

    // Integer-division thresholds: how many "units of 25" remain
    let units25 = r / 25;
    score -= 6.0 * units25 as f64;

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let nr = (post_residual - next_item_size) as i64;
            // reward more if the follow-up residual is also harmonious
            if nr % 10 == 0 {
                score -= 20.0;
            } else if nr < 10 {
                score += 10.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize mildly, more if this bin becomes dead
            if post_residual < 10 {
                score += 25.0;
            } else {
                score += 5.0;
            }
        }
    }

    // Last-chance logic: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: opening a bin is attractive only when the item
    // is large relative to capacity or existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        // fresh bin: post_residual == capacity - item_size
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base attractiveness for a fresh bin scaled by item size fraction
        score -= 10.0 + 30.0 * (item_size as f64 / bin_capacity as f64);
        // Late in the stream, prefer compacting into open bins
        score += 25.0 * progress;
        // If many open bins and mean residual is small, avoid opening new bins
        if mean_residual < item_size as f64 {
            score += 40.0;
        }
        // If no open bin fits (fitting_bins_count counts open fitting bins),
        // the fresh bin is the only option; make it very attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin: mild bonus for keeping bin count low when many bins open
        score -= (open_bins_count.min(20) as f64) * 0.5;
        // Prefer bins whose residual is close to the item (tight fit)
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += 20.0 * tightness;
    }

    // Mean-residual alignment: bins deviating far below the mean are already
    // fragmented; discourage dumping items there.
    let dev = mean_residual - bin_residual as f64;
    if dev > 20.0 {
        score += 8.0;
    } else if dev < -20.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
