pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical future
    // items (below the minimum plausible item size) are pure waste.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        // Perfect fit zone: strongly reward leaving nothing usable wasted.
        score -= 40.0 * (1.0 - (post_residual as f64) / dead_threshold.max(1.0));
    } else {
        // Penalize residual mass that can never be filled by the next item.
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            score += 0.5 * (post_residual as f64 - dead_threshold).max(0.0);
        }
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * (open_bins_count as f64) * (1.0 - tightness);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin — prefer filling it to keep large residuals open.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.05 * residual_gap;

    // New-bin candidate handling: an empty bin should only win when the fit
    // into open bins would be poor (large post_residual in open bins).
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * (open_bins_count as f64);
        // Early in the stream, opening fresh bins is cheaper.
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: if the next item exactly fills this bin's post_residual, reward strongly.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
