pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item exactly (chain placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards; reward proportional closeness.
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item will NOT fit in this bin's leftover: penalize
            // dead space that the lookahead cannot use.
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.5 * unusable;
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer bins that are already relatively full (small residual).
    let resid = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = resid / mean_residual;
        if rel < 0.5 {
            score -= 80.0 * (0.5 - rel);
        } else if rel > 1.5 {
            score += 40.0 * (rel - 1.5);
        }
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when nothing else fits well.
    if bin_residual == bin_capacity {
        // Base penalty so an open bin with decent fit is preferred.
        score += 60.0;
        // But if there are no fitting open bins at all, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        // Early in the stream, spreading load across bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 {
            score -= 40.0 * (0.3 - progress);
        }
        // If the next item is large, keeping a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 30.0;
        }
    }

    // Mild penalty for opening many bins relative to items seen.
    if open_bins_count as f64 > (step_index as f64 * 0.7).max(1.0) {
        score += 15.0;
    }

    score
}

