    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Reward filling the bin deeply (high fill ratio)
