    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: quadratic dead-space penalty on post residual
    let mut score = pr + 0.9 * pr * norm_pr;

    // Smooth non-linear coupling with stream progress:
    // late in the stream, tight fits matter more (dead space costlier)
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Reward filling bins that are nearly full, modulated by progress
    score -= 8.0 * (norm_pr * norm_pr) * (1.0 - progress);

    // Last-chance bin bonus (avoid opening new bin needlessly)
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 6.0 * (1.0 - gap / cap) * (1.0 - progress);
        // perfect lookahead fit
        if pr as u32 == next_item_size {
            score -= 10.0;
        }
    } else {
        // end of stream: strongly prefer minimal residual
        score += 5.0 * norm_pr;
    }

    // Mild penalty for spreading across many open bins vs mean residual
    score += 0.05 * open_bins_count as f64 * norm_pr;
    // Prefer bins near the mean residual (balance)
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    score
}

