pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that pair well with common sizes get rewards.
    let pr = post_residual;
    if pr > 0 {
        // Perfect closure: bin exactly filled.
        if pr == 0 {
            score -= 50.0;
        }
        // Small dead space is bad; penalize tiny unusable leftovers (< 10).
        if pr < 10 {
            score += 40.0;
        }
        // Harmonic class via integer division thresholds: residuals that can host
        // at least one more plausible item (>=10) are valuable.
        if pr >= 10 {
            score -= 8.0;
        }
        // Modulo arithmetic on capacity: residuals near "nice" fractions of C
        // (C/4, C/2, 3C/4) are structurally reusable.
        let quarter = bin_capacity / 4;
        let half = bin_capacity / 2;
        let three_quarter = 3 * bin_capacity / 4;
        if pr == quarter || pr == half || pr == three_quarter {
            score -= 15.0;
        }
        // Modular resonance: pr divisible by common item granularities.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Pairing bonus: post-residual can exactly host the next item.
        if next_item_size > 0 && pr == next_item_size {
            score -= 20.0;
        }
        // Next item fits with room to spare afterwards: chain bonus scaled by leftover utility.
        if next_item_size > 0 && pr >= next_item_size {
            let after = pr - next_item_size;
            score -= 10.0;
            if after >= 10 {
                score -= (after / 10) as f64 * 2.0;
            }
        }
        // Next item does NOT fit: this bin becomes a dead end for the lookahead; penalize mildly.
        if next_item_size > 0 && pr < next_item_size && pr < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Large items (>= half capacity) are fine in a fresh bin.
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
        // If the item barely fits nowhere well (few fitting bins), fresh bin is acceptable.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Lookahead: if next item is large too, a fresh bin with big current item
        // leaves nothing useful; discourage slightly.
        if next_item_size >= bin_capacity / 2 && item_size >= bin_capacity / 2 {
            score += 10.0;
        }
        // As the stream matures, opening bins early to spread load is less costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    }

    // Prefer filling bins below the mean residual (tighter packs) mildly.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Slight preference for bins with smaller current residual (best-fit flavor).
    score += bin_residual as f64 * 0.02;

    // Many open bins: encourage consolidation by penalizing spread.
    score += open_bins_count as f64 * 0.3;

    score
}

