        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (better fit than average).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.2 * progress);

    // New-bin candidate: only attractive when item fits poorly everywhere else.
