        score += 20.0 + 2.0 * open_bins_count as f64;
        // Early in stream, new bins are cheap (future flexibility); late, expensive.
        score -= 15.0 * (1.0 - progress);
        // If next item is large and this bin is empty, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Slight preference for bins with residual close to item (perfect packing pressure).
    score -= 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

