pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small is good; dead space below 10 is perfect.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 40.0;
    } else if post_residual < 20 {
        score -= 15.0;
    } else {
        // Penalize large leftover space that only small items could fill
        score += (post_residual as f64) * 0.15;
    }

    // Harmonic class: how well does post_residual align with typical item granularity?
    // Residuals divisible by 10 are "reusable" classes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > post_residual {
        // Next item cannot use this residual anyway; leftover is dead weight
        score += (post_residual as f64) * 0.1;
    }

