    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current bin's fit is very loose. Penalize new bins by default.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is large, a fresh bin is fine (large items pair well later)
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, avoid spreading items across many bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.8 {
            score += 15.0;
        }
    }

    // Slight preference for filling bins with below-average residual (balance)
    if bin_residual != bin_capacity {
        let resid_f = bin_residual as f64;
        if resid_f < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    score
}

