        let exact = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 12.0 * (1.0 - exact / (bin_capacity as f64)) ;
        score -= 6.0; // lookahead bonus
    } else if next_item_size > 0 {
        // next item won't fit here: penalize if this bin would be left nearly full anyway
        score += 3.0;
    }

    // Compare post_residual against mean residual across open bins
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 2.5 * (mean_residual - pr) / (bin_capacity as f64);
    } else {
        score += 2.0 * (pr - mean_residual) / (bin_capacity as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize tiny dead space (< 10 unusable) unless post_residual is zero
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Reward tight fills
    if post_residual == 0 {
        score -= 10.0;
    }

    // Slight preference for keeping fewer open bins late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * progress * (open_bins_count as f64 / (bin_capacity as f64));

    // New-bin candidate: make empty bins mildly unattractive unless residuals are bad
    if bin_residual == bin_capacity {
        score += 4.0 + 0.1 * mean_residual;
    }

