        }
        // MUTATION (gen 182): fresh-bin dead-space economy — a fresh bin whose
        // leftover strands the next item by a large margin is wasteful when
        // good existing alternatives exist; penalize proportionally.
        if next_item_size > 0 && fitting_bins_count >= 2 && new_left < next_item_size
            && (next_item_size - new_left) > 6 {
            score += 1.5 + 1.5 * progress;
        }
        // MUTATION (gen 182): existing-bin near-exact-fill lookahead — an open
        // bin whose residual after this item leaves <= 4 units is effectively
        // closed; strong preference to consolidate into it.
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 && fitting_bins_count >= 1 {
