        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            if (post_residual as f64) < mean_residual * 0.5 {
                score += (next_item_size - post_residual) as f64 * 0.06;
            } else {
                score -= 0.4;
            }
        }
        if progress > 0.8 && post_residual == 0 {
            score -= 2.0 + 2.0 * (progress - 0.8) * 10.0;
        }
        // existing-bin two-step chain lookahead.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= next_item_size {
                score -= 1.0 + 1.2 * progress;
            } else if tail > 0 && (tail as f64) < mean_residual * 0.35 && fitting_bins_count >= 2 {
                score += 0.6 + 0.6 * progress;
            }
        }
        // consolidation pressure.
        if open_bins_count >= 5 && post_residual <= 4 {
            score -= 1.5 + 1.0 * progress;
        }
        // exact-fill lookahead.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 3 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        // residual-reuse alignment.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            let tail_dev = ((tail as f64) - mean_residual).abs();
            if tail > 0 && tail_dev <= mean_residual * 0.3 {
                score -= 0.6 + 0.6 * progress;
            } else if (tail as f64) > mean_residual * 2.5 && tail > next_item_size {
                score += 0.5 + 0.5 * progress;
            }
        }
        // dead-space ratio trade-off — an existing bin whose post-fit tail is
        // small relative to the next item's chain capacity is nearly closed.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 6.0 && fitting_bins_count >= 1 && post_residual >= 8 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        // MUTATION (gen 150): late-stream near-closed bin closing bonus.
        if progress > 0.85 && post_residual > 0
            && (post_residual as f64) / (bin_capacity.max(1) as f64) <= 0.05 {
            score -= 2.0;
        }
        // MUTATION (gen 150): exact half-chain bonus for existing bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail == next_item_size / 2 && tail >= 3 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        // MUTATION (gen 182): residual-decay economy — prefer bins whose tail
        // after the next item is small relative to the item stream scale, so
        // the leftover space gets consumed quickly instead of lingering.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && (tail as f64) < next_item_size as f64 * 0.35 && tail <= 12 {
                score -= 0.6 + 0.8 * progress;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: capacity split into 8 bands.
    let frac = post_residual as f64 / bin_capacity as f64;
    let band = (frac * 8.0).floor() as i32;

    // Reward tight fits: residuals in low bands are more usable dead space.
    match band {
        0 => score -= 12.0,
        1 => score -= 6.0,
        2 => score -= 2.0,
        3 => {}
        4 => score += 3.0,
        5 => score += 6.0,
        6 => score += 9.0,
        _ => score += 12.0,
    }

    // Modulo-10 class of post_residual: residuals divisible by 10 pair well
    // with items on a 10-grid; odd/prime residuals are dead space.
    let pr = post_residual as i64;
    if pr % 10 == 0 {
        score -= 5.0;
    } else if pr % 5 == 0 {
        score -= 2.0;
    } else if pr < 10 {
        score += 8.0; // sliver residual, nearly unusable
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item exactly fills remaining space.
            if next_item_size == post_residual {
                score -= 20.0;
            } else if post_residual - next_item_size <= 5 {
                score -= 10.0;
            } else {
                score -= (post_residual - next_item_size) as f64 / 10.0;
            }
        } else {
            // Next item won't fit here; penalize more if this was the only option.
            score += 4.0;
            if fitting_bins_count <= 1 {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: only this bin fits the item — strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented or
    // the item is large relative to typical open-bin space.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= 60 || (pressure < 0.25 && open_bins_count > 0) {
            score += 25.0; // discourage new bin
        } else if frac >= 0.0 {
            // empty bin baseline: slightly worse than a decent fit
            score += 8.0 - 4.0 * progress;
        }
        // large item with no good home: new bin becomes attractive
        if item_size >= 50 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
    }

    // Mild penalty for spreading across too many bins.
    score += open_bins_count as f64 * 0.3;

    // Small reward for filling bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (item_size as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    let r = post_residual as f64;
    let dead_zone = 35.0;
    if r > 0.0 && r < dead_zone {
        let deadness = (dead_zone - r) / dead_zone;
        score += 60.0 * deadness * deadness;
