            }
        }
        // G183: late-stream near-full closing — reward existing bins that
        // fill to >= 95% capacity near the end of the stream.
        if progress > 0.85 && post_residual > 0
            && (post_residual as f64) / (bin_capacity.max(1) as f64) <= 0.05 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 12.0 + (10 - post_residual) as f64;
    } else if post_residual <= 25 {
        score -= 4.0;
    }

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: reward leaving room for the next item; penalize when the
    // residual after placement can no longer host the lookahead item while
    // other placements could.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0;
        }
        // Perfect two-item chaining bonus.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or few bins fit it.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tight = fitting_bins_count <= 1;
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if tight || big_item {
            score -= 5.0;
        } else {
            // Discard wasteful new-bin openings when existing bins fit fine.
            score += 15.0;
        }
    }

    // Time horizon: late in the stream, prefer consolidation into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0 * (post_residual as f64 / bin_capacity as f64);

    // Global residual pressure: if mean residual is high, prefer filling the
    // emptiest bins to consolidate; if low, prefer tight fits (default above).
    if mean_residual > 30.0 && post_residual as f64 >= mean_residual {
        score += 3.0;
    } else if mean_residual > 30.0 {
        score -= 2.0;
    }

    // Mild penalty per open bin to encourage closing bins out.
    score += 0.05 * open_bins_count as f64;

    score
}

