    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex so tight fits are preferred.
    let mut score = pr + 0.5 * pr * norm_pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space matters more -> penalize residual quadratically in progress.
