    score += progress.powi(2) * pr;

    // Mean residual coupling: prefer bins whose residual deviates from mean smoothly.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bonus: if this is the only fitting bin, reward usage smoothly.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr);
    }

