    // Penalize large dead space more as stream progresses
    score -= (1.0 - poly) * (item_size as f64 / cap) * 8.0;

    // Reward tight fits (small post residual) with smooth quadratic term
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * poly;
