    score += 0.05 * (open_bins_count as f64).sqrt();
    score += 0.1 * (mean_residual - pr).abs();

    // New-bin candidate: make it moderately attractive only when item is large
    if bin_residual == bin_capacity {
        score -= 5.0 + 20.0 * (item_size as f64 / cap);
    }

    score
}

