pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // next item fits here afterward: mild bonus proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit after placement: penalize dead space relative to next item
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize large post residuals that create unusable dead space
    // (residual smaller than the minimum item size is pure waste).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Compare against mean residual: prefer bins tighter (smaller residual) than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild penalty for opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    // Early in the stream, allow more new bins; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

