    // Reward tight fits: small post_residual gets a strong bonus.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical items.
    if post_residual < 10 {
        score -= 6.0; // perfect fill, extra reward
    } else if post_residual < 20 {
        score += 2.0;
    }

    // Lookahead: bonus if next item fits into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 + (next_item_size as f64 / 20.0);
        } else {
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: prefer the tightest, mild penalty against waste.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, be more open to spreading load;
    // late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * fit_ratio;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global residual pressure: if mean residual is high, encourage filling bins.
