    // Mild penalty for proliferating bins when a good fit exists.
    if bin_residual < bin_capacity {
        score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);
    }

    // New-bin candidate: only attractive when current item is large and
    // open bins would leave awkward residuals.
    if bin_residual == bin_capacity {
        let awkward = (post_residual as f64 / bin_capacity as f64);
        score += 30.0 - 20.0 * awkward - 15.0 * fit_ratio;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
