    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Open-bins pressure: discourage spreading across many bins unless
    // the fit is genuinely good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Prefer bins whose residual is already below average (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here: mild penalty proportional to gap size
        score += 0.15 * post_residual as f64;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (bin_residual - item_size) >= 0
            && mean_residual >= (item_size as f64 + 20.0);
        if good_fit_exists {
            score += 30.0; // discourage opening a new bin
        } else {
            score -= 5.0; // slight preference to open fresh bin
        }
    }

    score
}

