        if progress > 0.85 && post_residual > 0
            && (post_residual as f64) / (bin_capacity.max(1) as f64) <= 0.05 {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail == next_item_size / 2 && tail >= 3 {
                score -= 1.0 + 1.0 * progress;
            }
        }
        // MUTATION (gen 191): three-deep chain lookahead in existing bins —
        // a residual that hosts the next item thrice is prime compaction.
        if next_item_size > 0 && post_residual >= next_item_size * 3
            && (post_residual - next_item_size * 3) <= 4 {
            score -= 1.5 + 1.5 * progress;
        }
        // MUTATION (gen 191): dead-space trade-off — an existing bin that
        // would strand the next item while its own residual is far below the
        // mean residual is a dead end; penalize relative to alternatives.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && (post_residual as f64) < mean_residual * 0.55 && fitting_bins_count >= 2 {
            score += 1.2 + 1.0 * progress;
        }
    }

    score
}
